    overflow: auto;
}
.subtitle { margin-bottom: 25px; color: var(--text-muted); font-size: 1rem; }

/* 表单输入框样式 - 适配深色模式 */
.form-input { 
    width: 100%; height: 54px; padding: 0 20px; margin-bottom: 15px; 
    border: 1px solid var(--border); border-radius: var(--radius-md); 
    background: var(--bg-main); color: var(--text-main); font-size: 1.1rem;
    transition: 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}
.form-input:focus { 
    outline: none; border-color: var(--primary); 
    background: white;
    box-shadow: none; 
}
.form-group { margin-bottom: 1.5rem; text-align: left; }

/* 全局弹窗表单布局：业务弹窗只声明字段，不重复定义控件外观与断点。 */
.modal-form-grid {
    --modal-form-columns: 2;
    display: grid;
    grid-template-columns: repeat(var(--modal-form-columns), minmax(0, 1fr));
    gap: 12px;
}

.modal-form-grid--3 {
    --modal-form-columns: 3;
}

.modal-form-field {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 6px;
    text-align: left;
}

.modal-form-field > label,
.modal-form-field > .modal-form-label {
    color: var(--text-muted);
    font-size: 0.78rem;
    font-weight: 600;
    line-height: 1.2;
}

.modal-form-field > .form-input {
    width: 100%;
    height: 40px;
    margin: 0;
    padding: 0 12px;
    border-radius: var(--radius-md);
    background: var(--bg-main);
    font-size: 0.88rem;
}

.modal-form-field > select.form-input {
    padding-right: 32px;
}

.modal-form-field > textarea.form-input {
    height: auto;
    min-height: 72px;
    padding: 10px 12px;
    line-height: 1.45;
    resize: vertical;
}

.modal-form-field > .form-input:focus {
    background: var(--bg-main);
}

.modal-form-field--span-2 {
    grid-column: span 2;
}

.modal-form-field--wide {
    grid-column: 1 / -1;
}

.modal-form-check {
    display: flex;
    min-width: 0;
    min-height: 40px;
    align-items: center;
    align-self: end;
    gap: 8px;
    color: var(--text-muted);
    font-size: 0.78rem;
    font-weight: 600;
    text-align: left;
}

.modal-form-check input[type="checkbox"] {
    width: 15px;
    height: 15px;
    margin: 0;
    accent-color: var(--primary);
}

@media (max-width: 820px) {
    .modal-form-grid--3 {
        --modal-form-columns: 2;
    }
}

@media (max-width: 560px) {
    .modal-form-grid {
        --modal-form-columns: 1;
    }

    .modal-form-field--span-2,
    .modal-form-field--wide {
        grid-column: auto;
    }
}

/* 隐藏浏览器原生的密码显示/清除按钮，避免图标冲突 */
input::-ms-reveal,
input::-ms-clear {
    display: none;
}
input::-webkit-contacts-auto-fill-button {
    visibility: hidden;
    display: none !important;
    pointer-events: none;
}

