/* Auth login final wide layout */
#auth-container {
    --auth-ink: #071936;
    --auth-green: #059669;
    --auth-green-soft: #11c583;
    --auth-cyan: #0891b2;
    --auth-muted: #59677d;
    --auth-panel-width: clamp(430px, 29vw, 540px);
    --auth-shell-width: min(1440px, calc(100vw - clamp(52px, 8vw, 160px)));
    padding: clamp(24px, 4vh, 48px) clamp(32px, 5vw, 88px) clamp(34px, 5vh, 58px);
    overflow: hidden;
    background:
        radial-gradient(ellipse at 18% 16%, rgba(16, 185, 129, 0.1), transparent 34%),
        radial-gradient(ellipse at 36% 56%, rgba(20, 184, 166, 0.07), transparent 38%),
        radial-gradient(ellipse at 86% 86%, rgba(6, 182, 212, 0.055), transparent 34%),
        linear-gradient(180deg, #fbfdff 0%, #ffffff 62%, #fbfffd 100%);
    background-size: auto;
}
#auth-container::before {
    content: "";
    position: absolute;
    left: -12%;
    right: -12%;
    bottom: -30%;
    z-index: 0;
    height: clamp(240px, 31vh, 390px);
    opacity: 0.28;
    background:
        repeating-radial-gradient(ellipse at 31% 108%, rgba(5, 150, 105, 0.16) 0 1px, transparent 1px 12px),
        repeating-radial-gradient(ellipse at 72% 116%, rgba(20, 184, 166, 0.1) 0 1px, transparent 1px 18px),
        radial-gradient(ellipse at 48% 105%, rgba(16, 185, 129, 0.1), transparent 64%);
    transform: rotate(-1.2deg);
    transform-origin: center bottom;
    -webkit-mask-image: linear-gradient(to top, rgba(0, 0, 0, 0.8) 0%, rgba(0, 0, 0, 0.42) 44%, transparent 82%);
    mask-image: linear-gradient(to top, rgba(0, 0, 0, 0.8) 0%, rgba(0, 0, 0, 0.42) 44%, transparent 82%);
    pointer-events: none;
}
#auth-container::after {
    content: "";
    position: absolute;
    left: -8%;
    top: -10%;
    z-index: 0;
    width: min(72vw, 980px);
    height: 112%;
    opacity: 0.58;
    background:
        radial-gradient(ellipse at 45% 42%, rgba(16, 185, 129, 0.1), transparent 58%),
        radial-gradient(ellipse at 54% 62%, rgba(6, 182, 212, 0.055), transparent 62%),
        radial-gradient(ellipse at 20% 78%, rgba(5, 150, 105, 0.055), transparent 54%);
