    grid-template-columns: 1fr;
    justify-items: center;
    align-content: center;
    gap: 7px;
    padding: 2px 4px;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    backdrop-filter: none;
    animation: auth-feature-float 6.8s ease-in-out infinite;
}
.auth-feature-node-models {
    left: 8%;
    right: auto;
    top: 13%;
    bottom: auto;
    animation-delay: -0.4s;
}
.auth-feature-node-knowledge {
    left: auto;
    right: 10%;
    top: 10%;
    bottom: auto;
    animation-delay: -1.2s;
}
.auth-feature-node-workflow {
    left: 0;
    right: auto;
    top: 43%;
    bottom: auto;
    animation-delay: -2s;
}
.auth-feature-node-tools {
    left: auto;
    right: 1%;
    top: 45%;
    bottom: auto;
    animation-delay: -0.8s;
}
.auth-feature-node-data {
    left: 10%;
    right: auto;
    top: auto;
    bottom: 6%;
    animation-delay: -2.6s;
}
.auth-feature-node-security {
    left: auto;
    right: 12%;
    top: auto;
    bottom: 9%;
    animation-delay: -1.7s;
}
.auth-feature-node::after {
    display: none;
}
.auth-feature-icon {
    width: clamp(40px, 5vh, 52px);
    height: clamp(40px, 5vh, 52px);
    border-radius: 8px;
    background: linear-gradient(145deg, rgba(255,255,255,0.98), rgba(226,252,239,0.92));
    box-shadow: 0 12px 24px rgba(15, 23, 42, 0.08);
}
.auth-feature-icon svg {
    width: clamp(19px, 2.4vh, 24px);
    height: clamp(19px, 2.4vh, 24px);
}
.auth-feature-node strong {
    font-size: clamp(0.78rem, 1.16vh, 0.9rem);
    line-height: 1.2;
    font-weight: 850;
    white-space: normal;
    text-align: center;
}
.auth-feature-node small {
    display: block;
    margin-top: -4px;
    color: #64748b;
    font-size: 0.7rem;
    line-height: 1.2;
    text-align: center;
}
.auth-orbit {
    position: absolute;
    left: 50%;
    top: 53%;
    z-index: 2;
    width: clamp(235px, 31vh, 360px);
    height: clamp(260px, 36vh, 400px);
    display: block;
    transform: translate(-50%, -50%);
}
.auth-orbit::before,
.auth-orbit::after,
.auth-orbit-ring {
    opacity: 0.64;
}
.auth-orbit-sweep {
    opacity: 0.44;
}
.auth-orbit-platform {
    border-radius: 20px;
}
.auth-hero-logo {
    top: 9%;
    width: clamp(112px, 15vh, 168px);
    height: clamp(112px, 15vh, 168px);
    filter: drop-shadow(0 24px 32px rgba(0, 127, 89, 0.22));
}
.auth-trust-strip,
.auth-showcase-announcements-slot {
    display: none !important;
}
#auth-container .modal.auth-panel {
    align-self: center;
    width: var(--auth-panel-width);
    max-height: min(800px, calc(100dvh - clamp(54px, 8vh, 88px)));
    min-height: min(760px, calc(100dvh - clamp(54px, 8vh, 88px)));
    padding: clamp(32px, 4vh, 52px) clamp(34px, 3.2vw, 56px) clamp(30px, 4vh, 46px);
    border: 1px solid rgba(226, 232, 240, 0.86);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.9);
    box-shadow: 0 34px 90px rgba(15, 23, 42, 0.15);
    backdrop-filter: blur(24px) saturate(160%);
    display: flex;
    flex-direction: column;
    justify-content: center;
}
#auth-container .modal.auth-panel::before,
#auth-container .modal.auth-panel::after {
    display: none;
}
.auth-panel-mark {
    display: block;
    width: clamp(74px, 8.5vh, 108px);
    height: clamp(74px, 8.5vh, 108px);
    object-fit: contain;
    margin: 0 auto clamp(20px, 3vh, 32px);
    filter: drop-shadow(0 18px 26px rgba(0, 127, 89, 0.18));
}
.auth-panel-header {
    margin-bottom: clamp(24px, 3.6vh, 40px);
    text-align: center;
}
.auth-panel-kicker {
    display: none;
}
#auth-container .auth-panel-title {
    font-size: clamp(1.68rem, 3vh, 2.18rem);
    line-height: 1.18;
}
.auth-title-brand {
    gap: 8px;
}
.auth-mode-label {
    margin-top: 10px;
    color: var(--auth-muted);
    font-size: clamp(0.88rem, 1.35vh, 1rem);
    font-weight: 650;
}
.auth-panel-header::after {
    content: "";
    display: block;
    width: 100%;
    height: 1px;
    margin-top: clamp(22px, 3vh, 30px);
    background: linear-gradient(90deg, transparent, rgba(148, 163, 184, 0.44), transparent);
}
#auth-form {
    margin-bottom: clamp(14px, 2vh, 18px);
}
#auth-container .form-input {
    height: clamp(48px, 5.6vh, 56px);
    margin-bottom: clamp(12px, 1.8vh, 18px);
    border-radius: 8px;
    background-color: rgba(255, 255, 255, 0.78);
    border-color: rgba(203, 213, 225, 0.9);
    font-size: clamp(0.92rem, 1.35vh, 1rem);
}
/* 输入框外部包装器与独立图标定义（彻底解决自动填充时图标消失问题） */
.auth-input-wrapper {
    position: relative;
    width: 100%;
    margin-bottom: clamp(12px, 1.8vh, 18px);
}
#auth-container .auth-input-wrapper .form-input {
    margin-bottom: 0 !important;
    padding-left: 50px !important;
}
.auth-input-icon {
    position: absolute;
    left: 18px;
    top: 50%;
    transform: translateY(-50%);
    width: 18px;
    height: 18px;
    color: #64758b;
    pointer-events: none;
    z-index: 2;
    transition: color 0.2s ease;
}
.auth-input-wrapper:focus-within .auth-input-icon {
    color: var(--auth-green);
}
/* 解决自动填充下的背景颜色优化 */
#auth-container .form-input:-webkit-autofill,
#auth-container .form-input:autofill {
    -webkit-box-shadow: 0 0 0px 1000px #eef2ff inset !important;
    -webkit-text-fill-color: var(--auth-ink) !important;
}
#auth-container .auth-password-field .form-input {
    padding-right: 54px !important;
}
#auth-container .btn-toggle-pw {
    right: 12px;
    width: 34px;
    height: 34px;
    border-radius: 8px;
}
#auth-container .btn-primary {
    height: clamp(50px, 5.8vh, 56px);
    border-radius: 8px;
    background: linear-gradient(135deg, #059669 0%, #13b982 100%);
    letter-spacing: 0.02em;
    box-shadow: 0 22px 36px rgba(5, 150, 105, 0.24);
}
.auth-switch-row,
.auth-download-row {
    margin-top: clamp(10px, 1.6vh, 14px);
}
.auth-panel-note {
    margin-top: clamp(24px, 3.6vh, 40px);
    padding: 0;
    border: 0;
    background: transparent;
    justify-content: center;
    text-align: left;
}
.auth-panel-note > span {
    border-radius: 8px;
}
.auth-copyright {
    bottom: clamp(12px, 2.4vh, 24px);
}
@media (min-width: 1680px) and (min-height: 860px) {
    .auth-shell {
        height: min(860px, calc(100dvh - 112px));
    }
    .auth-feature-orbit {
        width: min(100%, 800px);
        min-height: clamp(420px, 48vh, 520px);
    }
    .auth-orbit {
        width: clamp(300px, 34vh, 410px);
        height: clamp(330px, 39vh, 450px);
    }
}
@media (max-width: 1360px) {
    #auth-container {
        --auth-shell-width: min(1240px, calc(100vw - 48px));
        --auth-panel-width: clamp(390px, 32vw, 455px);
        padding-inline: 24px;
    }
    .auth-shell {
        grid-template-columns: minmax(540px, 1fr) var(--auth-panel-width);
        gap: clamp(34px, 5vw, 72px);
    }
    .auth-brand-icon {
        width: clamp(50px, 6.4vh, 68px);
        height: clamp(50px, 6.4vh, 68px);
    }
    .auth-brand-name {
        font-size: clamp(1.72rem, 2.6vw, 2.34rem);
    }
    .auth-showcase-copy h1 {
        font-size: clamp(2.18rem, 4.8vh, 3rem);
    }
    .auth-feature-orbit {
        width: min(100%, 650px);
        height: clamp(340px, 45vh, 460px);
    }
    .auth-feature-node {
        width: clamp(94px, 9vw, 124px);
        padding: 2px 4px;
    }
    .auth-feature-node-models { left: 7%; right: auto; top: 13%; bottom: auto; }
    .auth-feature-node-knowledge { left: auto; right: 8%; top: 11%; bottom: auto; }
    .auth-feature-node-workflow { left: 0; right: auto; top: 43%; bottom: auto; }
    .auth-feature-node-tools { left: auto; right: 0; top: 45%; bottom: auto; }
    .auth-feature-node-data { left: 8%; right: auto; top: auto; bottom: 7%; }
    .auth-feature-node-security { left: auto; right: 10%; top: auto; bottom: 9%; }
}
@media (max-height: 790px) and (min-width: 981px) {
    .auth-shell {
        height: calc(100dvh - 72px);
    }
    .auth-showcase {
        gap: 12px;
    }
    .auth-showcase-copy::before {
        display: none;
    }
    .auth-showcase-copy h1 {
        font-size: clamp(2rem, 4.6vh, 2.68rem);
    }
    .auth-showcase-copy p {
        font-size: clamp(0.92rem, 2vh, 1.06rem);
    }
    .auth-feature-orbit {
        height: clamp(280px, 42vh, 340px);
    }
    .auth-feature-node {
        width: 96px;
        padding: 1px 3px;
        gap: 4px;
    }
    .auth-feature-icon {
        width: 36px;
        height: 36px;
    }
    .auth-feature-icon svg {
        width: 18px;
        height: 18px;
    }
    .auth-feature-node strong {
        font-size: 0.7rem;
    }
    .auth-feature-node small {
        display: none;
    }
    .auth-orbit {
        width: clamp(190px, 29vh, 270px);
        height: clamp(210px, 33vh, 300px);
    }
    .auth-hero-logo {
        width: clamp(88px, 14vh, 126px);
        height: clamp(88px, 14vh, 126px);
    }
    #auth-container .modal.auth-panel {
        min-height: 0;
        padding-block: 26px;
    }
    .auth-panel-mark {
        width: 68px;
        height: 68px;
        margin-bottom: 16px;
    }
    .auth-panel-header {
        margin-bottom: 16px;
    }
    .auth-panel-header::after {
        margin-top: 16px;
    }
    .auth-panel-note {
        display: none;
    }
}
@media (max-width: 980px) {
    #auth-container {
        overflow: auto;
        padding: 18px 18px 42px;
    }
    .auth-locale-control {
        display: none;
    }
    .auth-shell {
        width: min(620px, 100%);
        height: auto;
        min-height: calc(100dvh - 70px);
        grid-template-columns: 1fr;
        align-content: center;
        gap: 18px;
    }
    .auth-showcase {
        height: auto;
    }
    .auth-showcase-brand {
        justify-self: center;
    }
    .auth-showcase-main,
    .auth-showcase-copy {
        justify-items: center;
        text-align: center;
    }
    .auth-showcase-copy {
        transform: none;
    }
    .auth-showcase-copy::before {
        display: none;
    }
    .auth-feature-orbit,
    .auth-trust-strip,
    .auth-showcase-announcements-slot {
        display: none !important;
    }
    .auth-announcements {
        left: 50%;
        right: auto;
        bottom: 22px;
        width: min(520px, calc(100vw - 36px));
        max-height: min(320px, calc(100dvh - 520px));
        transform: translateX(-50%);
        animation: none;
    }
    .auth-announcements-list {
        max-height: 242px;
    }
    #auth-container .modal.auth-panel {
        justify-self: center;
        width: min(456px, 100%);
        min-height: 0;
        max-height: none;
        padding: 30px 28px 26px;
    }
    .auth-panel-mark {
        width: 70px;
        height: 70px;
        margin-bottom: 18px;
    }
}
@media (max-width: 520px) {
    .auth-announcements {
        display: none;
    }
    .auth-brand-icon {
        width: 40px;
        height: 40px;
    }
    .auth-brand-name {
        font-size: 1.22rem;
    }
    .auth-showcase-copy h1 {
        font-size: 1.68rem;
    }
    .auth-showcase-copy p {
        font-size: 0.92rem;
    }
    #auth-container .modal.auth-panel {
        padding: 24px 20px 22px;
    }
    .auth-panel-mark {
        width: 62px;
        height: 62px;
    }
    #auth-container .auth-panel-title {
        font-size: 1.48rem;
    }
}
/* Auth register mode refinement */
#auth-container.is-register-mode {
    --auth-panel-width: clamp(480px, 32vw, 560px);
}
#auth-container.is-register-mode .modal.auth-panel {
    min-height: 0;
    max-height: min(860px, calc(100dvh - clamp(32px, 6vh, 64px)));
    padding: clamp(28px, 3.4vh, 38px) clamp(34px, 3.2vw, 56px) clamp(26px, 3.2vh, 36px);
    justify-content: flex-start;
    overflow: visible;
}
#auth-container.is-register-mode .auth-panel-mark {
    width: clamp(66px, 7.2vh, 88px);
    height: clamp(66px, 7.2vh, 88px);
    margin-bottom: clamp(14px, 2vh, 20px);
}
#auth-container.is-register-mode .auth-panel-header {
    margin-bottom: clamp(18px, 2.5vh, 26px);
}
#auth-container.is-register-mode .auth-mode-label {
    margin-top: 7px;
}
#auth-container.is-register-mode .auth-panel-header::after {
    margin-top: clamp(18px, 2.4vh, 24px);
}
#auth-container.is-register-mode #auth-form {
    width: 100%;
    display: grid;
    gap: clamp(10px, 1.4vh, 14px);
    margin-bottom: clamp(16px, 2vh, 20px);
}
#auth-container.is-register-mode .reg-only:not(.hidden) {
    display: grid;
    gap: clamp(10px, 1.4vh, 14px);
}
#auth-container.is-register-mode .form-input,
#auth-container.is-register-mode .auth-password-field .form-input {
    height: clamp(46px, 5.2vh, 54px);
    margin-bottom: 0;
}
#auth-container.is-register-mode .auth-password-field {
    margin-bottom: 0 !important;
}
#auth-container.is-register-mode #auth-submit {
    flex: 0 0 auto;
    height: clamp(50px, 5.4vh, 56px);
    min-height: 50px;
    margin-top: clamp(2px, 0.8vh, 6px);
}
#auth-container.is-register-mode .auth-switch-row,
#auth-container.is-register-mode .auth-download-row {
    margin-top: 10px;
}
#auth-container.is-register-mode .auth-panel-note {
    margin-top: clamp(22px, 3vh, 30px);
}
@media (max-height: 860px) {
    #auth-container.is-register-mode .modal.auth-panel {
        max-height: calc(100dvh - 28px);
        padding-block: 24px;
        overflow-y: auto;
    }
    #auth-container.is-register-mode .auth-panel-mark {
        width: 64px;
        height: 64px;
        margin-bottom: 12px;
    }
    #auth-container.is-register-mode .auth-panel-header {
        margin-bottom: 14px;
    }
    #auth-container.is-register-mode .auth-panel-header::after {
        margin-top: 14px;
    }
    #auth-container.is-register-mode #auth-form {
        gap: 10px;
        margin-bottom: 14px;
    }
    #auth-container.is-register-mode .form-input,
    #auth-container.is-register-mode .auth-password-field .form-input {
        height: 44px;
    }
    #auth-container.is-register-mode #auth-submit {
        height: 48px;
        min-height: 48px;
    }
    #auth-container.is-register-mode .auth-panel-note {
        display: none;
    }
}
@media (max-width: 980px) {
    #auth-container.is-register-mode {
        padding: 18px 18px 32px;
    }
    #auth-container.is-register-mode .modal.auth-panel {
        width: min(540px, 100%);
        padding-inline: clamp(24px, 6vw, 38px);
    }
}
@media (max-width: 520px) {
    .auth-announcements {
        display: none;
    }
    #auth-container.is-register-mode .modal.auth-panel {
        padding: 22px 18px 20px;
    }
    #auth-container.is-register-mode .auth-panel-mark {
        width: 58px;
        height: 58px;
    }
    #auth-container.is-register-mode .auth-panel-title {
        font-size: 1.4rem;
    }
}


/* === styles/base/sidebar.css === */
.sidebar { 
    --sidebar-width: 336px;
    flex: 0 0 var(--sidebar-width);
    width: var(--sidebar-width);
    min-width: var(--sidebar-width);
    max-width: var(--sidebar-width);
    box-sizing: border-box;
    overflow: hidden;
    background: linear-gradient(180deg, #fafafa 0%, #f8fafc 100%);
    border-right: 1px solid rgba(148, 163, 184, 0.22); 
    box-shadow: inset -1px 0 0 rgba(255,255,255,0.7), 4px 0 18px rgba(15, 23, 42, 0.03);
    display: flex; flex-direction: column; 
    transition: margin-left 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    z-index: 50;
}
.sidebar.collapsed {
    margin-left: calc(var(--sidebar-width) * -1);
}
.sidebar-header { 
    padding: 14px 14px 10px;
    display: flex; flex-direction: column; gap: 8px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.1);
    background: rgba(255, 255, 255, 0.6);
    backdrop-filter: blur(20px) saturate(180%);
    -webkit-backdrop-filter: blur(20px) saturate(180%);
}
.sidebar-header-mobile-bar {
    display: none;
    justify-content: flex-end;
}
.sidebar-mobile-close-btn {
    width: 32px;
    height: 32px;
    display: none;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.8);
    color: var(--text-muted);
    cursor: pointer;
}
.sidebar-mobile-close-btn:hover {
    color: var(--text-main);
    border-color: rgba(148, 163, 184, 0.38);
    background: #fff;
}
.app-brand-mini {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}
.brand-logo-mini {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    object-fit: contain;
}
.brand-text-mini {
    min-width: 0;
    display: inline-flex;
    align-items: baseline;
    gap: 7px;
    font-size: 1.42rem;
    line-height: 1;
    font-weight: 800;
    letter-spacing: 0;
    white-space: nowrap;
}
.brand-text-pivot {
    color: #071936;
    font-weight: 800;
}
.brand-text-cn {
    color: #08a45b;
    font-weight: 800;
}

.desktop-app-menu {
    display: none;
    align-items: center;
    height: 100%;
    padding: 0 8px;
    background: transparent;
    -webkit-app-region: no-drag;
}
body.pivot-desktop-runtime .desktop-app-menu {
    display: inline-flex;
}
.desktop-app-menu-trigger {
    height: 24px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 0 6px;
    border: 1px solid transparent;
    border-radius: 6px;
    background: transparent;
    color: #334155;
    font-size: 0.74rem;
    font-weight: 700;
    cursor: pointer;
    position: relative;
    transition: all 0.15s cubic-bezier(0.4, 0, 0.2, 1);
    -webkit-app-region: no-drag;
    user-select: none;
}
.desktop-app-menu-trigger:hover,
.desktop-app-menu-trigger.is-open {
    background: rgba(241, 245, 249, 0.9);
    border-color: rgba(203, 213, 225, 0.65);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.05);
    color: #0f172a;
}
.desktop-app-brand-logo {
    width: 14px;
    height: 14px;
    object-fit: contain;
    flex-shrink: 0;
    border-radius: 2px;
}
.desktop-app-brand-name {
    font-family: inherit;
    font-weight: 700;
    font-size: 0.75rem;
    letter-spacing: -0.01em;
    color: #1e293b;
    line-height: 1;
    transition: color 0.15s ease;
}
.desktop-app-menu-trigger:hover .desktop-app-brand-name,
.desktop-app-menu-trigger.is-open .desktop-app-brand-name {
    color: #0f172a;
}
.desktop-app-menu-trigger.has-update::after {
    content: '';
    position: absolute;
    top: -2px;
    right: -2px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #0284c7;
    border: 2px solid #ffffff;
    box-shadow: 0 0 0 1px rgba(2, 132, 199, 0.35);
    animation: desktop-menu-update-pulse 2.4s infinite ease-in-out;
}
.desktop-app-menu-trigger.has-update.is-ready::after {
    background: #10b981;
    box-shadow: 0 0 0 1px rgba(16, 185, 129, 0.35);
}
@keyframes desktop-menu-update-pulse {
    0%, 100% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.22); opacity: 0.85; }
}
.desktop-app-menu-popover {
    position: fixed;
    z-index: 2800;
    min-width: 228px;
    max-width: 270px;
    padding: 6px;
    border: 1px solid rgba(226, 232, 240, 0.85);
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.98);
    backdrop-filter: blur(16px);
    box-shadow: 0 14px 36px -4px rgba(15, 23, 42, 0.14), 0 4px 12px rgba(15, 23, 42, 0.06);
    animation: desktop-menu-popover-in 0.14s cubic-bezier(0.16, 1, 0.3, 1);
    -webkit-app-region: no-drag;
}
.desktop-app-menu-popover.hidden {
    display: none !important;
}
@keyframes desktop-menu-popover-in {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}
.desktop-app-menu-section-header {
    padding: 6px 10px 3px;
    font-size: 0.65rem;
    font-weight: 700;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    user-select: none;
}
.desktop-app-menu-item {
    width: 100%;
    height: 30px;
    display: flex;
    align-items: center;
