.chat-tools-menu-panel .chat-rag-scope { flex: 1; width: auto; min-width: 0; height: 28px; font-size: .68rem; }
.chat-tools-menu-panel .chat-tool-status { display: flex; flex: 0 0 auto; max-width: none; margin: 2px 0 0; padding: 3px; }
.chat-tools-menu-panel .chat-tool-status.hidden { display: none; }
