.input-actions.left input[type="checkbox"][id^="chat-"] {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: 0;
    opacity: 0;
    pointer-events: none;
}
.chat-tool-toggle {
    position: relative;
    z-index: 1;
    height: 30px;
    width: 30px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    border: none;
    border-radius: 50%;
    background: transparent;
    color: #64748b;
    box-shadow: none;
    cursor: pointer;
    user-select: none;
    transition: border-color 0.18s ease, color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}
.chat-tool-icon {
    width: 18px;
    height: 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: currentColor;
    transition: color 0.18s ease, transform 0.18s ease;
}
.chat-tool-icon svg {
    width: 18px;
    height: 18px;
    stroke-width: 2.25;
}
.chat-tool-toggle:hover {
    color: var(--primary);
    background: rgba(16, 185, 129, 0.08);
    transform: translateY(-1px);
}
.chat-tool-toggle.is-active,
.chat-tool-toggle[aria-pressed="true"] {
    background: var(--primary);
    color: #fff;
    box-shadow: 0 6px 14px rgba(16, 185, 129, 0.28);
}
.chat-tool-toggle.is-active .chat-tool-icon,
.chat-tool-toggle[aria-pressed="true"] .chat-tool-icon {
    transform: scale(1.04);
}
.chat-rag-scope {
    width: 132px;
    height: 30px;
    margin: 0;
    padding: 0 8px;
    border-radius: 6px;
    font-size: 0.74rem;
    color: var(--text-muted);
    background: var(--bg-secondary);
}
.chat-rag-scope.hidden,
body:not(.chat-rag-scope-open) .chat-rag-scope {
    display: none !important;
}
#chat-rag-enabled[aria-pressed="false"] ~ .chat-rag-scope,
#chat-rag-enabled:not(.is-active):not([aria-pressed="true"]) ~ .chat-rag-scope {
    display: none !important;
}
.chat-tool-toggle::after,
.has-tooltip::after {
    content: attr(data-tooltip);
    position: absolute;
    left: 50%;
    bottom: calc(100% + 10px);
    z-index: 30;
    width: max-content;
    max-width: 240px;
    padding: 6px 9px;
    border: 1px solid rgba(15, 23, 42, 0.08);
    border-radius: 7px;
    background: rgba(15, 23, 42, 0.92);
    color: #fff;
    font-size: 0.72rem;
    font-weight: 500;
    line-height: 1.35;
    white-space: normal;
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.18);
    opacity: 0;
    pointer-events: none;
    transform: translate(-50%, 4px);
    transition: opacity 0.16s ease, transform 0.16s ease;
}
.chat-tool-toggle::before,
.has-tooltip::before {
    content: "";
    position: absolute;
    left: 50%;
    bottom: calc(100% + 5px);
    z-index: 31;
    border: 5px solid transparent;
    border-top-color: rgba(15, 23, 42, 0.92);
    opacity: 0;
    pointer-events: none;
    transform: translate(-50%, 4px);
    transition: opacity 0.16s ease, transform 0.16s ease;
}
.chat-tool-toggle:hover::after,
.chat-tool-toggle:hover::before,
.has-tooltip:hover::after,
.has-tooltip:hover::before {
    opacity: 1;
    transform: translate(-50%, 0);
}
.btn-icon {
    position: relative;
    width: 30px;
    height: 30px;
    background: transparent;
    border: none;
    color: var(--text-muted);
    cursor: pointer;
    padding: 0;
    border-radius: 50%;
    transition: background 0.18s ease, color 0.18s ease, transform 0.18s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}
.btn-icon:hover { background: rgba(15, 23, 42, 0.05); color: var(--primary); transform: translateY(-1px); }
.btn-icon svg { width: 17px; height: 17px; }
.input-wrapper .btn-primary {
    width: 34px;
    height: 34px;
    flex: 0 0 34px;
    padding: 0;
    border-radius: 50%;
    position: static;
    box-shadow: 0 8px 18px rgba(16, 185, 129, 0.24);
}
.input-wrapper #stop-btn {
    display: flex;
    width: 34px;
    height: 34px;
    flex: 0 0 34px;
    padding: 0;
    border-radius: 50%;
    align-items: center;
    justify-content: center;
}

/* 附件预览区域样式 */
.chat-tools-menu-panel .chat-tool-menu-item,
.chat-tools-menu-panel .chat-tool-menu-item.chat-tool-toggle {
    width: 100%; height: auto; min-height: 42px; padding: 7px 9px;
    align-items: center; justify-content: flex-start; gap: 10px;
