.chat-tools-menu-panel .chat-tool-menu-item .chat-tool-menu-icon { flex: 0 0 22px; }


/* === styles/base/attachments.css === */
.attachment-preview {
    display: flex;
    gap: 8px;
    padding: 8px 10px;
    border-bottom: 1px solid var(--border);
    background: rgba(255,255,255,0.6);
    backdrop-filter: blur(5px);
    overflow-x: auto;
    border-top-left-radius: var(--radius-lg);
    border-top-right-radius: var(--radius-lg);
    max-height: 92px;
}
.attachment-preview.hidden { display: none; }
#attachment-user-header.hidden { display: none; }
.attachments-tab #attachment-search-input {
    width: 190px !important;
    height: 34px !important;
    padding: 5px 10px !important;
    margin: 0 !important;
    font-size: 0.86rem !important;
    line-height: 1.2;
}

.upload-progress-card {
    flex: 0 0 74px;
    height: 56px;
    display: grid;
    place-items: center;
    gap: 2px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: #fff;
    padding: 4px 5px;
}

.upload-progress-ring {
    --progress: 0;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background:
        radial-gradient(closest-side, #fff 72%, transparent 73%),
        conic-gradient(var(--primary) calc(var(--progress) * 1%), rgba(148, 163, 184, 0.22) 0);
}

.upload-progress-ring span {
    font-size: 0.58rem;
    font-weight: 700;
    color: var(--text-main);
}

.upload-progress-name {
    width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: center;
    font-size: 0.62rem;
    color: var(--text-muted);
}

.preview-card {
    position: relative;
    width: 74px;
    height: 56px;
    border-radius: 8px; border: 1px solid var(--border);
    background: white; flex-shrink: 0;
    overflow: hidden; animation: slideInUp 0.2s ease-out;
}
.preview-card.file-card {
    width: 120px; height: 56px; padding: 6px 8px;
    display: flex; align-items: center; gap: 8px;
}
.preview-card img { width: 100%; height: 100%; object-fit: cover; }
.preview-card .file-icon { color: var(--primary); flex-shrink: 0; }
.preview-card .file-icon svg { display: block; }
.preview-card .file-name {
    font-size: 0.7rem; color: var(--text-main);
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    min-width: 0;
    padding-right: 12px;
    line-height: 1.15;
}
.preview-card .file-main {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
    flex: 1;
    justify-content: center;
}
.preview-card-local img {
    display: block;
    object-fit: cover;
}
.preview-card.image-card {
    width: 164px;
    height: 64px;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 8px;
}
.preview-image-frame {
    position: relative;
    flex: 0 0 52px;
    width: 52px;
    height: 52px;
    overflow: hidden;
    border: 1px solid rgba(148, 163, 184, 0.26);
    border-radius: 7px;
    background: #f8fafc;
}
.preview-image {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    opacity: 0;
    transition: opacity 0.16s ease;
}
.preview-image-frame.is-ready .preview-image { opacity: 1; }
.preview-image-fallback {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2px;
    padding: 3px;
    color: #64748b;
    background: #f8fafc;
    text-align: center;
}
.preview-image-frame.is-ready .preview-image-fallback {
    opacity: 0;
    pointer-events: none;
}
.preview-image-frame.is-error .preview-image-fallback {
    color: #b45309;
    background: #fffbeb;
}
.preview-image-fallback-icon { display: inline-flex; color: #0f9f83; }
.preview-image-fallback-copy {
    display: grid;
    gap: 1px;
    max-width: 100%;
}
.preview-image-fallback-copy strong,
.preview-image-fallback-copy small {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.preview-image-fallback-copy strong { font-size: 0.55rem; line-height: 1.15; }
.preview-image-fallback-copy small { font-size: 0.5rem; line-height: 1.15; }
.preview-card.image-card .file-main { gap: 3px; }
.preview-card.image-card .file-name { padding-right: 14px; }
.preview-card.image-card .preview-state-badge { align-self: flex-start; }
.preview-state-badge {
    display: inline-flex;
    align-self: flex-start;
    padding: 1px 5px;
    border-radius: 999px;
    background: rgba(16, 185, 129, 0.08);
    color: #047857;
    font-size: 0.58rem;
    line-height: 1.2;
    white-space: nowrap;
}
.remove-preview {
    position: absolute;
    top: 4px;
    right: 4px;
    width: 20px;
    height: 20px;
    display: grid;
    place-items: center;
    cursor: pointer;
    border: 1px solid rgba(248, 113, 113, 0.28);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.92);
    color: #dc2626;
    box-shadow: 0 4px 12px rgba(15, 23, 42, 0.12);
    z-index: 10;
    padding: 0;
    line-height: 1;
    transition: background 0.16s ease, color 0.16s ease, transform 0.16s ease, border-color 0.16s ease;
}
.remove-preview svg {
    width: 11px;
    height: 11px;
    stroke: currentColor;
    stroke-width: 2.2;
    stroke-linecap: round;
    fill: none;
}
.remove-preview:hover {
    background: #ef4444;
    border-color: #ef4444;
    color: #fff;
    transform: scale(1.04);
}
.remove-preview:focus-visible {
    outline: 2px solid rgba(239, 68, 68, 0.3);
    outline-offset: 2px;
}
@keyframes slideInUp {
    from { transform: translateY(10px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
}

