/* 添加模型弹窗样式 */
.model-modal { 
    width: min(500px, 100%);
    max-height: 100%;
    padding: 0;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    border: 1px solid var(--border); box-shadow: var(--shadow-lg);
    background: #ffffff;
}
.model-config-modal {
    width: min(900px, 100%);
    max-height: min(860px, 100%);
}
.model-modal-header { 
    flex: 0 0 auto;
    padding: 18px 24px 14px; background: #f8fafc; 
    border-bottom: 1px solid var(--border); text-align: left; 
}
.model-modal-header h3 { margin: 0; font-size: 1.1rem; color: var(--text-main); line-height: 1.2; }
.model-modal-desc { margin: 4px 0 0; font-size: 0.78rem; color: var(--text-muted); line-height: 1.35; }

.model-form {
    flex: 1 1 auto;
    min-height: 0;
    padding: 18px 24px 18px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    overflow: auto;
    text-align: left;
}
.model-config-modal .model-modal-header {
    padding: 16px 24px 12px;
}
.model-config-modal .model-form {
    padding: 0;
    gap: 0;
    overflow: hidden;
}
.model-config-modal .model-form-scroll {
    flex: 1 1 auto;
    min-height: 0;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px 12px;
    padding: 16px 24px 16px;
    overflow-y: auto;
    scrollbar-gutter: stable;
}
.model-config-modal .model-form-scroll > input[type="hidden"] {
    display: none;
}
.model-config-modal .model-form-row {
    display: contents;
}
.model-config-modal .model-cost-row {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px 12px;
}
.model-config-modal .model-context-row {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px 12px;
}
.model-config-modal .form-item {
    min-width: 0;
}
.model-config-modal .model-id-item,
.model-config-modal .model-full-row,
.model-config-modal .model-modal-actions {
    grid-column: 1 / -1;
}
.model-config-modal .model-scope-units-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 10px 12px;
    align-items: end;
}
.model-config-modal .model-scope-units-row.scope-hidden {
    grid-template-columns: 1fr;
}
.model-form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px 12px; }
.model-form .form-item { display: flex; flex-direction: column; gap: 4px; }
.model-form label { font-size: 0.78rem; font-weight: 600; color: #475569; text-align: left; line-height: 1.2; }
.model-capability-row {
    flex-direction: row !important;
    align-items: center;
