    color: var(--text-muted);
    font-size: 0.7rem;
    line-height: 1.3;
}
.model-capability-icons {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-wrap: nowrap;
    gap: 2px;
    width: 100%;
    overflow: hidden;
}
.model-capability-cell {
    min-width: 64px;
    white-space: nowrap;
    overflow: hidden;
    text-align: center;
}
.model-capability-icons .model-capability-icon {
    width: 17px;
    height: 17px;
    overflow: hidden;
}
.model-capability-icons .model-capability-icon svg {
    width: 10px;
    height: 10px;
    display: block;
    overflow: hidden;
}
.model-capability-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 18px;
    padding: 0 5px;
    border-radius: 5px;
    border: 1px solid rgba(100, 116, 139, 0.2);
    background: rgba(100, 116, 139, 0.08);
    color: #475569;
    font-size: 0.64rem;
    font-weight: 700;
    line-height: 1;
    white-space: nowrap;
}
