    height: 38px;
}
.model-form .form-input:focus { border-color: var(--primary); background: #f0fdf4; }

.model-modal-actions { 
    flex: 0 0 auto;
    display: flex; gap: 10px; margin-top: 8px; 
}
.model-config-modal .model-modal-actions {
    margin-top: 0;
    padding: 12px 24px 14px;
    border-top: 1px solid var(--border);
    background: #fff;
    box-shadow: 0 -8px 18px rgba(15, 23, 42, 0.035);
}
.model-modal-actions button { flex: 1; height: 38px; font-weight: 600; font-size: 0.82rem; }

@media (max-width: 760px) {
    .model-modal-header {
