/* === styles/admin/admin-records.css === */
/* 拆自 admin.css。 */
/* 管理关闭按钮、API 调用日志、用户记录与监控路由弹窗样式。 */
.settings-dialog-close {
    position: absolute;
    z-index: 100;
    height: 34px;
    padding: 0 14px;
    border-color: rgba(239, 68, 68, 0.35);
    color: var(--danger);
}
.settings-panel-close {
    position: static;
    width: 100%;
    height: 38px;
    margin-top: 12px;
    flex: 0 0 auto;
    border-color: rgba(239, 68, 68, 0.35);
    color: var(--danger);
}
.settings-dialog-close {
    top: 22px;
    right: 24px;
}
.api-call-logs-modal {
    width: min(1480px, calc(100vw - 48px));
    max-height: min(760px, calc(100vh - 72px));
    padding: 0;
    overflow: hidden;
}
.api-call-logs-panel {
    display: flex;
    flex-direction: column;
    width: 100%;
    box-sizing: border-box;
    max-height: min(760px, calc(100vh - 72px));
    background: #fff;
}
.api-call-logs-panel .table-container {
    flex: 1;
    min-height: 0;
    max-height: 520px;
}
.api-call-logs-toolbar {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
}
.api-call-logs-toolbar .form-input {
    flex: 0 0 auto;
}
.api-call-logs-header-close {
    height: 34px;
    padding: 0 14px;
    border-color: rgba(239, 68, 68, 0.35);
    color: var(--danger);
}
.api-call-logs-table-wrap {
    overflow-x: hidden !important;
}
.api-call-logs-table {
    table-layout: fixed;
    width: 100%;
    min-width: 0;
}
.api-call-logs-table .col-index { width: 48px; }
.api-call-logs-table .col-time { width: 136px; }
.api-call-logs-table .col-user { width: 92px; }
.api-call-logs-table .col-key { width: 106px; }
.api-call-logs-table .col-model { width: 108px; }
.api-call-logs-table .col-token { width: 66px; }
.api-call-logs-table .col-status { width: 70px; }
.api-call-logs-table .col-content { width: auto; }
.api-call-logs-table th,
.api-call-logs-table td {
    padding: 6px 7px;
}
.api-call-logs-panel .pagination {
    margin-top: 10px;
    padding-top: 10px;
}
.user-records-modal {
    width: min(1500px, calc(100vw - 48px));
    min-width: min(1060px, calc(100vw - 48px));
    max-width: calc(100vw - 48px);
    max-height: min(820px, calc(100vh - 48px));
    padding: 0;
    overflow: hidden;
    resize: horizontal;
}
.user-records-panel {
    display: flex;
    flex-direction: column;
    gap: 14px;
    max-height: min(820px, calc(100vh - 48px));
    padding: 24px;
    background: #fff;
}
.user-records-header {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    align-items: flex-start;
    padding-right: 38px;
}
.user-records-header h3 {
    margin: 0 0 4px 0;
    font-size: 1.1rem;
    color: var(--text-main);
}
.user-records-toolbar {
    display: flex;
    gap: 8px;
    align-items: center;
    flex-wrap: wrap;
    justify-content: flex-end;
}
.user-records-toolbar .form-input {
    width: 260px;
    height: 34px;
    margin: 0;
    font-size: 0.84rem;
    padding: 5px 10px;
}
.user-records-toolbar .btn-secondary {
    height: 34px;
    padding: 0 14px;
}
.user-records-toolbar .user-records-header-close {
    border-color: rgba(239, 68, 68, 0.35);
    color: var(--danger);
}
.user-records-check {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 34px;
    padding: 0 10px;
    border: 1px solid var(--border);
    border-radius: 8px;
    color: var(--text-secondary);
    font-size: 0.82rem;
    white-space: nowrap;
}
.user-records-check input {
    margin: 0;
}
.user-records-table-wrap {
    flex: 1;
    min-height: 0;
    max-height: 650px;
    overflow: auto;
}
.user-records-panel .pagination {
    margin-top: 10px;
    padding-top: 10px;
}
.user-records-table {
    table-layout: fixed;
    min-width: 0;
}
.user-records-table .col-time { width: 150px; }
.user-records-table .col-session { width: 190px; }
.user-records-table .col-model { width: 130px; }
.user-records-table .col-token { width: 92px; }
.user-records-table .col-content { width: auto; }
.user-records-table th,
.user-records-table td {
    padding: 6px 8px;
    font-size: 0.8rem;
}
.user-record-content {
    max-width: 100%;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.record-deleted {
    margin-left: 6px;
    color: var(--danger);
    font-size: 0.72rem;
}

#monitor-routes-modal .modal {
    width: min(1000px, 100%) !important;
    max-height: 100%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    text-align: left;
}
#monitor-routes-modal .table-container {
    flex: 1 1 auto;
    min-height: 0;
    max-height: none !important;
    overflow: auto;
}

#key-modal .modal,
#input-prompt-container .modal,
#rename-container .modal,
#tags-container .modal {
    max-width: 100%;
    max-height: 100%;
}

/* 统计与监控卡片样式 */


/* === styles/admin/admin-tool-policy.css === */
/* 管理员工具策略页。 */
.tool-policy-tab {
    min-height: 0;
}

.tool-policy-tab .settings-page-head {
    margin-bottom: 10px;
}

.tool-policy-board {
    position: relative;
    min-width: 0;
    min-height: 560px;
    border: 1px solid rgba(148, 163, 184, 0.14);
    border-radius: 8px;
    background: #fff;
}

.tool-policy-board-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 12px 14px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
}

.tool-policy-board-head strong {
    flex: 0 0 auto;
    color: var(--text-main);
    font-size: 0.86rem;
}

.tool-policy-board-count {
    flex: 0 0 auto;
    margin-left: auto;
    color: var(--text-muted);
    font-size: 0.72rem;
    line-height: 1.2;
    text-align: right;
    white-space: nowrap;
}

.tool-policy-empty {
    padding: 18px 8px;
    color: var(--text-muted);
    font-size: 0.78rem;
    text-align: center;
}

.tool-policy-empty.is-error {
    color: var(--danger);
}

.tool-policy-tool-shell {
    min-height: 500px;
    padding: 12px;
    overflow: visible;
}

.tool-policy-tool-grid {
    min-width: 0;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    align-content: start;
    gap: 10px;
}

.tool-policy-tool-grid.has-message {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 280px;
}

.tool-policy-tool-grid.has-message .tool-policy-empty {
    width: 100%;
}

.tool-policy-tool-card {
    min-width: 0;
    min-height: 140px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    gap: 7px;
    padding: 10px 12px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 10px;
    background: #ffffff;
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.015);
    transition: transform 0.22s cubic-bezier(0.4, 0, 0.2, 1),
                box-shadow 0.22s cubic-bezier(0.4, 0, 0.2, 1),
                border-color 0.22s ease,
                background-color 0.22s ease;
}

.tool-policy-tool-card:hover {
    transform: translateY(-2px);
    border-color: rgba(16, 163, 127, 0.3);
    box-shadow: 0 8px 16px -4px rgba(15, 23, 42, 0.06), 0 2px 6px -1px rgba(15, 23, 42, 0.02);
}

.tool-policy-tool-card.is-enabled {
    border-color: rgba(16, 163, 127, 0.22);
    background: linear-gradient(180deg, #ffffff 0%, #f7fdfb 100%);
}

.tool-policy-tool-card.is-enabled:hover {
    border-color: var(--primary);
    box-shadow: 0 8px 18px -4px rgba(16, 163, 127, 0.1), 0 2px 6px -1px rgba(16, 163, 127, 0.02);
}

.tool-policy-tool-card.is-disabled {
    border-color: rgba(148, 163, 184, 0.22);
    background: #f8fafc;
    opacity: 0.78;
}

.tool-policy-tool-card.is-stale {
    border-color: rgba(245, 158, 11, 0.3);
}

.tool-policy-tool-card.active {
    box-shadow: inset 3px 0 0 var(--primary), 0 8px 18px -4px rgba(16, 163, 127, 0.1);
}

.tool-policy-tool-card-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 8px;
    min-width: 0;
}

.tool-policy-tool-title {
    min-width: 0;
    display: grid;
    gap: 4px;
}

.tool-policy-tool-title strong {
    display: block;
    min-width: 0;
    overflow: hidden;
    color: var(--text-main);
    font-size: 0.82rem;
    font-weight: 800;
    line-height: 1.25;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.tool-policy-tool-title em {
    justify-self: start;
    max-width: 100%;
    height: 18px;
    padding: 0 6px;
    overflow: hidden;
    border: 1px solid rgba(16, 163, 127, 0.2);
    border-radius: 5px;
    color: var(--primary);
    background: #ecfdf5;
    font-size: 0.64rem;
    font-style: normal;
    font-weight: 800;
    line-height: 16px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.tool-policy-status-toggle {
    flex: 0 0 auto;
    position: relative;
    width: 42px;
    height: 24px;
    padding: 0;
    border: 1px solid rgba(148, 163, 184, 0.34);
    border-radius: 999px;
    background: #f1f5f9;
    cursor: pointer;
    box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.08), 0 1px 1px rgba(15, 23, 42, 0.03);
    transition: border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
}

.tool-policy-status-toggle span {
    position: absolute;
    top: 2px;
    left: 2px;
    width: 18px;
    height: 18px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 999px;
    background: #ffffff;
    box-shadow: 0 2px 5px rgba(15, 23, 42, 0.2);
    transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.tool-policy-status-toggle.is-on {
    border-color: rgba(16, 163, 127, 0.42);
    background: var(--primary);
    box-shadow: inset 0 1px 2px rgba(6, 95, 70, 0.22), 0 1px 2px rgba(16, 163, 127, 0.16);
}

.tool-policy-status-toggle.is-on span {
    transform: translateX(18px);
    border-color: rgba(255, 255, 255, 0.76);
    box-shadow: 0 2px 6px rgba(6, 95, 70, 0.28);
}

.tool-policy-status-toggle:hover {
    border-color: rgba(16, 163, 127, 0.44);
    box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.08), 0 2px 5px rgba(15, 23, 42, 0.08);
}

.tool-policy-status-toggle:disabled {
    cursor: default;
    opacity: 0.62;
}

.tool-policy-tool-card p {
    align-self: stretch;
    margin: 0;
    color: #64748b;
    font-size: 0.7rem;
    line-height: 1.4;
    text-align: left;
    display: -webkit-box;
    line-clamp: 2;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.tool-policy-card-meta {
    align-self: flex-start;
    display: inline-flex;
    max-width: 100%;
    overflow: hidden;
    color: #94a3b8;
    font-size: 0.66rem;
    font-weight: 600;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.tool-policy-tool-card:hover .tool-policy-card-meta {
    color: #64748b;
}

.tool-policy-tool-card footer {
    display: flex;
    align-items: center;
    flex-wrap: nowrap;
    gap: 8px;
    margin-top: 4px;
    min-width: 0;
}

.tool-policy-chip {
    flex: 0 0 auto;
    height: 20px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0 7px;
    border-radius: 999px;
    background: #f1f5f9;
    color: #475569;
    font-size: 0.66rem;
    font-weight: 800;
    line-height: 1;
    white-space: nowrap;
}

.tool-policy-chip.risk-low {
    background: #ecfdf5;
    color: #047857;
}

.tool-policy-chip.risk-medium {
    background: #fffbeb;
    color: #b45309;
}

.tool-policy-chip.risk-high {
    background: #fef2f2;
    color: #b91c1c;
}

.tool-policy-chip.approval-on {
    background: #eff6ff;
    color: #1d4ed8;
}

.tool-policy-chip.package-off {
    background: #f1f5f9;
    color: #64748b;
}

.tool-policy-tool-card footer button {
    flex: 0 0 auto;
    height: 28px;
    margin-left: auto;
    padding: 0 10px;
    border-radius: 6px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    background: #ffffff;
    color: #334155;
    font-size: 0.72rem;
    font-weight: 500;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.02);
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.tool-policy-tool-card footer button:hover {
    border-color: var(--primary);
    color: var(--primary);
    background: #f0fdf4;
    box-shadow: 0 4px 8px -2px rgba(16, 163, 127, 0.08);
}

.tool-policy-switch-control {
    position: relative;
    display: inline-flex;
    flex: 0 0 auto;
    width: 42px;
    height: 24px;
}

.tool-policy-switch-control input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.tool-policy-switch-track {
    position: absolute;
    inset: 0;
    border: 1px solid rgba(148, 163, 184, 0.34);
    border-radius: 999px;
    background: #f1f5f9;
    box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.08), 0 1px 1px rgba(15, 23, 42, 0.03);
    transition: border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
}

.tool-policy-switch-track::after {
    content: "";
    position: absolute;
    top: 2px;
    left: 2px;
    width: 18px;
    height: 18px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 999px;
    background: #fff;
    box-shadow: 0 2px 5px rgba(15, 23, 42, 0.2);
    transition: transform 0.2s ease;
}

.tool-policy-switch-control input:checked + .tool-policy-switch-track {
    border-color: rgba(16, 163, 127, 0.42);
    background: var(--primary);
}

.tool-policy-switch-control input:checked + .tool-policy-switch-track::after {
    transform: translateX(18px);
}

.tool-policy-governance-panel[hidden] {
    display: none !important;
}

.tool-policy-governance-panel {
    position: fixed;
    top: 50%;
    left: 50%;
    z-index: 1200;
    width: min(420px, calc(100vw - 32px));
    max-height: calc(100vh - 72px);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 10px;
    background: #fff;
    box-shadow: 0 18px 36px rgba(15, 23, 42, 0.14);
    transform: translate(-50%, -50%);
}

.tool-policy-governance-head {
    display: flex;
    align-items: flex-start;
    justify-content: flex-start;
    gap: 12px;
    padding: 13px 14px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
    background: #f8fafc;
    text-align: left;
}

.tool-policy-governance-head > div {
    min-width: 0;
    display: grid;
    gap: 3px;
}

.tool-policy-governance-head span {
    color: var(--primary);
    font-size: 0.68rem;
    font-weight: 800;
}

.tool-policy-governance-head strong,
.tool-policy-governance-head small {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.tool-policy-governance-head strong {
    color: var(--text-main);
    font-size: 0.88rem;
}

.tool-policy-governance-head small {
    color: var(--text-muted);
    font-size: 0.68rem;
}

.tool-policy-governance-body {
    display: grid;
    gap: 12px;
    padding: 14px;
    overflow: auto;
    text-align: left;
}

.tool-policy-switch-row {
    min-width: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 10px 12px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: #f8fafc;
    cursor: pointer;
}

.tool-policy-switch-row.is-readonly {
    cursor: default;
    opacity: 0.72;
}

.tool-policy-switch-row > span:first-child {
    min-width: 0;
    display: grid;
    gap: 3px;
}

.tool-policy-switch-row strong {
    color: var(--text-main);
    font-size: 0.78rem;
}

.tool-policy-switch-row small {
    color: var(--text-muted);
    font-size: 0.68rem;
}

.tool-policy-form-field {
    display: grid;
    gap: 6px;
    min-width: 0;
    text-align: left;
}

.tool-policy-form-field > span {
    justify-self: start;
    width: 100%;
    color: #334155;
    font-size: 0.74rem;
    font-weight: 800;
    line-height: 1.2;
    text-align: left;
}

.tool-policy-form-field .form-input {
    width: 100%;
    min-width: 0;
    margin: 0;
    border-radius: 7px;
    font-size: 0.78rem;
    text-align: left;
}

.tool-policy-form-field select.form-input {
    height: 36px;
    padding: 0 34px 0 12px;
    line-height: 34px;
}

.tool-policy-form-field textarea.form-input {
    min-height: 88px;
    padding: 8px 10px;
    line-height: 1.45;
    resize: vertical;
}

.tool-policy-governance-actions {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
}

.tool-policy-governance-actions button {
    height: 32px;
    padding: 0 14px;
}

#pagination-tool-policy:empty {
    display: none;
}

.tool-policy-board #pagination-tool-policy {
    margin: 0;
    padding: 10px 12px;
}

@media (max-width: 620px) {
    .tool-policy-board-head {
        align-items: center;
        flex-direction: row;
    }

    .tool-policy-tool-grid {
        grid-template-columns: 1fr;
    }
}


/* === styles/admin/admin-global-params.css === */
/* 全局参数页专属紧凑布局与样式 (Global Parameters Compact Layout & Aesthetics) */
.global-params-tab {
    width: 100%;
    max-width: 100%;
    display: flex;
    flex-direction: column;
    gap: 10px;
    box-sizing: border-box;
}

/* 顶部操作区状态说明文本 */
.global-params-tab .runtime-settings-status {
    margin: 0;
    font-size: 0.76rem;
    color: var(--text-muted, #64748b);
    line-height: 1.2;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ==========================================================================
   1. 参数卡片主网格 (Compact Card Grid Layout)
   ========================================================================== */
.global-params-tab .global-params-list {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
    max-width: none;
    padding-bottom: 12px;
    width: 100%;
}
@media (max-width: 1360px) {
    .global-params-tab .global-params-list {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (max-width: 860px) {
    .global-params-tab .global-params-list {
        grid-template-columns: 1fr;
    }
}

/* ==========================================================================
   2. 单张卡片紧凑基础样式 (Compact Card Foundation)
   ========================================================================== */
.global-params-tab .global-params-section {
    padding: 10px 12px 10px !important;
    border: 1px solid rgba(226, 232, 240, 0.9);
    border-radius: 9px;
    background: #ffffff;
    box-shadow: 0 1px 4px -1px rgba(15, 23, 42, 0.04), 0 1px 2px rgba(15, 23, 42, 0.02);
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    transition: all 0.18s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
    overflow: hidden;
}
.global-params-tab .global-params-section:hover {
    border-color: #cbd5e1;
    box-shadow: 0 4px 12px -2px rgba(15, 23, 42, 0.06), 0 2px 4px rgba(15, 23, 42, 0.02);
    transform: translateY(-1px);
}

/* 卡片顶部标题栏 (紧凑简洁) */
.global-params-tab .global-params-card-header {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    margin-bottom: 8px;
    padding-bottom: 6px;
    border-bottom: 1px solid #f1f5f9;
}
.global-params-tab .card-header-content {
    min-width: 0;
    flex: 1;
}
.global-params-tab .card-header-content h4 {
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    font-size: 0.84rem !important;
    font-weight: 800;
    color: #1e293b;
    line-height: 1.25;
    text-align: left;
}
.global-params-tab .card-header-content .global-params-section-desc {
    margin: 2px 0 0;
    color: #64748b;
    font-size: 0.68rem;
    line-height: 1.3;
    text-align: left;
    white-space: normal;
    overflow: hidden;
    display: -webkit-box;
