.monitor-empty { color: var(--text-muted); font-size: 0.82rem; padding: 8px 0; text-align: left; line-height: 1.45; }
.monitor-empty.is-warning { 
    color: #92400e; background: #fffbeb; 
    border: 1px solid rgba(245, 158, 11, 0.2); 
