/* === styles/workspaces.css === */
/* 工作区样式入口。保持导入顺序稳定。 */

/* === styles/workspaces/agent/agent-layout.css === */
/* 拆自 agent-base.css。 */
/* Agent 工作台布局、弹窗外壳、面板与配置弹窗布局样式。 */
/* Agent 工作台布局、控件、模板、工具与共享面板样式。拆自 agent.css。 */
.agent-workbench {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
    min-height: 0;
}

.mcp-layout {
    display: grid;
    grid-template-columns: minmax(400px, 460px) minmax(0, 1fr);
    gap: 10px;
    min-height: 0;
}

.agent-modal {
    width: 100%;
    height: 100%;
    padding: 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    text-align: left;
    background: var(--surface);
}

.agent-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 14px 18px 12px;
    border-bottom: 1px solid var(--border);
    background: #fff;
}

.agent-modal-header h3,
.agent-dag-modal-header h3 {
    margin: 0 0 4px;
    font-size: 1.08rem;
    font-weight: 800;
    line-height: 1.25;
    color: var(--text-main);
}

.agent-modal-header p {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.78rem;
    line-height: 1.4;
}

.agent-modal-close {
    flex: 0 0 auto;
    min-width: 72px;
    height: 34px;
    padding: 0 14px;
    font-size: 0.82rem;
    font-weight: 700;
    border-color: rgba(239, 68, 68, 0.35);
    background: #fff;
    color: var(--danger);
    box-shadow: none;
}

.agent-modal-close:hover {
    border-color: var(--danger);
    background: rgba(254, 226, 226, 0.7);
    color: var(--danger);
}

.agent-modal-header-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    flex: 0 0 auto;
}

.agent-modal-header-actions > .btn-secondary:not(.agent-modal-close) {
    height: 34px;
    padding: 0 14px;
    border-radius: 8px;
    font-size: 0.82rem;
    font-weight: 700;
}

.automation-primary-tabs {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 24px;
    min-height: 43px;
    padding: 0 18px;
    overflow-x: auto;
    border-bottom: 1px solid var(--border);
    background: #fff;
    scrollbar-width: none;
}

.automation-primary-tabs::-webkit-scrollbar {
    display: none;
}

.automation-primary-tab {
    position: relative;
    align-self: stretch;
    flex: 0 0 auto;
    padding: 0 2px;
    border: 0;
    background: transparent;
    color: #64748b;
    font-size: 0.82rem;
    font-weight: 700;
    cursor: pointer;
}

.automation-primary-tab::after {
    content: "";
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    height: 2px;
    border-radius: 2px 2px 0 0;
    background: transparent;
}

.automation-primary-tab:hover {
    color: var(--text-main);
}

.automation-primary-tab.active {
    color: var(--primary);
}

.automation-primary-tab.active::after {
    background: var(--primary);
}

.agent-modal > .agent-workbench {
    flex: 1;
    min-height: 0;
    padding: 12px 14px 14px;
    overflow: hidden;
    background: #f8fafc;
}

.agent-history-panel,
.mcp-form,
.mcp-list-wrap {
    border: 1px solid var(--border);
    border-radius: 8px;
    background: #fff;
    padding: 12px;
    min-width: 0;
    overflow: hidden;
}

.mcp-form,
.mcp-list-wrap {
    padding: 12px;
}

.agent-history-panel {
    display: flex;
    flex-direction: column;
    min-height: 0;
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.035);
}

.agent-history-panel {
    display: flex;
    flex-direction: column;
    gap: 0;
    padding: 10px;
}

.agent-task-editor-modal {
    width: min(760px, calc(100vw - 32px));
    max-height: min(860px, calc(100dvh - 32px));
    display: flex;
    flex-direction: column;
    padding: 0;
    overflow: hidden;
    text-align: left;
}

.agent-task-editor-modal .agent-config-modal-head > div {
    flex: 1 1 auto;
    min-width: 0;
    text-align: left;
}

.agent-task-editor-modal .agent-config-modal-head h3 {
    padding: 0;
    text-align: left;
}

.agent-task-editor-modal .agent-config-modal-head span {
    display: block;
    margin-top: 3px;
    overflow: hidden;
    color: var(--text-muted);
    font-size: 0.7rem;
    font-weight: 600;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.agent-task-editor-body {
    display: flex;
    flex: 1 1 auto;
    min-height: 0;
    flex-direction: column;
    gap: 12px;
    overflow: auto;
    padding: 16px;
    background: #fff;
}

.agent-task-editor-body .modal-form-field > span {
    color: var(--text-muted);
    font-size: 0.74rem;
    font-weight: 700;
    line-height: 1.2;
}

.agent-task-editor-modal .modal-form-field > input.agent-title-input {
    width: 100%;
    height: 38px;
    line-height: 1.4;
    font-size: 0.82rem;
    margin: 0;
    padding: 0 12px;
    border-radius: 8px;
}

.agent-task-editor-modal .modal-form-field > textarea.agent-goal-input {
    width: 100%;
    min-height: 112px;
    flex: 0 0 auto;
    resize: vertical;
    line-height: 1.5;
    font-size: 0.82rem;
    margin: 0;
    padding: 10px 12px;
    border-radius: 8px;
}

.agent-task-editor-modal .agent-quick-goals {
    margin: -5px 0 0;
}

.agent-task-primary-fields .agent-model-trigger {
    height: 40px;
    padding: 0 12px;
    font-size: 0.88rem;
}

.agent-task-editor-footer {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 16px 16px;
    border-top: 1px solid var(--border);
    background: #fff;
}

.agent-task-editor-footer > div {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
}

.agent-task-editor-footer .btn-primary,
.agent-task-editor-footer .btn-secondary {
    height: 36px;
    padding: 0 13px;
    border-radius: 8px;
    font-size: 0.78rem;
    white-space: nowrap;
}

.agent-task-editor-foot {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    margin-top: 12px;
}

.agent-collapse-section {
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 8px;
    background: #fff;
    margin: 8px 0;
    overflow: hidden;
    flex: 0 0 auto;
}

.agent-collapse-section summary {
    height: 40px;
    min-height: 40px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 0 12px;
    cursor: pointer;
    list-style: none;
    color: var(--text-main);
    font-size: 0.84rem;
    font-weight: 800;
}

.agent-collapse-section summary::-webkit-details-marker {
    display: none;
}

.agent-collapse-section summary::after {
    content: "";
    width: 7px;
    height: 7px;
    border-right: 1.5px solid #94a3b8;
    border-bottom: 1.5px solid #94a3b8;
    transform: rotate(45deg);
    transition: transform 0.16s ease;
    flex: 0 0 auto;
}

.agent-collapse-section[open] summary::after {
    transform: rotate(225deg);
}

.agent-collapse-section summary small {
    margin-left: auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text-muted);
    font-size: 0.69rem;
    font-weight: 600;
}

.agent-collapse-body {
    padding: 10px;
    border-top: 1px solid rgba(148, 163, 184, 0.16);
    background: #fbfdff;
}

.agent-config-section-store {
    display: none;
}

.agent-inline-settings {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin: 8px 0 0;
    padding: 10px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 8px;
    background: #fbfdff;
}

.agent-inline-settings-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    min-height: 20px;
}

.agent-inline-settings-head strong {
    color: var(--text-main);
    font-size: 0.78rem;
    font-weight: 800;
}

.agent-inline-settings-head span {
