    padding: 12px;
    background: #f8fafc;
}

.agent-config-modal-body .agent-collapse-section {
    margin: 0;
}

.agent-config-modal-body .agent-collapse-section > summary {
    display: none;
}

.agent-config-modal-body .agent-collapse-body {
    border-top: none;
    background: #fff;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-config-modal-body,
#agent-config-modal[data-agent-config-section="results"] .agent-config-modal-body {
    overflow: hidden;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-config-modal,
#agent-config-modal[data-agent-config-section="results"] .agent-config-modal {
    display: flex;
    flex-direction: column;
    width: min(1480px, calc(100vw - 20px));
    height: calc(100vh - 20px);
    max-height: calc(100vh - 20px);
}

body.pivot-desktop-runtime:not(.auth-active) #agent-config-modal[data-agent-config-section="templates"] .agent-config-modal,
body.pivot-desktop-runtime:not(.auth-active) #agent-config-modal[data-agent-config-section="results"] .agent-config-modal {
    height: calc(100vh - 50px);
    height: calc(100dvh - 50px);
    max-height: calc(100vh - 50px);
    max-height: calc(100dvh - 50px);
}

#agent-config-modal[data-agent-config-section="templates"] .agent-config-modal-body,
#agent-config-modal[data-agent-config-section="results"] .agent-config-modal-body {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    height: calc(100vh - 76px);
    max-height: calc(100vh - 76px);
}

body.pivot-desktop-runtime:not(.auth-active) #agent-config-modal[data-agent-config-section="templates"] .agent-config-modal-body,
body.pivot-desktop-runtime:not(.auth-active) #agent-config-modal[data-agent-config-section="results"] .agent-config-modal-body {
    height: calc(100vh - 106px);
    height: calc(100dvh - 106px);
    max-height: calc(100vh - 106px);
    max-height: calc(100dvh - 106px);
}

#agent-config-modal[data-agent-config-section="templates"] .agent-config-modal-body .agent-collapse-section,
#agent-config-modal[data-agent-config-section="results"] .agent-config-modal-body .agent-collapse-section {
    flex: 1;
    min-height: 0;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    min-height: 0;
    max-height: 100%;
    overflow: hidden;
}

.agent-config-modal-body .agent-collapse-results[open] .agent-collapse-body {
    max-height: none;
    min-height: 0;
    overflow: visible;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-collapse-body {
    display: grid;
    grid-template-columns: minmax(360px, 1fr) minmax(300px, 0.72fr);
    grid-template-areas: "templates notifications";
    gap: 14px;
    align-items: stretch;
    padding: 12px;
    height: 100%;
    min-height: 0;
    overflow: hidden;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-template-strip {
    grid-area: templates;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 10px;
    min-width: 0;
    min-height: 0;
    padding: 12px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: #f8fafc;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-template-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(172px, 1fr));
    align-content: start;
    gap: 8px;
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 0;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-template-item {
    min-width: 0;
    max-width: none;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-template-apply {
    min-height: 60px;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-template-notifications {
    grid-area: notifications;
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-width: 0;
    min-height: 0;
    padding: 12px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: #f8fafc;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-template-notifications .agent-ops-list {
    flex: 1;
    min-height: 0;
    max-height: none;
    overflow: auto;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-tool-section-head.compact {
    margin-bottom: 0;
}

#agent-config-modal[data-agent-config-section="templates"] .agent-tool-section-head.compact strong {
    font-size: 0.78rem;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] .agent-collapse-body {
    display: grid;
    flex: 1 1 auto;
    grid-template-columns: minmax(420px, 0.58fr) minmax(300px, 0.42fr);
    grid-template-rows: max-content minmax(0, 1fr);
    grid-template-areas:
        "status status"
        "tools art";
    gap: 14px;
    align-items: stretch;
    padding: 12px;
    height: calc(100vh - 102px);
    min-height: 0;
    max-height: calc(100vh - 102px);
    overflow: hidden;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-runtime-status {
    grid-area: status;
}

#agent-config-modal[data-agent-config-section="results"] .agent-results-panel {
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-width: 0;
    min-height: 0;
    height: 100%;
    max-height: 100%;
    overflow: hidden;
}

#agent-config-modal[data-agent-config-section="results"] .agent-results-tools-panel {
    grid-area: tools;
}

#agent-config-modal[data-agent-config-section="results"] .agent-results-artifacts-panel {
    grid-area: art;
}

#agent-config-modal[data-agent-config-section="results"] .agent-results-panel .agent-tool-section-head.compact {
    flex: 0 0 auto;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-tool-list {
    flex: 1 1 auto;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    justify-content: start;
    align-content: start;
    align-items: start;
    gap: 5px;
    min-height: 0;
    height: auto;
    max-height: none;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding-right: 4px;
    scrollbar-gutter: stable;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-tool-list .agent-tool-chip {
    min-width: 0;
    padding: 5px 6px;
    border-radius: 7px;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-tool-list .agent-tool-select {
    grid-template-columns: 13px minmax(0, 1fr);
    column-gap: 5px;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-tool-list .agent-tool-select input {
    width: 12px;
    height: 12px;
    margin-top: 1px;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-tool-list .agent-tool-chip strong {
    display: block;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 0.66rem;
    line-height: 1.25;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-tool-list .agent-tool-chip strong em {
    height: 14px;
    margin-left: 4px;
    padding: 0 4px;
    vertical-align: 1px;
    font-size: 0.55rem;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-tool-list .agent-tool-chip span {
    display: -webkit-box;
    margin-top: 2px;
    overflow: hidden;
    line-clamp: 1;
    -webkit-line-clamp: 1;
    -webkit-box-orient: vertical;
    font-size: 0.6rem;
    line-height: 1.25;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-tool-list .agent-tool-chip small.agent-tool-owner {
    display: block;
    grid-column: 2;
    margin-top: 2px;
    overflow: hidden;
    color: #64748b;
    font-size: 0.56rem;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
}


#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-artifact-list {
    flex: 1 1 auto;
    grid-template-columns: minmax(0, 1fr);
    justify-content: start;
    align-content: start;
    align-items: start;
    min-height: 0;
    height: auto;
    max-height: none;
    overflow: auto;
    overscroll-behavior: contain;
}

#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-tool-list .empty-state,
#agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-artifact-list .empty-state {
    grid-column: 1 / -1;
}

#agent-config-modal[data-agent-config-section="results"] .agent-tool-section-head.compact {
    margin-bottom: 0;
}

#agent-config-modal[data-agent-config-section="results"] .agent-tool-section-head.compact strong {
    font-size: 0.78rem;
}

#agent-config-modal[data-agent-config-section="results"] .agent-runtime-status {
    margin-bottom: 0;
}

@media (max-width: 900px) {
    .agent-history-toolbar {
        grid-template-columns: 1fr;
    }

    .agent-history-filters {
        grid-template-columns: 112px minmax(0, 1fr);
    }

    #agent-config-modal[data-agent-config-section="templates"] .agent-collapse-body,
    #agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] .agent-collapse-body {
        display: flex;
        flex-direction: column;
        overflow: auto;
    }

    #agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-tool-list,
    #agent-config-modal[data-agent-config-section="results"] .agent-collapse-results[open] #agent-artifact-list {
        max-height: none;
    }

    .agent-workflow-version-item {
        grid-template-columns: 1fr;
        align-items: stretch;
    }

    .agent-workflow-version-actions {
        justify-content: flex-start;
        flex-wrap: wrap;
    }
}

@media (max-width: 720px) {
    .agent-task-editor-modal {
        width: calc(100vw - 20px);
        max-height: calc(100vh - 20px);
    }

    .agent-task-editor-body {
        padding: 12px;
    }

    .agent-task-editor-footer {
        align-items: stretch;
        flex-direction: column;
        padding: 12px;
    }

    .agent-task-editor-footer > div {
        flex-wrap: wrap;
    }
}

@media (max-width: 640px) {
    .agent-modal-header {
        align-items: flex-start;
        flex-direction: column;
    }

    .agent-modal-header-actions {
        width: 100%;
        justify-content: flex-start;
        flex-wrap: wrap;
    }

    .automation-primary-tabs {
        gap: 18px;
        padding: 0 14px;
    }

    .agent-task-editor-modal .agent-policy-controls,
    .agent-task-editor-modal .agent-enterprise-controls,
    .agent-task-editor-modal .agent-context-controls,
    .agent-inline-settings-grid {
        grid-template-columns: minmax(0, 1fr);
    }

    .agent-task-editor-modal .agent-context-notes-field {
        grid-column: auto;
    }
}


/* === styles/workspaces/agent/agent-controls.css === */
/* 拆自 agent-base.css。 */
/* Agent 策略、上下文、模板、计划控件、通知、开关与运行时标签样式。 */
.agent-collapse-results[open] .agent-collapse-body {
    display: flex;
    flex-direction: column;
    gap: 10px;
    max-height: min(360px, calc(100vh - 470px));
    min-height: 220px;
    overflow-y: auto;
    padding: 10px 8px 10px 10px;
}

.agent-config-section-store .agent-collapse-results[open] #agent-tool-list {
    max-height: none;
    overflow: visible;
}

.agent-policy-controls {
    display: grid;
    grid-template-columns: minmax(0, 1.3fr) minmax(112px, 0.7fr);
    gap: 9px;
    align-items: end;
    margin: 0 0 9px;
}

.agent-context-controls,
.agent-schedule-controls {
    display: grid;
    grid-template-columns: 132px minmax(0, 1fr);
    gap: 9px;
    align-items: end;
    margin: 0 0 9px;
}

.agent-schedule-controls {
    grid-template-columns: minmax(0, 1fr) 112px 82px;
}

.agent-enterprise-controls {
    display: grid;
    grid-template-columns: minmax(0, 1.35fr) 88px 72px;
    gap: 9px;
    align-items: end;
    margin: 0 0 9px;
}

.agent-enterprise-controls label {
    display: flex;
    flex-direction: column;
    gap: 5px;
    min-width: 0;
}

.agent-token-budget-help.hidden,
.agent-max-steps-help.hidden {
    display: none;
}

.agent-token-budget-help,
.agent-max-steps-help {
    grid-column: 1 / -1;
    margin: -2px 0 0;
    color: var(--text-muted);
    font-size: 0.7rem;
    line-height: 1.45;
}

.agent-context-controls label,
.agent-schedule-controls label {
    display: flex;
    flex-direction: column;
    gap: 5px;
    min-width: 0;
}

.agent-context-controls label > span,
.agent-schedule-controls label > span {
    color: #475569;
    font-size: 0.7rem;
    font-weight: 700;
}

.agent-context-controls .form-input,
.agent-schedule-controls .form-input {
    height: 34px;
    margin: 0;
    padding: 5px 10px;
    font-size: 0.83rem;
    border-radius: 8px;
}

.agent-context-controls .agent-context-notes-field,
.agent-inline-settings-grid .agent-context-notes-field {
    grid-column: 1 / -1;
}

.agent-context-controls textarea.form-input {
    height: auto;
    min-height: 58px;
    padding: 8px 10px;
    line-height: 1.45;
    resize: vertical;
}

.agent-task-composer-templates-bar {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 8px 10px;
    background: #f8fafc;
    border: 1px solid rgba(226, 232, 240, 0.9);
    border-radius: 8px;
    margin-bottom: 6px;
}

.agent-task-composer-templates-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.composer-templates-label {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: 0.72rem;
    font-weight: 700;
    color: #475569;
}

.btn-text-action {
    background: transparent;
    border: none;
    padding: 0;
    color: var(--primary, #10a37f);
    font-size: 0.72rem;
    font-weight: 600;
    cursor: pointer;
    text-decoration: none;
}

.btn-text-action:hover {
    text-decoration: underline;
}

.agent-template-strip {
    margin: 0 0 10px;
}

.agent-template-list {
    display: flex;
    gap: 6px;
    overflow-x: auto;
    padding: 7px 0 1px;
}

.agent-template-item {
    flex: 0 0 auto;
    min-width: 112px;
    max-width: 160px;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 4px;
    align-items: center;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: #fff;
    padding: 6px 6px 6px 8px;
    text-align: left;
}

.agent-template-item:hover {
    border-color: rgba(16, 163, 127, 0.35);
    background: rgba(16, 163, 127, 0.05);
}

.agent-template-item strong,
.agent-template-item span {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.agent-template-item strong {
    font-size: 0.76rem;
    color: var(--text-main);
}

.agent-template-apply {
    min-width: 0;
    border: 0;
    padding: 0;
    background: transparent;
    color: inherit;
    text-align: left;
    cursor: pointer;
}

.agent-mini-danger {
    height: 22px;
    border: 1px solid rgba(239, 68, 68, 0.28);
    border-radius: 6px;
    background: #fff;
    color: var(--danger);
    font-size: 0.66rem;
    font-weight: 700;
    cursor: pointer;
}

.agent-mini-danger:hover {
    border-color: var(--danger);
    background: rgba(254, 226, 226, 0.72);
}

.agent-template-item span {
    margin-top: 2px;
    font-size: 0.68rem;
    color: var(--text-muted);
}

/* 常用任务模板弹窗 */
.agent-template-dialog {
    width: min(640px, calc(100vw - 32px));
    max-height: min(540px, calc(100vh - 40px));
    padding: 0;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.agent-template-modal-body {
    padding: 14px 16px;
    overflow-y: auto;
    flex: 1 1 auto;
    min-height: 120px;
    max-height: 380px;
    background: var(--bg-secondary, #f8fafc);
}

.agent-template-modal-body .agent-task-composer-templates-bar {
    margin-bottom: 0;
    background: transparent;
    border: none;
    padding: 0;
}

.agent-template-modal-body .agent-template-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 8px;
    overflow-x: visible;
    padding: 2px 0;
}

.agent-template-modal-body .agent-template-item {
    min-width: 0;
    max-width: none;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 6px;
    padding: 8px 10px;
    border: 1px solid var(--border, #e2e8f0);
    border-radius: 6px;
    background: #fff;
    cursor: pointer;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.agent-template-modal-body .agent-template-item:hover {
    border-color: var(--primary, #10a37f);
    box-shadow: 0 1px 4px rgba(16, 163, 127, 0.12);
}

.agent-task-footer-left-actions {
    display: flex;
    align-items: center;
    gap: 8px;
}

.agent-ops-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 10px;
    margin-bottom: 0;
}

.agent-ops-grid > div {
    min-width: 0;
}

.agent-ops-list {
    display: grid;
    gap: 6px;
    max-height: 112px;
    overflow: auto;
    padding-right: 2px;
}

.agent-ops-item {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 5px 7px;
    align-items: center;
    border: 1px solid var(--border);
    border-radius: 7px;
    background: #f8fafc;
    padding: 7px 8px;
    color: var(--text-main);
    text-align: left;
}

button.agent-ops-item {
    cursor: pointer;
}

.agent-ops-item.unread {
    border-color: rgba(16, 163, 127, 0.32);
    background: rgba(16, 163, 127, 0.06);
}

.agent-ops-item strong {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 0.74rem;
}

.agent-ops-item span {
    grid-column: 1 / -1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text-muted);
    font-size: 0.68rem;
}

.agent-ops-item .btn-secondary {
    height: 24px;
    padding: 0 8px;
    font-size: 0.68rem;
    border-radius: 7px;
}

.agent-ops-actions {
    display: flex;
    gap: 5px;
    align-items: center;
}

.agent-ops-actions .btn-secondary,
