    align-items: center;
    justify-content: space-between;
    gap: 8px !important;
    padding: 0 10px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: #f8fafc;
    cursor: pointer;
}

.agent-toggle-field input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.agent-toggle-field > span {
    color: #334155;
    font-size: 0.78rem;
    font-weight: 800;
}

.agent-switch-track {
    position: relative;
    flex: 0 0 auto;
    width: 40px;
    height: 22px;
    border: 1px solid rgba(148, 163, 184, 0.32);
    border-radius: 999px;
    background: #fff;
    box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.08);
    transition: background 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.agent-switch-track::after {
    content: "";
    position: absolute;
    top: 3px;
    left: 3px;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: #cbd5e1;
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.22);
    transition: transform 0.18s ease, background 0.18s ease;
}

.agent-toggle-field input:checked ~ .agent-switch-track {
