    content: '';
    display: inline-block;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: currentColor;
    flex-shrink: 0;
}

.agent-run-status.running {
    background: rgba(14, 165, 233, 0.12);
    color: #0284c7;
}

.agent-run-status.running::before {
    animation: status-badge-pulse 1.4s infinite ease-in-out;
}

@keyframes status-badge-pulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.35; transform: scale(0.7); }
}

.agent-run-status.queued {
    background: rgba(245, 158, 11, 0.12);
    color: #d97706;
}

.agent-run-status.completed {
    background: rgba(16, 185, 129, 0.12);
    color: #059669;
}

.agent-run-status.error {
    background: rgba(239, 68, 68, 0.12);
    color: #dc2626;
}

.agent-run-status.approval_required {
    background: rgba(249, 115, 22, 0.14);
    color: #ea580c;
}

.agent-run-status.completed_with_errors {
    background: rgba(245, 158, 11, 0.14);
    color: #b45309;
}

.agent-runs-goal-wrap {
    display: flex;
    align-items: center;
    gap: 6px;
    min-width: 0;
}

.agent-runs-goal-text {
    display: block;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text-muted, #64748b);
    font-size: 0.74rem;
    cursor: default;
    outline-offset: 2px;
}

.agent-copy-goal-btn,
.btn-link-copy {
    padding: 2px 6px;
    font-size: 0.68rem;
    line-height: 1.2;
    border-radius: 4px;
    border: 1px solid var(--border-color, #cbd5e1);
    background: #ffffff;
    color: var(--text-main, #334155);
    cursor: pointer;
    white-space: nowrap;
    transition: all 0.15s ease;
}

.agent-copy-goal-btn:hover,
.btn-link-copy:hover {
    background: #f1f5f9;
    border-color: #94a3b8;
    color: #0f172a;
}

.agent-run-status.cancelled {
    background: #f1f5f9;
    color: #64748b;
}

/* --- 统一任务工作台：全宽列表与沉浸式详情视图切换 --- */
#agent-tasks-view {
    display: flex;
    flex-direction: column;
    flex: 1 1 auto;
    height: calc(100vh - 107px);
    min-height: 0;
    overflow: hidden;
    padding: 14px 18px 18px;
    background: #f8fafc;
    box-sizing: border-box;
    position: relative;
}

#agent-tasks-view .agent-tasks-master-pane {
    display: flex;
    flex-direction: column;
    flex: 1 1 auto;
    width: 100%;
    height: 100%;
    min-height: 0;
    overflow: hidden;
    background: #fff;
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 14px 16px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04);
}

#agent-tasks-view .agent-tasks-detail-container {
    display: none;
    flex-direction: column;
    flex: 1 1 auto;
    width: 100%;
    height: 100%;
    min-height: 0;
    overflow: hidden;
    background: #fff;
    border: 1px solid var(--border);
    border-radius: 10px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

#agent-tasks-view.has-active-detail .agent-tasks-master-pane {
    display: none;
}

#agent-tasks-view.has-active-detail .agent-tasks-detail-container {
    display: flex;
    animation: agent-detail-fade-in 0.18s ease-out;
}

@keyframes agent-detail-fade-in {
    from { opacity: 0; transform: translateY(4px); }
    to { opacity: 1; transform: translateY(0); }
}

.agent-detail-header-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 10px 16px;
    border-bottom: 1px solid var(--border);
    background: #ffffff;
    flex-shrink: 0;
    min-height: 48px;
    box-sizing: border-box;
}

.agent-detail-breadcrumb {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.8rem;
    color: var(--text-muted);
    min-width: 0;
}

.agent-breadcrumb-back {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    height: 30px;
    padding: 0 10px;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: #f8fafc;
    color: var(--text-main);
    font-size: 0.76rem;
    font-weight: 600;
    cursor: pointer;
    margin-right: 8px;
    transition: all 0.15s ease;
}

.agent-breadcrumb-back:hover {
    background: #f1f5f9;
    border-color: var(--primary);
    color: var(--primary);
}

.agent-breadcrumb-item.active {
    font-weight: 700;
    color: var(--text-main);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: 480px;
}

.agent-breadcrumb-sep {
    color: #cbd5e1;
    font-weight: 400;
}

.agent-detail-header-actions {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-shrink: 0;
}

.agent-detail-header-actions .btn-secondary,
.agent-detail-header-actions .btn-primary,
.agent-detail-header-actions .btn-danger-outline {
    height: 28px;
    padding: 0 10px;
    font-size: 0.74rem;
    border-radius: 6px;
}

.agent-run-tabs {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 6px 14px;
    border-bottom: 1px solid var(--border);
    background: #fafbfc;
    flex-shrink: 0;
    overflow-x: auto;
}

.agent-run-tab {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    border: 1px solid transparent;
    border-radius: 6px;
    background: transparent;
    font-size: 0.76rem;
    font-weight: 600;
    color: var(--text-muted);
    cursor: pointer;
    transition: all 0.15s ease;
    white-space: nowrap;
}

.agent-run-tab:hover {
    background: #f1f5f9;
    color: var(--text-main);
}

.agent-run-tab.active {
    background: #fff;
    color: var(--primary);
    border-color: var(--border);
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
    font-weight: 700;
}

.agent-run-tab-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 18px;
    height: 16px;
    padding: 0 4px;
    border-radius: 999px;
    font-size: 0.64rem;
    font-weight: 700;
    background: #e2e8f0;
    color: #475569;
}

.agent-run-tab.active .agent-run-tab-badge {
    background: rgba(16, 185, 129, 0.14);
    color: var(--primary);
}

.agent-run-tab-badge--warning {
    background: #fee2e2 !important;
    color: var(--danger) !important;
}

.agent-tasks-content-and-context {
    display: flex;
    flex: 1;
    min-height: 0;
    overflow: hidden;
}

.agent-run-tab-panes {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 14px 16px;
    background: #fff;
}

.agent-run-tab-pane {
    display: flex;
    flex-direction: column;
    gap: 12px;
    min-height: 100%;
}

.agent-run-tab-pane.hidden {
    display: none !important;
}

.agent-run-detail-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    min-height: 320px;
    text-align: center;
    color: var(--text-muted);
    padding: 32px 20px;
}

.agent-run-detail-empty .empty-icon-wrap {
    width: 64px;
    height: 64px;
    border-radius: 16px;
    background: #f1f5f9;
    color: #94a3b8;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 14px;
}

.agent-run-detail-empty h4 {
    font-size: 0.98rem;
    font-weight: 700;
    color: var(--text-main);
    margin: 0 0 6px;
}

.agent-run-detail-empty p {
    font-size: 0.78rem;
    max-width: 380px;
    line-height: 1.5;
    color: var(--text-muted);
    margin: 0;
}

.agent-tasks-context-pane {
    width: 270px;
    flex-shrink: 0;
    border-left: 1px solid var(--border);
    background: #fafbfc;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    padding: 14px 12px;
    box-sizing: border-box;
}

.agent-context-pane-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
    padding-bottom: 8px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.18);
}

.agent-context-pane-head strong {
    font-size: 0.82rem;
    color: var(--text-main);
}

.agent-context-status-pill {
    font-size: 0.68rem;
    padding: 2px 8px;
    border-radius: 999px;
    background: #e2e8f0;
    color: #475569;
    font-weight: 700;
}

.agent-context-pane-body {
    font-size: 0.74rem;
    line-height: 1.5;
    color: var(--text-main);
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.agent-context-loading-hint {
    color: var(--text-muted);
    font-size: 0.74rem;
    text-align: center;
    padding: 24px 0;
}

.agent-context-card {
    background: #fff;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 10px 12px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.02);
}

.agent-context-card h5 {
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--text-muted);
    margin: 0 0 8px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.agent-context-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 4px 0;
    font-size: 0.74rem;
    border-bottom: 1px dashed #f1f5f9;
}

.agent-context-row:last-child {
    border-bottom: none;
}

.agent-context-row span {
    color: var(--text-muted);
}

.agent-context-row strong {
    color: var(--text-main);
    font-weight: 600;
}

/* 响应式断点 */
@media (max-width: 1200px) {
    .agent-tasks-context-pane {
        display: none;
    }
}

@media (max-width: 900px) {
    .agent-workbench-split-layout {
        display: block;
        position: relative;
        padding: 8px;
    }
    .agent-tasks-master-pane {
        width: 100%;
        height: 100%;
    }
    .agent-tasks-detail-container {
        display: none;
        width: 100%;
        height: 100%;
        position: absolute;
        inset: 8px;
        z-index: 10;
    }
    .agent-workbench-split-layout.has-active-detail .agent-tasks-master-pane {
        display: none;
    }
    .agent-workbench-split-layout.has-active-detail .agent-tasks-detail-container {
        display: flex;
    }
    .agent-breadcrumb-back {
        display: inline-flex;
    }
}



/* === styles/workspaces/agent/agent-run-detail.css === */
/* 拆自 agent-runs.css。 */
/* Agent 运行详情弹窗、进度摘要、最终答案与结构化输出面板样式。 */
#agent-run-detail-modal {
    z-index: 2000;
}

.agent-run-detail {
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 12px;
    background: #f8fafc;
}

.agent-run-detail-modal {
    display: flex;
    flex-direction: column;
    width: min(1220px, calc(100vw - 32px));
    height: min(860px, calc(100vh - 32px));
    max-height: calc(100vh - 32px);
    padding: 0;
    overflow: hidden;
    border-radius: 10px;
}

.agent-detail-head {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 10px;
    padding: 10px;
    border-radius: 8px;
    background: rgba(248, 250, 252, 0.9);
    border: 1px solid var(--border);
}

.agent-detail-head h4 {
    margin: 7px 0 3px;
    font-size: 0.9rem;
}

.agent-detail-head p,
.agent-detail-head small {
    color: var(--text-muted);
    margin: 0;
    line-height: 1.45;
    font-size: 0.76rem;
}

.agent-detail-actions {
    display: flex;
    align-items: flex-end;
    flex-direction: column;
    gap: 6px;
    flex-shrink: 0;
}

.agent-detail-actions .btn-secondary,
.agent-detail-actions .btn-danger-outline {
    height: 28px;
    padding: 0 9px;
    font-size: 0.72rem;
    border-radius: 7px;
}

.agent-progress-summary {
    border: 1px solid var(--border);
    border-radius: 8px;
    background: #fff;
    padding: 8px 10px;
    margin-bottom: 10px;
}

.agent-progress-bar {
    height: 6px;
    border-radius: 999px;
    background: #e2e8f0;
    overflow: hidden;
}

.agent-progress-bar span {
    display: block;
    height: 100%;
    border-radius: inherit;
    background: var(--primary);
    transition: width 0.25s ease;
}

.agent-progress-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 7px 10px;
    margin-top: 7px;
    color: var(--text-muted);
    font-size: 0.72rem;
}

.agent-progress-meta .btn-secondary,
.agent-progress-meta .btn-danger-outline {
    height: 26px;
    padding: 0 9px;
    font-size: 0.7rem;
    border-radius: 7px;
}

.agent-progress-meta .btn-secondary:first-of-type,
.agent-progress-meta .btn-danger-outline:first-of-type {
    margin-left: auto;
}

.agent-trace-panel {
    margin-bottom: 12px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 8px;
    background: #fff;
    overflow: hidden;
}

.agent-trace-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 42px;
    padding: 8px 12px;
    cursor: pointer;
    list-style: none;
    background: #f8fafc;
}

.agent-trace-head::-webkit-details-marker {
    display: none;
}

.agent-trace-head > span {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

.agent-trace-head strong {
    color: #0f172a;
    font-size: 0.78rem;
}

.agent-trace-head em {
    color: #64748b;
    font-size: 0.68rem;
    font-style: normal;
    white-space: nowrap;
}

.agent-trace-head em.is-success {
    color: #047857;
    font-weight: 800;
}

.agent-trace-head em.is-error {
    color: #b91c1c;
    font-weight: 800;
}

.agent-trace-list {
    display: flex;
    flex-direction: column;
    gap: 0;
    padding: 4px 12px 10px;
}

.agent-trace-item {
    padding: 9px 0;
    border-bottom: 1px solid rgba(148, 163, 184, 0.16);
}

.agent-trace-item:last-child {
    border-bottom: 0;
}

.agent-trace-item-meta {
    display: grid;
    grid-template-columns: 54px minmax(0, 1fr) max-content;
    align-items: center;
    gap: 8px;
}

.agent-trace-item-meta strong {
    min-width: 0;
    color: #1e293b;
    font-size: 0.72rem;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.agent-trace-item-meta em {
    color: #64748b;
    font-size: 0.66rem;
    font-style: normal;
}

.agent-trace-type {
    padding: 2px 6px;
    border-radius: 5px;
    background: #e2e8f0;
    color: #334155;
    font-size: 0.62rem;
    font-weight: 800;
    text-align: center;
}

.agent-trace-track {
    position: relative;
    height: 6px;
    margin: 7px 0 0 62px;
    border-radius: 999px;
    background: #eef2f7;
    overflow: hidden;
}

.agent-trace-track > span {
    position: absolute;
    top: 0;
    bottom: 0;
    border-radius: inherit;
    background: #0f766e;
}

.agent-trace-item.error .agent-trace-track > span {
    background: #dc2626;
}

.agent-trace-item.running .agent-trace-track > span {
    background: #2563eb;
}

.agent-trace-detail {
    margin: 7px 0 0 62px;
}

.agent-trace-detail > summary {
    width: fit-content;
    color: #64748b;
    font-size: 0.66rem;
    font-weight: 700;
    cursor: pointer;
}

.agent-trace-detail-body {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 8px;
    margin-top: 7px;
}

.agent-trace-detail-body section {
    min-width: 0;
    padding: 8px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 6px;
    background: #f8fafc;
    font-size: 0.7rem;
    overflow: auto;
}

.agent-trace-detail-body h5 {
    margin: 0 0 6px;
    color: #475569;
    font-size: 0.66rem;
}

@media (max-width: 640px) {
    .agent-trace-head {
        align-items: flex-start;
        flex-direction: column;
    }

    .agent-trace-item-meta {
        grid-template-columns: 48px minmax(0, 1fr);
    }

    .agent-trace-item-meta em {
        grid-column: 2;
    }

    .agent-trace-track,
    .agent-trace-detail {
        margin-left: 56px;
    }
}

.agent-final {
    position: relative;
    border: 1px solid rgba(226, 232, 240, 0.9);
    border-radius: 12px;
    padding: 20px 24px;
    margin-bottom: 16px;
    background: #ffffff;
    box-shadow: 0 4px 20px rgba(15, 23, 42, 0.04), 0 1px 3px rgba(15, 23, 42, 0.02);
    font-size: 0.84rem;
    line-height: 1.75;
    text-align: left;
    color: #1e293b;
    overflow-wrap: anywhere;
}

.agent-final::before {
    display: none;
}

.agent-final-label {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0 0 14px;
    padding: 3px 10px;
    border-radius: 6px;
    background: #f1f5f9;
    color: #334155;
    font-size: 0.74rem;
    font-weight: 800;
    letter-spacing: 0.02em;
    border: 1px solid rgba(148, 163, 184, 0.2);
}

.agent-final > :first-child {
    margin-top: 0;
}

.agent-final > :last-child {
    margin-bottom: 0;
}

.agent-final p {
    margin: 0.55em 0;
    text-align: left;
    text-indent: 0;
}

.agent-final p:has(strong:only-child) {
    text-indent: 0;
}

.agent-final ol,
.agent-final ul {
    margin: 0.55em 0 0.75em;
    padding-left: 1.55em;
    text-align: left;
    list-style-position: outside;
}

.agent-final li {
    margin: 0.3em 0;
    padding-left: 0.15em;
    text-align: left;
    text-indent: 0;
}

.agent-final h1,
.agent-final h2 {
    margin: 0 0 0.75em;
    color: #0f172a;
    font-size: clamp(1.22rem, 1.6vw, 1.55rem);
    line-height: 1.25;
    letter-spacing: 0;
}

.agent-final h3,
.agent-final h4 {
    margin: 1.05em 0 0.45em;
    color: #0f172a;
    font-size: 0.92rem;
    line-height: 1.35;
}

.agent-final strong,
.agent-final h1,
.agent-final h2,
.agent-final h3,
.agent-final h4 {
    text-align: left;
}

.agent-final code {
    padding: 1px 5px;
    border-radius: 5px;
    background: rgba(15, 23, 42, 0.05);
    color: #0f172a;
    font-size: 0.86em;
}

.agent-final .table-wrapper {
    margin: 14px 0;
    border: 1px solid rgba(226, 232, 240, 0.9);
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.03);
}

.agent-final table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.78rem;
}

.agent-final th {
    background: #f8fafc;
    color: #475569;
    font-weight: 700;
    padding: 9px 12px;
    border-bottom: 1px solid rgba(226, 232, 240, 0.9);
    text-align: left;
}

.agent-final td {
    padding: 9px 12px;
    color: #1e293b;
    border-bottom: 1px solid rgba(241, 245, 249, 0.8);
    line-height: 1.5;
}

.agent-final tr:last-child td {
    border-bottom: 0;
}

.agent-final tr:nth-child(even) td {
    background: #fbfcfe;
}

.agent-result-raw {
    margin-top: 14px;
    padding-top: 10px;
    border-top: 1px solid rgba(148, 163, 184, 0.18);
}

.agent-result-raw summary {
    width: fit-content;
    color: var(--text-muted);
    font-size: 0.7rem;
    font-weight: 700;
    cursor: pointer;
}

.agent-result-raw pre {
    max-height: 260px;
    margin: 9px 0 0;
    padding: 10px 12px;
    overflow: auto;
    border-radius: 6px;
    background: #0f172a;
    color: #e2e8f0;
    font-size: 0.68rem;
    line-height: 1.5;
    white-space: pre-wrap;
    word-break: break-word;
}

.agent-visual-results {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 12px;
}

.agent-structured-output {
    min-width: 0;
}

.agent-structured-output-title {
    margin: 0 0 6px;
    color: var(--text-muted);
    font-size: 0.72rem;
    font-weight: 700;
}

.agent-structured-output-body {
    min-width: 0;
}

.agent-structured-output-body .pivot-echart-block {
    max-width: 100%;
    margin: 0;
}

.agent-structured-output-body .table-wrapper {
    margin: 0;
}

/* ── 面向普通用户的执行结果视图 ───────────────────────────── */
.agent-run-detail-modal {
    width: min(1120px, calc(100vw - 28px));
    height: min(820px, calc(100vh - 28px));
    max-height: calc(100vh - 28px);
    border: 1px solid rgba(148, 163, 184, 0.34);
    border-radius: 12px;
    background: #f6f8fb;
    box-shadow: 0 24px 70px rgba(15, 23, 42, 0.22);
}

.agent-run-detail-modal > .agent-config-modal-head {
    min-height: 58px;
    padding: 12px 20px;
    background: #fff;
}

.agent-run-detail-modal > .agent-config-modal-head h3 {
    color: #0f172a;
    font-size: 1.02rem;
    font-weight: 800;
}

.agent-run-detail {
    padding: 20px 24px 28px;
    background: #f6f8fb;
}

.agent-run-overview {
    margin-bottom: 14px;
    padding: 20px 22px 16px;
    border: 1px solid rgba(148, 163, 184, 0.26);
    border-radius: 12px;
    background: #fff;
    box-shadow: 0 3px 12px rgba(15, 23, 42, 0.04);
}

.agent-run-overview-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 24px;
}

.agent-run-status-copy {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    min-width: 0;
    text-align: left;
}

.agent-run-status-copy > div {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    text-align: left;
}

.agent-run-status-icon {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 36px;
    width: 36px;
    height: 36px;
    margin-top: 1px;
    border-radius: 50%;
    background: linear-gradient(135deg, #10b981 0%, #059669 100%);
    box-shadow: 0 3px 10px rgba(16, 185, 129, 0.28);
}

.agent-run-status-icon::after {
    content: "";
    position: absolute;
    left: 12px;
    top: 14.5px;
    width: 11px;
    height: 6px;
    border-left: 2.2px solid #ffffff;
    border-bottom: 2.2px solid #ffffff;
    border-bottom-left-radius: 1px;
    transform: rotate(-45deg);
    box-sizing: border-box;
}

.agent-run-overview.running .agent-run-status-icon,
.agent-run-overview.queued .agent-run-status-icon {
    background: linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%);
    box-shadow: 0 3px 10px rgba(37, 99, 235, 0.28);
}

.agent-run-overview.running .agent-run-status-icon::after,
.agent-run-overview.queued .agent-run-status-icon::after {
    left: 10px;
    top: 10px;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    border: 2.2px solid #ffffff;
    border-bottom-color: transparent;
    transform: none;
    animation: agentRunIconSpin 0.9s linear infinite;
}

@keyframes agentRunIconSpin {
    to { transform: rotate(360deg); }
}

.agent-run-overview.error .agent-run-status-icon,
.agent-run-overview.completed_with_errors .agent-run-status-icon {
    background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
    box-shadow: 0 3px 10px rgba(220, 38, 38, 0.28);
}

.agent-run-overview.error .agent-run-status-icon::after,
.agent-run-overview.completed_with_errors .agent-run-status-icon::after {
    content: "!";
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    border: 0;
    transform: none;
    color: #ffffff;
    font-size: 17px;
    font-weight: 800;
    display: flex;
    align-items: center;
    justify-content: center;
}

.agent-run-overview.approval_required .agent-run-status-icon {
    background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
    box-shadow: 0 3px 10px rgba(217, 119, 6, 0.28);
}

.agent-run-overview.approval_required .agent-run-status-icon::after {
    content: "!";
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    border: 0;
    transform: none;
    color: #ffffff;
    font-size: 17px;
    font-weight: 800;
    display: flex;
    align-items: center;
    justify-content: center;
}

.agent-run-overview.cancelled .agent-run-status-icon {
    background: linear-gradient(135deg, #64748b 0%, #475569 100%);
    box-shadow: 0 3px 10px rgba(100, 116, 139, 0.25);
}

.agent-run-kicker {
    display: block;
    margin-bottom: 3px;
    color: #64748b;
    font-size: 0.72rem;
    font-weight: 700;
    text-align: left;
}

.agent-run-status-copy h4 {
    margin: 0;
    color: #0f172a;
    font-size: 1.28rem;
    line-height: 1.25;
    text-align: left;
}

.agent-run-status-copy p {
    margin: 5px 0 0;
    color: #64748b;
    font-size: 0.8rem;
    line-height: 1.5;
    text-align: left;
}

.agent-run-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 7px;
    flex: 0 0 auto;
}

.agent-run-actions > .btn-primary,
.agent-run-actions > .btn-secondary,
.agent-run-actions > .btn-danger-outline,
.agent-run-more-actions > summary {
    min-height: 32px;
    padding: 0 12px;
    border-radius: 7px;
    font-size: 0.75rem;
    white-space: nowrap;
}

.agent-run-more-actions {
    position: relative;
}

.agent-run-more-actions > summary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    list-style: none;
}

.agent-run-more-actions > summary::-webkit-details-marker { display: none; }

.agent-run-more-actions > div {
    position: absolute;
    right: 0;
    top: calc(100% + 5px);
    z-index: 3;
    display: flex;
    flex-direction: column;
    gap: 5px;
    min-width: 136px;
    padding: 6px;
    border: 1px solid rgba(148, 163, 184, 0.3);
    border-radius: 8px;
    background: #fff;
    box-shadow: 0 10px 28px rgba(15, 23, 42, 0.14);
}

.agent-run-more-actions > div .btn-secondary {
    min-height: 30px;
    border: 0;
    text-align: left;
    box-shadow: none;
}

.agent-run-goal-box {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin: 16px 0 14px;
    padding: 12px 14px;
    border-radius: 8px;
    background: #f8fafc;
    border: 1px solid rgba(226, 232, 240, 0.9);
}

.agent-run-meta-item {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

.agent-run-meta-item.agent-run-goal-item {
    flex-direction: column;
    align-items: stretch;
    gap: 6px;
}

.agent-run-meta-label {
    flex: 0 0 auto;
    color: #64748b;
    font-size: 0.72rem;
    font-weight: 700;
}

.agent-run-title-val {
    color: #0f172a;
    font-size: 0.84rem;
    font-weight: 800;
}

.agent-run-goal-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
}

.agent-run-goal-actions {
    display: flex;
    align-items: center;
    gap: 6px;
}

.agent-run-goal-actions .btn-xs {
    padding: 2px 8px;
    font-size: 0.7rem;
    height: 24px;
    line-height: 1.2;
}

.agent-run-goal-body {
    padding: 8px 12px;
    border-radius: 6px;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    color: #334155;
    font-size: 0.78rem;
    line-height: 1.55;
    white-space: pre-wrap;
    word-break: break-word;
    max-height: 180px;
    overflow-y: auto;
}

.agent-run-overview .agent-progress-bar {
    height: 5px;
    background: #e2e8f0;
}

.agent-run-key-metrics {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 14px;
    margin: 15px 0 0;
}

.agent-run-key-metrics > div { min-width: 0; }
.agent-run-key-metrics dt {
    margin-bottom: 3px;
    color: #94a3b8;
    font-size: 0.68rem;
    font-weight: 700;
    text-align: left;
}

.agent-run-key-metrics dd {
    margin: 0;
    color: #1e293b;
    font-size: 0.82rem;
    font-weight: 800;
    text-align: left;
}

.agent-run-key-metrics dd.has-error { color: #b91c1c; }

.agent-run-technical-summary,
.agent-run-process {
    margin-bottom: 14px;
    border: 1px solid rgba(148, 163, 184, 0.26);
    border-radius: 10px;
    background: #fff;
    overflow: hidden;
}

.agent-run-technical-summary > summary,
.agent-run-process > summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 44px;
    padding: 11px 14px;
    color: #334155;
    font-size: 0.8rem;
    font-weight: 800;
    cursor: pointer;
    list-style: none;
}

.agent-run-technical-summary > summary::-webkit-details-marker,
.agent-run-process > summary::-webkit-details-marker { display: none; }
.agent-run-technical-summary > summary::before,
.agent-run-process > summary::before { content: ""; width: 7px; height: 7px; margin-right: 1px; border-right: 1.5px solid #64748b; border-bottom: 1.5px solid #64748b; transform: rotate(-45deg); transition: transform .15s ease; }
.agent-run-technical-summary[open] > summary::before,
.agent-run-process[open] > summary::before { transform: rotate(45deg); }
.agent-run-technical-summary > summary > span,
.agent-run-process > summary > span { margin-right: auto; }
.agent-run-technical-summary > summary em,
.agent-run-process > summary em { color: #94a3b8; font-size: 0.7rem; font-style: normal; font-weight: 600; }

.agent-run-technical-summary > dl {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 14px 24px;
    margin: 0;
    padding: 14px 20px;
    border-top: 1px solid rgba(148, 163, 184, 0.16);
    background: #fbfcfe;
}

.agent-run-technical-summary > dl > div {
    flex: 0 1 auto;
    min-width: max-content;
    text-align: center;
}

.agent-run-technical-summary dt {
    margin-bottom: 4px;
    color: #94a3b8;
    font-size: 0.7rem;
    font-weight: 700;
    text-align: center;
    white-space: nowrap;
}

.agent-run-technical-summary dd {
    margin: 0;
    color: #1e293b;
    font-size: 0.82rem;
    font-weight: 800;
    text-align: center;
    white-space: nowrap;
}

.agent-run-process-body {
    padding: 14px;
    border-top: 1px solid rgba(148, 163, 184, 0.16);
    background: #fbfcfe;
}

.agent-run-process-body > .agent-trace-panel { margin-top: 12px; margin-bottom: 0; }

.agent-visual-results {
    margin-bottom: 14px;
    padding: 14px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 10px;
    background: #fff;
}

.agent-visual-results .agent-tool-section-head { margin-bottom: 10px; }

.agent-dag-list { gap: 10px; margin-bottom: 0; display: flex; flex-direction: column; }
.agent-dag-list .agent-tool-section-head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin: 18px 0 10px;
    padding: 0 2px 8px;
    border-top: 0;
    border-bottom: 1px solid rgba(148, 163, 184, 0.18);
}
.agent-dag-list .agent-tool-section-head strong {
    color: #1e293b;
    font-size: 0.86rem;
    font-weight: 800;
}
.agent-dag-list .agent-tool-section-head span {
    color: #94a3b8;
    font-size: 0.72rem;
    font-weight: 600;
}

.agent-dag-node {
    padding: 0;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 9px;
    background: #fff;
    box-shadow: none;
    overflow: hidden;
    margin-bottom: 2px;
}
.agent-dag-node.completed { border-color: rgba(16, 185, 129, 0.28); background: #fff; }
.agent-dag-node.error { border-color: rgba(239, 68, 68, 0.32); background: #fff; }
.agent-dag-node.running { border-color: rgba(37, 99, 235, 0.32); background: #fff; }
.agent-dag-node-details > summary { list-style: none; cursor: pointer; }
.agent-dag-node-details > summary::-webkit-details-marker { display: none; }
.agent-dag-node-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    min-height: 54px;
    margin: 0;
    padding: 10px 14px;
}
.agent-dag-node-title {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: 10px;
    min-width: 0;
}
.agent-dag-node-index {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 24px;
    width: 24px;
    height: 24px;
    border-radius: 50%;
    background: #ecfdf5;
    color: #047857;
    font-size: 0.72rem;
    font-weight: 800;
}
.agent-dag-node.running .agent-dag-node-index { background: #eff6ff; color: #1d4ed8; }
.agent-dag-node.error .agent-dag-node-index { background: #fef2f2; color: #b91c1c; }
.agent-dag-node.pending .agent-dag-node-index { background: #f8fafc; color: #64748b; }
.agent-dag-node-title > div { display: flex; flex-direction: column; gap: 2px; min-width: 0; text-align: left; }
.agent-dag-node-title strong { font-size: 0.84rem; color: #0f172a; text-align: left; }
.agent-dag-node-title span { font-family: inherit; font-size: 0.68rem; color: #64748b; text-align: left; }
.agent-dag-node-badges { display: flex; align-items: center; justify-content: flex-end; max-width: none; gap: 8px; flex: 0 0 auto; }
.agent-dag-node-badges em { color: #94a3b8; font-size: 0.7rem; font-style: normal; white-space: nowrap; }
.agent-dag-node-status {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 24px;
    padding: 0 9px;
    border-radius: 999px;
    font-size: 0.68rem;
    font-weight: 700;
    white-space: nowrap;
}
.agent-dag-node-status.completed { background: rgba(16, 185, 129, 0.12); color: #047857; border: 1px solid rgba(16, 185, 129, 0.28); }
.agent-dag-node-status.running { background: rgba(37, 99, 235, 0.12); color: #1d4ed8; border: 1px solid rgba(37, 99, 235, 0.28); }
.agent-dag-node-status.error { background: rgba(239, 68, 68, 0.12); color: #b91c1c; border: 1px solid rgba(239, 68, 68, 0.28); }
.agent-dag-node-status.skipped { background: rgba(245, 158, 11, 0.12); color: #b45309; border: 1px solid rgba(245, 158, 11, 0.28); }
.agent-dag-node-status.pending { background: rgba(148, 163, 184, 0.12); color: #475569; border: 1px solid rgba(148, 163, 184, 0.24); }
.agent-dag-node-body { padding: 0 14px 14px; border-top: 1px solid rgba(148, 163, 184, 0.16); }
.agent-dag-node-result { margin-top: 12px; }
.agent-dag-node-result h5 { margin: 0 0 7px; color: #475569; font-size: 0.72rem; }
.agent-dag-node-readable-output { margin-top: 0; padding: 12px 14px; border-radius: 7px; background: #f8fafc; border-color: rgba(148, 163, 184, 0.2); font-size: 0.78rem; }
.agent-dag-node-technical { margin-top: 11px; }
.agent-dag-node-technical > summary { width: fit-content; color: #64748b; font-size: 0.7rem; font-weight: 700; cursor: pointer; }
.agent-dag-node-meta { margin-top: 8px; }
.agent-dag-node-meta span { background: #fbfcfe; }
.agent-dag-node-rerun { margin-top: 10px; }

@media (max-width: 760px) {
    .agent-run-detail { padding: 14px 12px 20px; }
    .agent-run-overview { padding: 16px; }
    .agent-run-overview-top { flex-direction: column; gap: 15px; }
    .agent-run-actions { justify-content: flex-start; width: 100%; }
    .agent-run-goal strong { white-space: normal; }
    .agent-run-key-metrics { gap: 8px; }
    .agent-run-key-metrics dd { font-size: 0.76rem; }
    .agent-run-process-body { padding: 10px; }
    .agent-dag-node-head { align-items: flex-start; }
    .agent-dag-node-badges { flex-direction: column; align-items: flex-end; gap: 4px; }
}

@media (max-width: 480px) {
    .agent-run-detail-modal { width: calc(100vw - 16px); height: calc(100vh - 16px); max-height: calc(100vh - 16px); }
    .agent-run-detail-modal > .agent-config-modal-head { padding: 10px 13px; }
    .agent-run-key-metrics { grid-template-columns: 1fr; gap: 10px; }
    .agent-run-technical-summary > dl { flex-direction: column; align-items: flex-start; gap: 10px; padding-left: 14px; }
    .agent-run-technical-summary > dl > div { text-align: left; }
    .agent-run-technical-summary dt,
    .agent-run-technical-summary dd { text-align: left; }
    .agent-run-technical-summary > summary em,
    .agent-run-process > summary em { display: none; }
    .agent-dag-node-title strong { font-size: 0.76rem; }
    .agent-dag-node-title span { max-width: 150px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
}
.agent-run-feedback {
    margin: 12px 0;
    padding: 10px 12px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 8px;
    background: #f8fafc;
    display: flex;
    flex-direction: column;
    gap: 8px;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.agent-run-feedback:focus-within {
    border-color: rgba(16, 163, 127, 0.35);
    box-shadow: 0 1px 4px rgba(16, 163, 127, 0.05);
}

.agent-run-feedback-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.agent-run-feedback-title {
    display: flex;
    align-items: center;
    gap: 6px;
}

.agent-run-feedback-title svg {
    flex-shrink: 0;
    color: var(--text-muted, #64748b);
}

.agent-run-feedback-title strong {
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--text-main, #1e293b);
}

.agent-run-feedback-hint {
    font-size: 0.68rem;
    color: var(--text-muted, #64748b);
}

.agent-run-feedback-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    flex-wrap: wrap;
}

.agent-run-feedback-pills {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
}

.agent-feedback-pill {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    height: 26px;
    padding: 0 10px;
    border: 1px solid rgba(148, 163, 184, 0.25);
    border-radius: 13px;
    background: #ffffff;
    color: var(--text-secondary, #475569);
    font-size: 0.72rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.14s ease;
    user-select: none;
}

.agent-feedback-pill svg {
    flex-shrink: 0;
    pointer-events: none;
}

.agent-feedback-pill:hover {
    background: #f1f5f9;
    border-color: rgba(148, 163, 184, 0.4);
    color: var(--text-main, #1e293b);
}

.agent-feedback-pill.active[data-agent-feedback-outcome="success"] {
    background: #ecfdf5;
    border-color: #10a37f;
    color: #059669;
    box-shadow: 0 1px 2px rgba(16, 163, 127, 0.12);
}

.agent-feedback-pill.active[data-agent-feedback-outcome="partial"] {
    background: #fffbeb;
    border-color: #f59e0b;
    color: #d97706;
    box-shadow: 0 1px 2px rgba(245, 158, 11, 0.12);
}

.agent-feedback-pill.active[data-agent-feedback-outcome="failure"] {
    background: #fff1f2;
    border-color: #f43f5e;
    color: #e11d48;
    box-shadow: 0 1px 2px rgba(244, 63, 94, 0.12);
}

.agent-run-feedback-rating-wrap {
    display: inline-flex;
    align-items: center;
}

.agent-run-feedback-rating-label {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: 0.7rem;
    color: var(--text-muted, #64748b);
    font-weight: 600;
}

.agent-run-feedback-rating-select {
    height: 26px;
    padding: 0 8px;
    border: 1px solid rgba(148, 163, 184, 0.25);
    border-radius: 5px;
    background: #ffffff;
    color: var(--text-main, #1e293b);
    font-size: 0.72rem;
    cursor: pointer;
}

.agent-run-feedback-textarea {
    width: 100%;
    min-height: 48px;
    max-height: 120px;
    padding: 6px 9px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 6px;
    background: #ffffff;
    font-size: 0.75rem;
