    color: var(--text-primary, #1e293b);
    font-size: 0.84rem;
    font-weight: 700;
    cursor: pointer;
    list-style: none;
    background: rgba(248, 250, 252, 0.8);
    transition: background 0.15s ease;
}

.agent-run-harness-diagnostics>summary:hover {
    background: rgba(241, 245, 249, 0.95);
}

.agent-run-harness-diagnostics>summary::-webkit-details-marker {
    display: none;
}

.agent-run-harness-diagnostics>summary::before {
    content: "";
    width: 7px;
    height: 7px;
    margin-right: 2px;
    border-right: 1.5px solid #64748b;
    border-bottom: 1.5px solid #64748b;
    transform: rotate(-45deg);
    transition: transform .18s ease;
}

.agent-run-harness-diagnostics[open]>summary::before {
    transform: rotate(45deg);
}

.agent-run-harness-diagnostics>summary span {
    margin-right: auto;
}

.agent-run-harness-diagnostics>summary em {
    color: var(--text-muted, #94a3b8);
    font-size: 0.72rem;
    font-style: normal;
    font-weight: 500;
}

.agent-harness-diagnostics-body {
    padding: 12px 16px 16px;
    border-top: 1px solid rgba(226, 232, 240, 0.85);
    background: rgba(248, 250, 252, 0.5);
}

/* 常驻子导航按钮组（分段控制器外观） */
.agent-harness-diagnostic-tabs {
    display: flex;
    gap: 4px;
    padding: 3px;
    background: rgba(241, 245, 249, 0.95);
    border: 1px solid rgba(226, 232, 240, 0.85);
    border-radius: 8px;
    position: sticky;
    top: 0;
    z-index: 5;
    backdrop-filter: blur(8px);
    margin-bottom: 10px;
}

.agent-harness-diagnostic-tab {
    flex: 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 32px;
    padding: 5px 12px;
    border: 1px solid transparent;
    border-radius: 6px;
    background: transparent;
    color: var(--text-muted, #64748b);
    font-size: 0.78rem;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    transition: all 0.16s cubic-bezier(0.4, 0, 0.2, 1);
}

.agent-harness-diagnostic-tab:hover {
    color: var(--text-primary, #0f172a);
    background: rgba(255, 255, 255, 0.65);
}

.agent-harness-diagnostic-tab.active {
    background: #fff;
    color: var(--primary-color, #2563eb);
    font-weight: 700;
    border-color: rgba(203, 213, 225, 0.85);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.08);
}

.agent-harness-diagnostic-panels {
    display: block;
    min-height: 60px;
}

.agent-harness-diagnostic-panel {
    display: grid;
    gap: 8px;
}

.agent-harness-diagnostic-panel.hidden {
    display: none !important;
}

.agent-harness-diagnostic-card {
    display: grid;
    gap: 5px;
    padding: 11px 14px;
    border: 1px solid rgba(226, 232, 240, 0.85);
    border-radius: 8px;
    background: var(--bg-secondary, #fff);
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.02);
    transition: border-color 0.15s ease;
}

.agent-harness-diagnostic-card:hover {
    border-color: rgba(148, 163, 184, 0.4);
}

.agent-harness-diagnostic-card>summary {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
    list-style: none;
    font-size: 0.78rem;
    font-weight: 600;
}

.agent-harness-diagnostic-card>summary::-webkit-details-marker {
    display: none;
}

.agent-harness-diagnostic-card strong {
    color: var(--text-primary, #0f172a);
    font-size: 0.78rem;
    font-weight: 700;
}

.agent-harness-diagnostic-card span,
.agent-harness-diagnostic-card small,
.agent-harness-diagnostic-meta {
