    margin-bottom: 22px;
}

.agent-goal-quick-templates {
    width: 100%;
    max-width: 660px;
    border-top: 1px solid rgba(148, 163, 184, 0.15);
    padding-top: 16px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
}

.agent-goal-quick-title {
    font-size: 0.72rem;
    color: var(--text-muted, #64748b);
    font-weight: 500;
}

.agent-goal-template-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    justify-content: center;
}

.agent-goal-template-chip {
    appearance: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    vertical-align: middle;
    gap: 6px;
    padding: 6px 12px;
    border-radius: 6px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    background: #f8fafc;
    color: var(--text-main, #0f172a);
    font-size: 0.74rem;
    line-height: 1;
    cursor: pointer;
    transition: all 0.15s ease;
}

.agent-goal-template-chip:hover {
    border-color: rgba(16, 163, 127, 0.45);
    background: rgba(16, 163, 127, 0.05);
    transform: translateY(-1px);
}

.agent-goal-template-chip .chip-svg {
    width: 14px;
    height: 14px;
    color: var(--text-muted, #64748b);
    display: block;
    flex-shrink: 0;
    margin: 0;
    transition: color 0.15s ease;
}

.agent-goal-template-chip:hover .chip-svg {
    color: #10a37f;
}

.agent-goal-template-chip .chip-name {
    font-weight: 600;
    color: var(--text-main, #0f172a);
    line-height: 1;
    margin: 0;
    padding: 0;
    display: inline-flex;
    align-items: center;
}

.agent-goal-template-chip .chip-badge {
    font-size: 0.68rem;
    line-height: 1;
    padding: 2px 6px;
    border-radius: 4px;
    background: rgba(148, 163, 184, 0.16);
    color: var(--text-muted, #64748b);
    margin: 0;
    display: inline-flex;
    align-items: center;
}

/* 暗色模式适配 */
body.dark-mode .agent-inbox-filter-pill,
.dark-mode .agent-inbox-filter-pill {
    background: #1e293b;
    border-color: rgba(148, 163, 184, 0.18);
    color: #94a3b8;
}

body.dark-mode .agent-inbox-filter-pill:hover,
.dark-mode .agent-inbox-filter-pill:hover {
    background: #334155;
    color: #f1f5f9;
}

body.dark-mode .agent-inbox-filter-pill.active,
.dark-mode .agent-inbox-filter-pill.active {
    background: rgba(16, 163, 127, 0.2);
    border-color: rgba(16, 163, 127, 0.6);
    color: #34d399;
}

body.dark-mode .agent-goal-empty-hero,
.dark-mode .agent-goal-empty-hero {
    background: #0f172a;
    border-color: rgba(148, 163, 184, 0.16);
}

body.dark-mode .agent-goal-template-chip,
.dark-mode .agent-goal-template-chip {
    background: #1e293b;
    border-color: rgba(148, 163, 184, 0.18);
    color: #e2e8f0;
}

body.dark-mode .agent-goal-template-chip:hover,
.dark-mode .agent-goal-template-chip:hover {
    background: rgba(16, 163, 127, 0.15);
    border-color: rgba(16, 163, 127, 0.5);
}

body.dark-mode .agent-goal-template-chip .chip-name,
.dark-mode .agent-goal-template-chip .chip-name {
    color: #f8fafc;
}



/* === styles/workspaces/agent/agent-evaluations.css === */
.agent-eval-center {
    display: flex;
    flex: 1;
    flex-direction: column;
    width: 100%;
    min-width: 0;
    min-height: 0;
}

#agent-config-modal[data-agent-config-section="evaluations"] .agent-config-modal {
    display: flex;
    flex-direction: column;
    width: min(1180px, calc(100vw - 32px));
    height: min(760px, calc(100vh - 32px));
    max-height: calc(100vh - 32px);
}

#agent-config-modal[data-agent-config-section="evaluations"] .agent-config-modal-body {
    display: flex;
    flex: 1;
    flex-direction: column;
    min-height: 0;
    max-height: none;
    overflow: hidden;
    padding: 14px;
}

#agent-config-modal[data-agent-config-section="evaluations"] .agent-collapse-evaluations {
    display: flex;
    flex-direction: column;
    flex: 1 1 100%;
    width: 100%;
    min-height: 0;
    margin: 0;
}

#agent-config-modal[data-agent-config-section="evaluations"] .agent-collapse-evaluations[open] {
    display: flex;
    flex-direction: column;
    flex: 1;
    width: 100%;
    min-height: 0;
    overflow: hidden;
}

#agent-config-modal[data-agent-config-section="evaluations"] .agent-collapse-evaluations[open] .agent-collapse-body {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    width: 100%;
    padding: 20px;
    border-radius: 10px;
    border: 1px solid rgba(226, 232, 240, 0.9);
    background: #ffffff;
    box-shadow: 0 4px 18px rgba(15, 23, 42, 0.03);
    overflow: hidden;
    box-sizing: border-box;
}

.agent-eval-toolbar,
.agent-eval-detail-head,
.agent-eval-editor-case-toolbar,
.agent-eval-case-editor-head,
.agent-eval-editor-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.agent-eval-toolbar,
.agent-eval-overview,
.agent-eval-layout {
    width: 100%;
    box-sizing: border-box;
}

.agent-eval-toolbar>div:first-child,
.agent-eval-detail-head>div:first-child {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 2px;
    min-width: 0;
    text-align: left;
}

.agent-eval-toolbar strong,
.agent-eval-detail-head strong {
    color: #0f172a;
    font-size: 0.84rem;
    font-weight: 750;
    text-align: left;
}

.agent-eval-toolbar span,
.agent-eval-detail-head span,
.agent-eval-description {
    color: #64748b;
    font-size: 0.68rem;
    line-height: 1.35;
    text-align: left;
}

.agent-eval-toolbar-actions,
.agent-eval-detail-actions {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
}

.agent-eval-overview {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 5px;
    margin: 2px 0 6px;
    width: 100%;
    background: transparent;
    border: none;
}

.agent-eval-overview>div {
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-height: 36px;
    gap: 1px;
    padding: 3px 6px;
    background: #f8fafc;
    border: 1px solid rgba(226, 232, 240, 0.9);
    border-radius: 5px;
    text-align: left;
    min-width: 0;
}

.agent-eval-overview span,
.agent-eval-batch-summary span {
    color: #64748b;
    font-size: 0.62rem;
    font-weight: 600;
    text-align: left;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.agent-eval-overview strong,
.agent-eval-batch-summary strong {
    color: #0f172a;
    font-size: 0.88rem;
    font-weight: 750;
    line-height: 1.15;
    text-align: left;
}

.agent-eval-layout {
    display: flex;
    flex: 1;
    min-height: 460px;
    max-height: 640px;
    overflow: hidden;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
}

.agent-eval-layout.is-empty {
    display: flex;
    flex: 1;
    align-items: center;
    justify-content: center;
    min-height: 420px;
    width: 100%;
    border-top: 1px solid rgba(226, 232, 240, 0.9);
}

.agent-eval-suite-list {
    flex: 0 0 200px;
    width: 200px;
    min-width: 0;
    padding: 4px 6px 4px 0;
    overflow-y: auto;
    border-right: 1px solid rgba(226, 232, 240, 0.9);
}

.agent-eval-layout.is-empty .agent-eval-suite-list {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 100%;
    padding: 36px 20px;
    overflow: hidden;
    border-right: 0;
}

.agent-eval-layout.is-empty .agent-eval-suite-detail {
    display: none;
}

.agent-eval-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    gap: 8px;
    max-width: 420px;
    margin: 0 auto;
}

.agent-eval-empty-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 52px;
    height: 52px;
    margin-bottom: 6px;
    border-radius: 50%;
    border: 1px solid rgba(16, 185, 129, 0.28);
    color: #047857;
    background: #ecfdf5;
}

.agent-eval-empty-icon svg {
    width: 24px;
    height: 24px;
}

.agent-eval-empty strong {
    color: #0f172a;
    font-size: 1.08rem;
    font-weight: 800;
}

.agent-eval-empty>span:not(.agent-eval-empty-icon) {
    color: #64748b;
    font-size: 0.8rem;
    line-height: 1.55;
}

.agent-eval-suite-item {
    display: flex;
    width: 100%;
    min-height: 48px;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    padding: 6px 8px;
    border: 1px solid transparent;
    border-radius: 4px;
    color: inherit;
    background: transparent;
    text-align: left;
    cursor: pointer;
}

.agent-eval-suite-item:hover,
.agent-eval-suite-item.is-active {
    border-color: var(--border-color, rgba(148, 163, 184, 0.2));
    background: var(--bg-secondary, #f8fafc);
}

.agent-eval-suite-item.is-active {
    box-shadow: inset 2px 0 0 #0f766e;
}

.agent-eval-suite-main,
.agent-eval-suite-stats {
    display: grid;
    min-width: 0;
    gap: 2px;
}

.agent-eval-suite-main strong,
.agent-eval-suite-main small,
.agent-eval-suite-stats small {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.agent-eval-suite-main strong {
    color: var(--text-primary, #0f172a);
    font-size: 0.74rem;
    font-weight: 700;
}

.agent-eval-suite-main small,
.agent-eval-suite-stats small {
    color: var(--text-secondary, #64748b);
    font-size: 0.66rem;
}

.agent-eval-suite-stats {
    flex: 0 0 auto;
    justify-items: end;
}

.agent-eval-suite-stats em {
    color: var(--text-primary, #0f172a);
    font-size: 0.72rem;
    font-style: normal;
    font-weight: 700;
}

.agent-eval-suite-detail {
    min-width: 0;
    padding: 6px 0 6px 12px;
    overflow: auto;
}

.agent-eval-description {
    margin: 4px 0 0;
}

.agent-eval-case-summary {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin: 6px 0 8px;
}

.agent-eval-case-summary span,
.agent-eval-rule {
    max-width: 100%;
    padding: 2px 6px;
    border: 1px solid var(--border-color, rgba(148, 163, 184, 0.2));
    border-radius: 3px;
    color: var(--text-secondary, #475569);
    background: var(--bg-secondary, #f8fafc);
    font-size: 0.68rem;
    overflow-wrap: anywhere;
}

.agent-eval-history-list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
    gap: 6px;
}

.agent-eval-history-item {
    display: grid;
    min-width: 0;
    min-height: 52px;
    align-content: center;
    gap: 2px;
    padding: 6px 8px;
    border: 1px solid var(--border-color, rgba(148, 163, 184, 0.2));
    border-radius: 4px;
    color: inherit;
    background: var(--bg-primary, #fff);
    text-align: left;
    cursor: pointer;
}

.agent-eval-history-item:hover,
.agent-eval-history-item.is-latest {
    border-color: #0f766e;
}

.agent-eval-history-item strong {
    color: var(--text-primary, #0f172a);
    font-size: 0.88rem;
    font-weight: 750;
}

.agent-eval-history-item span,
.agent-eval-history-item small {
    color: var(--text-secondary);
    font-size: 11px;
}

.agent-eval-run-detail {
    margin-top: 16px;
}

.agent-eval-batch-summary {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    border-block: 1px solid var(--border-color);
}

.agent-eval-batch-summary>div {
    display: grid;
    min-height: 84px;
    align-content: center;
    gap: 5px;
    padding: 10px 12px;
}

.agent-eval-batch-summary small {
    color: var(--text-secondary);
    font-size: 10px;
}

.agent-eval-batch-summary small.up {
    color: #047857;
}

.agent-eval-batch-summary small.down,
.agent-eval-error {
    color: #b91c1c;
}

.agent-eval-results {
    display: grid;
    gap: 8px;
    margin-top: 12px;
}

.agent-eval-result {
    border: 1px solid var(--border-color);
    border-left: 3px solid #94a3b8;
    border-radius: 6px;
    background: var(--bg-primary);
}

.agent-eval-result.passed {
    border-left-color: #059669;
}

.agent-eval-result.failed,
.agent-eval-result.error {
    border-left-color: #dc2626;
}

.agent-eval-result>summary {
    display: flex;
    min-height: 60px;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 10px 12px;
    cursor: pointer;
}

.agent-eval-result>summary>span {
    display: grid;
    min-width: 0;
    gap: 4px;
}

.agent-eval-result>summary>span:last-child {
    flex: 0 0 auto;
    justify-items: end;
}

.agent-eval-result>summary strong,
.agent-eval-result>summary em {
    color: var(--text-primary);
    font-size: 13px;
    font-style: normal;
}

.agent-eval-result>summary small {
    color: var(--text-secondary);
    font-size: 11px;
}

.agent-eval-result-body {
    display: grid;
    gap: 10px;
    padding: 0 12px 12px;
    border-top: 1px solid var(--border-color);
}

.agent-eval-rules {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    padding-top: 10px;
}

.agent-eval-rule.passed {
    border-color: rgba(5, 150, 105, 0.35);
    color: #047857;
    background: rgba(5, 150, 105, 0.08);
}

.agent-eval-rule.failed {
    border-color: rgba(220, 38, 38, 0.35);
    color: #b91c1c;
    background: rgba(220, 38, 38, 0.07);
}

.agent-eval-output>summary {
    color: var(--text-secondary);
    font-size: 12px;
    cursor: pointer;
}

.agent-eval-editor-overlay {
    z-index: 1970;
}

.agent-eval-editor-modal {
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto;
    width: min(880px, calc(100vw - 32px));
    max-width: 880px;
    height: min(710px, calc(100vh - 32px));
    max-height: min(710px, calc(100vh - 32px));
    padding: 0;
    overflow: hidden;
    text-align: left;
}

.agent-eval-editor-modal .agent-config-modal-head,
.agent-eval-editor-footer {
    padding: 10px 16px;
}

.agent-eval-editor-heading {
    min-width: 0;
}

.agent-eval-editor-modal .agent-config-modal-head p {
    margin: 2px 0 0;
    color: var(--text-secondary);
    font-size: 12px;
}

.agent-eval-editor-body {
    min-height: 0;
    padding: 10px 16px;
    overflow-y: auto;
    overflow-x: hidden;
    background: var(--bg-secondary);
}

.agent-eval-editor-section+.agent-eval-editor-section {
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid var(--border-color);
}

.agent-eval-editor-section-head {
    margin-bottom: 6px;
}

.agent-eval-editor-section-head strong,
.agent-eval-editor-case-toolbar strong {
    color: var(--text-primary);
    font-size: 13px;
}

.agent-eval-suite-fields,
.agent-eval-case-fields {
    gap: 8px 10px;
}

.agent-eval-editor-modal .modal-form-field {
    gap: 4px;
}

.agent-eval-editor-case-toolbar>div {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.agent-eval-editor-case-toolbar>div span {
    color: var(--text-secondary);
    font-size: 11px;
}

.agent-eval-editor-case-toolbar {
    margin: 0 0 6px;
}

.agent-eval-editor-cases {
    display: grid;
    gap: 8px;
}

.agent-eval-case-editor {
    padding: 8px 12px;
    border: 1px solid var(--border-color);
    border-radius: 6px;
    background: var(--bg-primary);
}

.agent-eval-case-editor-head {
    margin-bottom: 6px;
}

.agent-eval-case-editor-head strong {
    color: var(--text-primary);
    font-size: 13px;
}

.agent-eval-case-editor-head .btn-danger-outline {
    height: 26px;
    padding: 0 8px;
    font-size: 12px;
}

.agent-eval-case-advanced {
    margin-top: 6px;
    padding-top: 6px;
    border-top: 1px solid var(--border-color);
    color: var(--text-secondary);
    font-size: 12px;
}

.agent-eval-case-advanced>summary {
    width: fit-content;
    color: var(--text-primary);
    font-weight: 700;
    cursor: pointer;
}

.agent-eval-case-advanced>.modal-form-field {
    margin-top: 6px;
}

.agent-eval-code {
    font-family: Consolas, "Courier New", monospace;
    font-size: 12px;
}

.agent-eval-editor-footer {
    justify-content: flex-end;
    border-top: 1px solid var(--border-color);
    background: var(--bg-primary);
}

.agent-eval-editor-footer .btn-primary,
.agent-eval-editor-footer .btn-secondary {
    min-width: 68px;
    height: 32px;
}

#agent-config-modal[data-agent-config-section="evaluations"] .agent-config-modal.is-empty {
    height: min(540px, calc(100vh - 32px));
}

#agent-config-modal[data-agent-config-section="evaluations"] .agent-config-modal.is-empty .agent-config-modal-body,
#agent-config-modal[data-agent-config-section="evaluations"] .agent-config-modal.is-empty .agent-collapse-evaluations[open] {
    flex: 0 0 auto;
}

#agent-config-modal[data-agent-config-section="evaluations"] .agent-config-modal.is-empty .agent-config-modal-body,
#agent-config-modal[data-agent-config-section="evaluations"] .agent-config-modal.is-empty .agent-collapse-evaluations[open] .agent-collapse-body {
    overflow: visible;
}

#agent-config-modal[data-agent-config-section="evaluations"] .agent-config-modal.is-empty .agent-eval-layout.is-empty {
    min-height: 250px;
}

body.dark-mode .agent-eval-rule.passed,
.dark-mode .agent-eval-rule.passed,
body.dark-mode .agent-eval-batch-summary small.up,
.dark-mode .agent-eval-batch-summary small.up {
    color: #6ee7b7;
}

body.dark-mode .agent-eval-rule.failed,
.dark-mode .agent-eval-rule.failed,
body.dark-mode .agent-eval-batch-summary small.down,
.dark-mode .agent-eval-batch-summary small.down,
body.dark-mode .agent-eval-error,
.dark-mode .agent-eval-error {
    color: #fca5a5;
}

@media (max-width: 820px) {
    #agent-config-modal[data-agent-config-section="evaluations"] .agent-config-modal {
        width: calc(100vw - 16px);
        height: calc(100vh - 16px);
        max-height: calc(100vh - 16px);
    }

    #agent-config-modal[data-agent-config-section="evaluations"] .agent-config-modal-body {
        overflow: auto;
    }

    #agent-config-modal[data-agent-config-section="evaluations"] .agent-collapse-evaluations[open] .agent-collapse-body {
        overflow: visible;
    }

    .agent-eval-overview {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .agent-eval-layout {
        grid-template-columns: 1fr;
    }

    .agent-eval-suite-list {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
        padding-right: 0;
        border-right: 0;
        border-bottom: 1px solid var(--border-color);
    }

    .agent-eval-suite-detail {
        padding-left: 0;
    }

}

@media (max-width: 560px) {

    .agent-eval-toolbar,
    .agent-eval-detail-head {
        align-items: stretch;
        flex-direction: column;
    }

    .agent-eval-toolbar-actions,
    .agent-eval-detail-actions {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .agent-eval-detail-actions .btn-primary {
        grid-column: 1 / -1;
    }

    .agent-eval-batch-summary {
        grid-template-columns: 1fr;
    }

    .agent-eval-editor-modal {
        width: calc(100vw - 16px);
        height: calc(100vh - 16px);
    }

    .agent-eval-editor-modal .agent-config-modal-head,
    .agent-eval-editor-footer {
        padding-inline: 14px;
    }

    .agent-eval-editor-body {
        padding: 14px;
    }
}

/* === styles/workspaces/agent/agent-run-dag-artifacts.css === */
/* 拆自 agent-runs.css。 */
/* Agent DAG 运行时节点、产物、版本列表与空状态样式。 */
.agent-dag-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 10px;
}

.agent-dag-node {
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 8px;
    padding: 9px 10px;
    background: linear-gradient(180deg, #fff 0%, rgba(248, 250, 252, 0.72) 100%);
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03);
}

.agent-dag-node.completed {
    border-color: rgba(16, 185, 129, 0.34);
    background: linear-gradient(180deg, #fff 0%, rgba(236, 253, 245, 0.62) 100%);
}

.agent-dag-node.error {
    border-color: rgba(239, 68, 68, 0.35);
    background: linear-gradient(180deg, #fff 0%, rgba(254, 242, 242, 0.68) 100%);
}

.agent-dag-node-rerun {
    margin: 6px 0 2px;
    height: 28px;
    padding: 0 10px;
    border-radius: 7px;
