.pivot-dag-editor-wrap {
    display: grid;
    grid-template-rows: auto 1fr;
    gap: 8px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--bg-secondary);
    padding: 8px;
    min-height: 360px;
}

.agent-config-modal-body .pivot-dag-editor-wrap {
    min-height: 68vh;
    height: min(72vh, 760px);
    grid-template-rows: auto minmax(480px, 1fr);
}

.pivot-dag-editor-toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    align-items: center;
    padding: 6px 0 8px;
    border-bottom: 1px solid var(--border);
}

.pivot-dag-toolbar-group {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
    min-height: 38px;
    padding: 5px 6px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 8px;
    background: rgba(248, 250, 252, 0.82);
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
