    border-color: rgba(16, 163, 127, 0.28);
    background: rgba(16, 163, 127, 0.06);
}

.pivot-dag-toolbar-group.is-template-group {
    border-color: rgba(99, 102, 241, 0.28);
    background: rgba(99, 102, 241, 0.06);
}

.pivot-dag-toolbar-dropdown {
    position: relative;
    flex: 0 0 auto;
}

.pivot-dag-toolbar-dropdown[open] {
    z-index: 20;
}

.pivot-dag-toolbar-summary {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 74px;
    height: 32px;
    padding: 0 13px;
    border: 1px solid rgba(148, 163, 184, 0.34);
    border-radius: 7px;
    background: #fff;
    color: var(--text-main);
    cursor: pointer;
    font-size: 0.78rem;
    font-weight: 800;
    line-height: 1;
    list-style: none;
    white-space: nowrap;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.05);
}

.pivot-dag-toolbar-summary::marker {
    content: "";
    font-size: 0;
}

.pivot-dag-toolbar-summary::-webkit-details-marker {
    display: none;
}

.pivot-dag-toolbar-summary::after {
    display: none;
    content: none;
