    padding: 0 12px;
    border-radius: 8px;
}

.agent-dag-workspace-view {
    background: #f8fafc;
}

.agent-dag-modal {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.agent-dag-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 18px 12px;
    border-bottom: 1px solid var(--border);
    background: #fff;
}

.agent-dag-modal-header p {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.78rem;
    line-height: 1.4;
}

.agent-dag-header-actions {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    justify-content: flex-end;
}

.agent-dag-header-actions .btn-secondary,
.agent-dag-header-actions .btn-primary {
    height: 32px;
    padding: 0 12px;
    border-radius: 8px;
}

.automation-assets-view {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 14px;
    overflow: hidden;
    background: #f8fafc;
}

.automation-summary-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
    flex: 0 0 auto;
}

.automation-summary-item {
    min-width: 0;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas: "label value" "meta value";
    gap: 3px 14px;
    align-items: center;
    padding: 12px 14px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 8px;
    background: #fff;
}

.automation-summary-item span {
    grid-area: label;
    color: var(--text-main);
    font-size: 0.8rem;
    font-weight: 750;
}

.automation-summary-item strong {
    grid-area: value;
    color: var(--text-main);
    font-size: 1.35rem;
    line-height: 1;
}

.automation-summary-item small {
    grid-area: meta;
    color: var(--text-muted);
    font-size: 0.68rem;
}

.automation-assets-toolbar {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.automation-assets-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    min-width: 0;
}

.automation-assets-actions > button,
.automation-assets-actions .btn-primary,
.automation-assets-actions .btn-secondary,
.automation-assets-actions .btn-xs {
    height: 28px !important;
    line-height: 26px !important;
    padding: 0 12px !important;
    font-size: 0.75rem !important;
    font-weight: 500 !important;
    border-radius: 6px !important;
    white-space: nowrap !important;
    box-sizing: border-box !important;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    cursor: pointer;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
    transition: all 0.15s ease;
}

.automation-assets-actions > button.hidden {
    display: none !important;
}

.automation-assets-tabs {
    display: inline-flex;
    padding: 3px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 8px;
    background: #fff;
}

.automation-assets-tab {
    min-width: 92px;
    height: 30px;
    padding: 0 12px;
    border: 0;
    border-radius: 6px;
    background: transparent;
    color: #64748b;
    font-size: 0.76rem;
    font-weight: 700;
    cursor: pointer;
}

.automation-assets-tab.active {
    background: #f1f5f9;
    color: var(--primary);
}

.automation-assets-search {
