    padding: 0 12px 0 34px;
    font-size: 0.78rem;
}

.automation-assets-panel {
    flex: 1;
    min-height: 0;
    overflow: auto;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 8px;
    background: #fff;
}

.automation-table-wrap {
    min-width: 960px;
}

.automation-schedules-table {
    min-width: 1120px;
}

.automation-workflows-table {
    min-width: 1400px;
}

.automation-assets-table {
