    table-layout: fixed;
}

.automation-assets-table th,
.automation-assets-table td {
    height: 36px;
    min-height: 36px;
    padding: 6px 10px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
    color: var(--text-secondary, #334155);
    font-size: 0.74rem;
    line-height: 1.3;
    box-sizing: border-box;
    vertical-align: middle;
}

.automation-assets-table th {
    position: sticky;
    top: 0;
    z-index: 1;
    height: 36px;
    min-height: 36px;
    background: #f8fafc;
    color: #475569;
    font-size: 0.72rem;
    font-weight: 700;
    text-align: left;
    border-bottom: 1px solid rgba(148, 163, 184, 0.22);
    letter-spacing: 0.01em;
}

.automation-assets-table th:first-child,
.automation-assets-table td:first-child {
    width: 28%;
}

.automation-assets-table th:last-child,
.automation-assets-table td:last-child {
    width: 320px;
}

.automation-workflows-table th:first-child,
.automation-workflows-table td:first-child {
    width: 54px;
}

.automation-workflows-table th:nth-child(2),
.automation-workflows-table td:nth-child(2) {
    width: 180px;
}

.automation-workflows-table th:nth-child(3),
.automation-workflows-table td:nth-child(3) {
    width: 240px;
