}

.automation-workflows-table th:last-child,
.automation-workflows-table td:last-child {
    width: 390px;
}

.automation-schedules-table th:last-child,
.automation-schedules-table td:last-child {
    width: 390px;
}

.automation-assets-table td > strong,
.automation-assets-table td > small {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.automation-assets-table td > strong {
    color: var(--text-main);
