/* === styles/workspaces/agent/agent-dag-workbench.css === */
/* 拆自 agent-dag-shell.css。 */
/* DAG 工作台嵌入规则样式。 */
.agent-dag-workbench {
    flex: 1;
    position: relative;
    min-height: 0;
    padding: 12px 14px 14px;
    display: grid;
    grid-template-rows: minmax(0, 1fr);
    gap: 0;
    overflow: hidden;
}

.agent-dag-inputs-panel {
    flex: 0 0 auto;
    margin: 8px 14px 0;
    padding: 10px 12px;
    border: 1px solid rgba(16, 185, 129, 0.28);
    border-radius: 7px;
    background: rgba(236, 253, 245, 0.72);
}

.agent-dag-inputs-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.agent-dag-inputs-head > div { display: flex; align-items: baseline; gap: 8px; }
.agent-dag-inputs-head span, .agent-dag-input-item small { color: #64748b; font-size: 12px; }
.agent-dag-inputs-list { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 8px; margin-top: 8px; }
.agent-dag-input-item { display: grid; gap: 4px; min-width: 0; }
.agent-dag-input-item > span { font-size: 12px; font-weight: 700; }
.agent-dag-input-item em { margin-left: 6px; color: #dc2626; font-size: 10px; font-style: normal; }
.agent-dag-input-item textarea { resize: vertical; }

.agent-dag-workbench .pivot-dag-editor-wrap {
    min-height: 0;
    height: auto;
    grid-template-rows: auto minmax(0, 1fr);
}

.agent-dag-workbench .pivot-dag-editor-canvas {
    min-height: 0;
    max-height: none;
}


/* === styles/workspaces/agent/agent-dag-node-library.css === */
/* Dify 风格左侧节点类型库面板样式 */

.pivot-node-library {
    display: flex;
    flex-direction: column;
    gap: 8px;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    padding: 10px 8px;
    overflow: hidden;
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 8px;
    background: #fff;
}

.pivot-node-library-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex: 0 0 auto;
    padding: 0 2px 6px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.22);
}

.pivot-node-library-collapse {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    padding: 0;
    border: 1px solid rgba(148, 163, 184, 0.36);
    border-radius: 5px;
    background: transparent;
    color: #94a3b8;
    cursor: pointer;
    font-size: 12px;
    line-height: 1;
    transition: background 0.14s, color 0.14s, border-color 0.14s;
}

.pivot-node-library-collapse:hover {
    border-color: #3b82f6;
    background: rgba(59, 130, 246, 0.08);
    color: #2563eb;
}

.pivot-node-library-title {
    color: #0f172a;
    font-size: 0.82rem;
    font-weight: 800;
    letter-spacing: 0.02em;
}

.pivot-node-library-search-wrap {
    flex: 0 0 auto;
}

.pivot-node-library-search {
    box-sizing: border-box;
    width: 100%;
    height: 28px;
    padding: 0 8px;
    border: 1px solid rgba(148, 163, 184, 0.4);
    border-radius: 6px;
    background: #f8fafc;
    color: #0f172a;
    font-family: inherit;
    font-size: 0.75rem;
}

.pivot-node-library-search:focus {
    border-color: #3b82f6;
    background: #fff;
    outline: none;
}

.pivot-node-library-groups {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    gap: 10px;
    min-height: 0;
    overflow-x: hidden;
    overflow-y: auto;
    padding-right: 2px;
}

.pivot-node-library-group {
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.pivot-node-library-group-label {
    padding: 0 2px;
    color: #64748b;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.pivot-node-library-items {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.pivot-node-library-card {
    display: grid;
    grid-template-columns: 22px minmax(0, 1fr);
    grid-template-rows: auto auto;
    align-items: center;
    column-gap: 7px;
    row-gap: 1px;
    width: 100%;
    padding: 7px 8px;
    border: 1px solid rgba(148, 163, 184, 0.3);
    border-radius: 7px;
    background: #fff;
    cursor: pointer;
    font-family: inherit;
    text-align: left;
    transition: border-color 0.15s ease, background 0.15s ease, transform 0.1s ease;
}

.pivot-node-library-card:hover {
    border-color: #3b82f6;
    background: rgba(59, 130, 246, 0.05);
    transform: translateY(-1px);
}

.pivot-node-library-card:disabled {
    cursor: not-allowed;
    opacity: 0.55;
    transform: none;
}

.pivot-node-library-card:disabled:hover {
    border-color: rgba(148, 163, 184, 0.3);
    background: #fff;
}

.pivot-node-library-card:active {
    transform: translateY(0);
}

.pivot-node-library-card:focus-visible {
    border-color: #2563eb;
    outline: 2px solid rgba(59, 130, 246, 0.4);
    outline-offset: 1px;
}

.pivot-node-library-card-icon {
    display: flex;
    grid-row: 1 / 3;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    border-radius: 5px;
    background: rgba(15, 23, 42, 0.05);
    font-size: 12px;
    line-height: 1;
}

.pivot-node-library-card-icon svg {
    width: 14px;
    height: 14px;
}

.pivot-node-library-card-label {
    grid-column: 2;
    min-width: 0;
    overflow: hidden;
    color: #0f172a;
    font-size: 0.76rem;
    font-weight: 800;
    line-height: 1.25;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.pivot-node-library-card-desc {
    grid-column: 2;
    display: -webkit-box;
    min-width: 0;
    overflow: hidden;
    color: #64748b;
    font-size: 0.66rem;
    line-height: 1.35;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}

.pivot-node-library-empty {
    padding: 16px 8px;
    color: #94a3b8;
    font-size: 0.72rem;
    text-align: center;
}

.pivot-node-library-advanced-toggle {
    width: 100%;
    min-height: 30px;
    margin-top: 2px;
    padding: 5px 8px;
    border: 1px dashed rgba(100, 116, 139, 0.45);
    border-radius: 7px;
    background: rgba(248, 250, 252, 0.9);
    color: #475569;
    cursor: pointer;
    font: inherit;
    font-size: 0.7rem;
    font-weight: 700;
    text-align: center;
}

.pivot-node-library-advanced-toggle:hover,
.pivot-node-library-advanced-toggle:focus-visible {
    border-color: #3b82f6;
    background: rgba(239, 246, 255, 0.9);
    color: #1d4ed8;
    outline: none;
}

/* 节点类型主题色（与画布节点保持一致） */
.pivot-node-library-card-icon.is-llm      { background: rgba(13, 148, 136, 0.12); color: #0f766e; }
.pivot-node-library-card-icon.is-delegate { background: rgba(124, 58, 237, 0.12); color: #6d28d9; }
.pivot-node-library-card-icon.is-handoff  { background: rgba(168, 85, 247, 0.12); color: #9333ea; }
.pivot-node-library-card-icon.is-code     { background: rgba(234, 88, 12, 0.12); color: #c2410c; }
.pivot-node-library-card-icon.is-http     { background: rgba(37, 99, 235, 0.12); color: #1d4ed8; }
.pivot-node-library-card-icon.is-merge    { background: rgba(22, 163, 74, 0.12); }
.pivot-node-library-card-icon.is-rag      { background: rgba(2, 132, 199, 0.12); color: #0369a1; }
.pivot-node-library-card-icon.is-db       { background: rgba(71, 85, 105, 0.12); color: #475569; }
.pivot-node-library-card-icon.is-viz      { background: rgba(161, 98, 7, 0.12); color: #a16207; }
.pivot-node-library-card-icon.is-report   { background: rgba(225, 29, 72, 0.12); color: #be123c; }
.pivot-node-library-card-icon.is-input    { background: rgba(5, 150, 105, 0.12); color: #047857; }
.pivot-node-library-card-icon.is-output   { background: rgba(13, 148, 136, 0.12); color: #0f766e; }
.pivot-node-library-card-icon.is-condition{ background: rgba(217, 119, 6, 0.12); color: #b45309; }
.pivot-node-library-card-icon.is-approval { background: rgba(225, 29, 72, 0.12); color: #be123c; }
.pivot-node-library-card-icon.is-loop     { background: rgba(37, 99, 235, 0.12); color: #1d4ed8; }
.pivot-node-library-card-icon.is-subflow  { background: rgba(71, 85, 105, 0.12); color: #475569; }
.pivot-node-library-card-icon.is-delay    { background: rgba(161, 98, 7, 0.12); color: #a16207; }

/* ── 深色模式 ─────────────────────────────── */
body.dark-mode .pivot-node-library,
.dark-mode .pivot-node-library {
    border-color: rgba(148, 163, 184, 0.22);
    background: #0f172a;
}

body.dark-mode .pivot-node-library-header,
.dark-mode .pivot-node-library-header {
