}

/* ── 画布容器：为左侧面板腾出空间 ─────────── */
.pivot-dag-editor-canvas.has-node-library {
    padding-left: 204px;
}

.pivot-dag-node-library-host {
    position: absolute;
    top: 10px;
    bottom: 10px;
    left: 10px;
    z-index: 7;
    width: 188px;
    pointer-events: auto;
