    display: flex;
    max-width: 320px;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 18px 22px;
    border: 1px dashed rgba(148, 163, 184, 0.5);
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.86);
    pointer-events: none;
    text-align: center;
