    font-size: 0.84rem;
    font-weight: 800;
}

.pivot-dag-empty-hint small {
    color: #64748b;
    font-size: 0.72rem;
    line-height: 1.5;
}

body.dark-mode .pivot-dag-empty-hint,
.dark-mode .pivot-dag-empty-hint {
    border-color: rgba(148, 163, 184, 0.32);
    background: rgba(15, 23, 42, 0.82);
}

body.dark-mode .pivot-dag-empty-hint strong,
.dark-mode .pivot-dag-empty-hint strong {
