}

body.dark-mode .pivot-dag-empty-hint small,
.dark-mode .pivot-dag-empty-hint small {
    color: #94a3b8;
}

/* 折叠切换按钮 */
.pivot-node-library-toggle {
    position: absolute;
    top: 10px;
    left: 10px;
    z-index: 8;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    padding: 0;
    border: 1px solid rgba(148, 163, 184, 0.4);
