/* === styles/workspaces/agent/agent-dag-svg.css === */
/* 拆自 agent-dag-editor.css。 */
/* DAG SVG 节点、端口、连线与基础图形元素样式。 */
/* Pivot DAG 编辑器、检查器、向导、JSON 编辑器与小地图样式。拆自 agent.css。 */
.pivot-dag-svg {
    display: block;
    width: 100%;
    height: 100%;
    min-height: 100%;
    user-select: none;
    -webkit-user-select: none;
    cursor: grab;
}

.pivot-dag-node {
    cursor: grab;
}

.pivot-dag-node:active {
    cursor: grabbing;
}

.pivot-dag-node-body {
    fill: #fff;
    stroke: rgba(148, 163, 184, 0.6);
    stroke-width: 1.5;
    transition: fill 0.15s ease, stroke 0.15s ease;
}

.pivot-dag-node.is-llm .pivot-dag-node-body {
    fill: #f0fdfa;
    stroke: rgba(13, 148, 136, 0.7);
}

.pivot-dag-node.is-selected .pivot-dag-node-body {
    fill: rgba(59, 130, 246, 0.08);
    stroke: #3b82f6;
}

.pivot-dag-node.has-warning .pivot-dag-node-body {
    fill: #fffbeb;
    stroke: rgba(245, 158, 11, 0.72);
}

.pivot-dag-node-title {
    fill: #0f172a;
    font-size: 12px;
    font-weight: 800;
    pointer-events: none;
}

.pivot-dag-node-tool-foreign {
    pointer-events: none;
}

.pivot-dag-node-tool {
    box-sizing: border-box;
    display: grid;
    grid-template-columns: 12px minmax(0, 1fr);
    grid-template-rows: 14px 14px;
    column-gap: 4px;
    width: 100%;
    height: 30px;
    min-width: 0;
    overflow: hidden;
    color: #64748b;
    font-family: inherit;
    font-size: 9px;
    font-weight: 700;
    line-height: 1.15;
    pointer-events: none;
}

.pivot-dag-node-tool-arrow {
    grid-row: 1 / 3;
    align-self: start;
    padding-top: 1px;
    color: #64748b;
    font-size: 10px;
    font-weight: 800;
    line-height: 13px;
}

.pivot-dag-node-tool-name {
    align-self: center;
    min-width: 0;
    overflow: hidden;
    color: #334155;
    font-size: 10px;
    font-weight: 800;
    line-height: 13px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.pivot-dag-node-tool-id {
    display: inline-flex;
    align-items: center;
    align-self: center;
    min-width: 0;
    width: fit-content;
    max-width: 100%;
    height: 14px;
    padding: 0 6px;
    overflow: hidden;
    border: 1px solid rgba(37, 99, 235, 0.14);
    border-radius: 5px;
    background: rgba(59, 130, 246, 0.07);
    color: #475569;
    font-family: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", Menlo, monospace;
    font-size: 8.5px;
    font-weight: 700;
    line-height: 14px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.pivot-dag-node-tool.is-empty {
    color: #b45309;
}

.pivot-dag-node-tool.is-empty .pivot-dag-node-tool-name {
    color: #b45309;
}

.pivot-dag-node.is-selected .pivot-dag-node-tool-id {
    border-color: rgba(37, 99, 235, 0.26);
    background: rgba(59, 130, 246, 0.12);
    color: #1d4ed8;
}

.pivot-dag-port {
    fill: #fff;
    stroke: #94a3b8;
    stroke-width: 1.5;
    cursor: crosshair;
    transition: fill 0.15s ease;
}

.pivot-dag-port:hover {
    fill: #3b82f6;
    stroke: #2563eb;
}

.pivot-dag-edge {
    fill: none;
    stroke: #94a3b8;
    stroke-width: 1.5;
    pointer-events: none;
}

.pivot-dag-edge-hit {
    fill: none;
    stroke: transparent;
    stroke-width: 14;
    cursor: pointer;
    pointer-events: stroke;
}

.pivot-dag-edge-group.is-selected .pivot-dag-edge {
    stroke: #2563eb;
    stroke-width: 2.5;
}

.pivot-dag-edge-label {
    fill: #64748b;
    font-size: 10px;
    font-weight: 700;
    paint-order: stroke;
    pointer-events: none;
    stroke: #fff;
    stroke-width: 4px;
}

.pivot-dag-selection-box {
    fill: rgba(37, 99, 235, 0.08);
    stroke: #2563eb;
    stroke-dasharray: 5 3;
    stroke-width: 1.5;
    pointer-events: none;
}

.pivot-dag-edge-ghost {
    stroke-dasharray: 4 3;
    opacity: 0.7;
}

body.dark-mode .pivot-dag-node.is-llm .pivot-dag-node-body,
.dark-mode .pivot-dag-node.is-llm .pivot-dag-node-body {
    fill: #102f2b;
    stroke: rgba(45, 212, 191, 0.72);
}

/* ── 节点类型主题色 ───────────────────────────── */
.pivot-dag-node.is-code .pivot-dag-node-body   { fill: #fff7ed; stroke: rgba(234, 88, 12, 0.55); }
.pivot-dag-node.is-http .pivot-dag-node-body   { fill: #eff6ff; stroke: rgba(37, 99, 235, 0.55); }
.pivot-dag-node.is-merge .pivot-dag-node-body  { fill: #f0fdf4; stroke: rgba(22, 163, 74, 0.55); }
.pivot-dag-node.is-delegate .pivot-dag-node-body{ fill: #faf5ff; stroke: rgba(124, 58, 237, 0.55); }
.pivot-dag-node.is-handoff .pivot-dag-node-body { fill: #fdf4ff; stroke: rgba(168, 85, 247, 0.55); }
.pivot-dag-node.is-rag .pivot-dag-node-body    { fill: #f0f9ff; stroke: rgba(2, 132, 199, 0.55); }
.pivot-dag-node.is-db .pivot-dag-node-body     { fill: #f8fafc; stroke: rgba(71, 85, 105, 0.55); }
.pivot-dag-node.is-viz .pivot-dag-node-body    { fill: #fefce8; stroke: rgba(161, 98, 7, 0.55); }
.pivot-dag-node.is-report .pivot-dag-node-body { fill: #fff1f2; stroke: rgba(225, 29, 72, 0.45); }
.pivot-dag-node.is-mcp .pivot-dag-node-body    { fill: #f5f3ff; stroke: rgba(109, 40, 217, 0.45); }
.pivot-dag-node.is-input .pivot-dag-node-body  { fill: #ecfdf5; stroke: rgba(5, 150, 105, 0.55); }
.pivot-dag-node.is-output .pivot-dag-node-body { fill: #f0fdfa; stroke: rgba(13, 148, 136, 0.55); }
.pivot-dag-node.is-condition .pivot-dag-node-body { fill: #fff7ed; stroke: rgba(217, 119, 6, 0.58); }
.pivot-dag-node.is-approval .pivot-dag-node-body { fill: #fff1f2; stroke: rgba(225, 29, 72, 0.52); }
.pivot-dag-node.is-loop .pivot-dag-node-body { fill: #eff6ff; stroke: rgba(37, 99, 235, 0.5); }
.pivot-dag-node.is-subflow .pivot-dag-node-body { fill: #f8fafc; stroke: rgba(71, 85, 105, 0.55); }
.pivot-dag-node.is-delay .pivot-dag-node-body { fill: #fefce8; stroke: rgba(161, 98, 7, 0.5); }

/* 深色模式 */
body.dark-mode .pivot-dag-node.is-code .pivot-dag-node-body,
.dark-mode .pivot-dag-node.is-code .pivot-dag-node-body    { fill: #1c0f00; stroke: rgba(251, 146, 60, 0.6); }
body.dark-mode .pivot-dag-node.is-http .pivot-dag-node-body,
.dark-mode .pivot-dag-node.is-http .pivot-dag-node-body    { fill: #0c1a36; stroke: rgba(96, 165, 250, 0.6); }
body.dark-mode .pivot-dag-node.is-merge .pivot-dag-node-body,
.dark-mode .pivot-dag-node.is-merge .pivot-dag-node-body   { fill: #052e16; stroke: rgba(74, 222, 128, 0.6); }
body.dark-mode .pivot-dag-node.is-delegate .pivot-dag-node-body,
.dark-mode .pivot-dag-node.is-delegate .pivot-dag-node-body{ fill: #1e1030; stroke: rgba(167, 139, 250, 0.6); }
body.dark-mode .pivot-dag-node.is-rag .pivot-dag-node-body,
.dark-mode .pivot-dag-node.is-rag .pivot-dag-node-body     { fill: #082030; stroke: rgba(56, 189, 248, 0.6); }

/* ── 节点图标 ───────────────────────────────── */
.pivot-dag-node-icon-foreign { pointer-events: none; overflow: visible; }
.pivot-dag-node-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    border-radius: 4px;
    font-size: 11px;
    line-height: 1;
    pointer-events: none;
    user-select: none;
    background: rgba(0,0,0,0.04);
}

.pivot-dag-node-icon svg {
    width: 12px;
    height: 12px;
}

/* ── 运行状态徽章 ──────────────────────────── */
.pivot-dag-run-badge-foreign { pointer-events: none; overflow: visible; }
.pivot-dag-run-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 20px;
    height: 18px;
    padding: 0 4px;
    border-radius: 10px;
    font-size: 10px;
    font-weight: 800;
    line-height: 1;
    pointer-events: none;
}

.pivot-dag-run-badge.is-running  { background: #dbeafe; color: #1d4ed8; border: 1.5px solid #93c5fd; }
.pivot-dag-run-badge.is-completed{ background: #dcfce7; color: #15803d; border: 1.5px solid #86efac; }
.pivot-dag-run-badge.is-error    { background: #fee2e2; color: #dc2626; border: 1.5px solid #fca5a5; }
.pivot-dag-run-badge.is-continued_error { background: #ffedd5; color: #c2410c; border: 1.5px solid #fdba74; }
.pivot-dag-run-badge.is-skipped  { background: #f1f5f9; color: #64748b; border: 1.5px solid #cbd5e1; }

/* 节点边框光晕动画（运行中）*/
.pivot-dag-node-pulse {
    fill: none;
    stroke: #3b82f6;
    stroke-width: 2.5;
    opacity: 0;
    animation: pivot-dag-pulse 1.4s ease-in-out infinite;
}
@keyframes pivot-dag-pulse {
    0%, 100% { opacity: 0; stroke-width: 2.5; }
    50%       { opacity: 0.6; stroke-width: 4; }
}

/* 运行中 spinner（纯 CSS） */
.pivot-dag-run-spinner {
    display: inline-block;
    width: 9px;
    height: 9px;
    border: 1.5px solid #93c5fd;
    border-top-color: #1d4ed8;
    border-radius: 50%;
    animation: pivot-dag-spin 0.7s linear infinite;
}
@keyframes pivot-dag-spin {
    to { transform: rotate(360deg); }
}

/* 节点边框：各运行状态 */
.pivot-dag-node.run-running .pivot-dag-node-body  { stroke: #3b82f6; stroke-width: 2; }
.pivot-dag-node.run-completed .pivot-dag-node-body{ stroke: #22c55e; stroke-width: 2; }
.pivot-dag-node.run-error .pivot-dag-node-body    { stroke: #ef4444; stroke-width: 2; }
.pivot-dag-node.run-continued_error .pivot-dag-node-body { stroke: #f97316; stroke-width: 2; }
.pivot-dag-node.run-skipped .pivot-dag-node-body  { opacity: 0.55; }


/* === styles/workspaces/agent/agent-dag-drawer-inspector.css === */
/* 拆自 agent-dag-editor.css。 */
/* DAG 节点抽屉、检查器行、工具元数据与检查器响应式布局样式。 */
.agent-dag-node-drawer {
    position: absolute;
    top: 12px;
    right: 14px;
    bottom: 14px;
    z-index: 8;
    width: min(500px, calc(100% - 28px));
    pointer-events: none;
}

.agent-dag-node-drawer.hidden {
    display: none;
}

.agent-dag-node-drawer-panel {
    height: 100%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    pointer-events: auto;
    border: 1px solid rgba(148, 163, 184, 0.35);
    border-radius: 8px;
    background: #fff;
    box-shadow: 0 18px 44px rgba(15, 23, 42, 0.18);
}

.agent-dag-drawer-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    padding: 12px 12px 10px;
    border-bottom: 1px solid var(--border);
    background: #f8fafc;
}

.agent-dag-drawer-head h3 {
    margin: 0;
    color: var(--text-main);
    font-size: 0.92rem;
    line-height: 1.25;
}

.agent-dag-drawer-head span {
    display: block;
    max-width: 350px;
    margin-top: 3px;
    color: var(--text-muted);
    font-size: 0.7rem;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.agent-dag-drawer-actions {
    display: flex;
    align-items: center;
    gap: 6px;
    flex: 0 0 auto;
}

.agent-dag-drawer-actions .btn-secondary,
.agent-dag-drawer-actions .btn-danger-outline {
    height: 28px;
    padding: 0 10px;
    border-radius: 7px;
    font-size: 0.72rem;
}

.pivot-dag-editor-inspector {
    flex: 1;
    min-height: 0;
    overflow: auto;
    padding: 12px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    font-size: 0.78rem;
}

.pivot-dag-editor-inspector > .pivot-dag-inspector-row-main { order: 1; }
.pivot-dag-editor-inspector > .pivot-dag-inspector-row-tool { order: 2; }
.pivot-dag-editor-inspector > .pivot-dag-input-overview { order: 3; }
.pivot-dag-editor-inspector > .pivot-dag-inspector-depends { order: 4; }
.pivot-dag-editor-inspector > .pivot-dag-when-panel { order: 5; }
.pivot-dag-editor-inspector > .pivot-dag-inspector-row-runtime { order: 6; }
.pivot-dag-editor-inspector > .pivot-dag-tool-meta { order: 7; }
.pivot-dag-editor-inspector > .pivot-dag-contract-panel { order: 8; }

.pivot-dag-runtime-settings {
    order: 6;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 8px;
    background: #f8fafc;
}

.pivot-dag-runtime-settings > summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 34px;
    padding: 0 10px;
    color: var(--text-main);
    cursor: pointer;
    font-size: 0.72rem;
    list-style: none;
}

.pivot-dag-runtime-settings > summary::-webkit-details-marker {
    display: none;
}

.pivot-dag-runtime-settings > summary span {
    color: var(--text-muted);
    font-size: 0.64rem;
    font-weight: 600;
}

.pivot-dag-runtime-settings > .pivot-dag-inspector-row {
    padding: 0 10px 10px;
}

.pivot-dag-inspector-empty {
    color: var(--text-muted);
    font-size: 0.78rem;
    padding: 6px 4px;
}

.pivot-dag-inspector-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 8px;
}

.pivot-dag-inspector-row-main {
    grid-template-columns: minmax(150px, 0.82fr) minmax(180px, 1fr);
}

.pivot-dag-inspector-row-tool {
    grid-template-columns: minmax(0, 1fr) minmax(160px, 0.48fr);
    align-items: end;
}

.pivot-dag-inspector-row-runtime {
    grid-template-columns: minmax(150px, 1fr) minmax(110px, 0.7fr) minmax(130px, 0.85fr);
}

.pivot-dag-inspector-row label,
.pivot-dag-inspector-input {
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.pivot-dag-inspector-row label > span,
.pivot-dag-inspector-input > span {
    color: var(--text-muted);
    font-size: 0.7rem;
}

.pivot-dag-inspector-row input,
.pivot-dag-inspector-row select,
.pivot-dag-inspector-input textarea {
    width: 100%;
    height: 28px;
    padding: 4px 8px;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: #fff;
    color: #0f172a;
    font-size: 0.78rem;
    min-width: 0;
}

.pivot-dag-inspector-row select[data-pivot-dag-field="tool"] {
    font-weight: 700;
    text-overflow: clip;
}

.pivot-dag-tool-field {
    min-width: 0;
}

.pivot-dag-node-id-field input[readonly] {
    border-color: rgba(148, 163, 184, 0.28);
    background: #f8fafc;
    color: #475569;
    cursor: text;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-weight: 700;
}

.pivot-dag-node-id-field small {
    color: var(--text-muted);
    font-size: 0.66rem;
    line-height: 1.35;
}

.pivot-dag-test-result {
    max-height: 220px;
    margin: 10px 0 0;
    padding: 9px;
    overflow: auto;
    border: 1px solid rgba(148, 163, 184, 0.3);
    border-radius: 6px;
    background: #0f172a;
    color: #e2e8f0;
    font-size: 11px;
    line-height: 1.5;
    white-space: pre-wrap;
    word-break: break-word;
}

.pivot-dag-test-result.is-error { border-color: #f87171; color: #fecaca; }
.pivot-dag-test-result.is-success { border-color: #34d399; }

.pivot-dag-tool-meta {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 10px 12px;
    border: 1px solid rgba(16, 185, 129, 0.18);
    border-radius: 8px;
    background: linear-gradient(180deg, rgba(240, 253, 250, 0.92), rgba(248, 250, 252, 0.98));
    box-shadow: inset 3px 0 0 rgba(16, 185, 129, 0.45);
}

.pivot-dag-tool-meta.is-empty {
    border-color: rgba(148, 163, 184, 0.22);
    background: #f8fafc;
    box-shadow: none;
    color: var(--text-muted);
    font-size: 0.7rem;
    line-height: 1.35;
}

.pivot-dag-tool-meta-head {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
    min-width: 0;
}

.pivot-dag-tool-meta-head strong {
    min-width: 0;
    max-width: 100%;
    color: var(--text-main);
    font-size: 0.82rem;
    font-weight: 800;
    line-height: 1.25;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.pivot-dag-tool-meta-badges {
    display: flex;
    justify-content: flex-start;
    gap: 4px;
    flex-wrap: wrap;
    max-width: 55%;
}

.pivot-dag-tool-meta-head em {
    padding: 1px 5px;
    border-radius: 999px;
    background: rgba(16, 163, 127, 0.12);
    color: #047857;
    font-size: 0.62rem;
    font-style: normal;
    font-weight: 800;
    line-height: 1.5;
}

.pivot-dag-tool-meta-body {
    display: grid;
    grid-template-columns: minmax(0, 1fr) max-content;
    gap: 8px;
    align-items: start;
    min-width: 0;
}

.pivot-dag-tool-meta p {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.72rem;
    line-height: 1.45;
    overflow-wrap: anywhere;
    word-break: break-word;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.pivot-dag-tool-meta-id {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 6px;
    align-items: start;
    min-width: 0;
}

.pivot-dag-tool-meta-id span {
    padding-top: 3px;
    color: #047857;
    font-size: 0.66rem;
    font-weight: 800;
    line-height: 1.35;
    white-space: nowrap;
}

.pivot-dag-tool-meta-id code {
    display: block;
    min-width: 0;
    max-width: 100%;
    overflow-wrap: anywhere;
    word-break: break-all;
    padding: 4px 7px;
    border-radius: 6px;
    background: rgba(226, 232, 240, 0.82);
    color: #1e293b;
    font-size: 0.66rem;
    line-height: 1.45;
}

.pivot-dag-tool-meta-technical {
    min-width: 0;
}

.pivot-dag-tool-meta-technical > summary {
    color: #64748b;
    cursor: pointer;
    font-size: 0.64rem;
    font-weight: 700;
    list-style: none;
    text-align: right;
}

.pivot-dag-tool-meta-technical > summary::-webkit-details-marker {
    display: none;
}

.pivot-dag-tool-meta-technical > summary::before {
    content: '›';
    display: inline-block;
    margin-right: 3px;
    transition: transform 0.12s ease;
}

.pivot-dag-tool-meta-technical[open] > summary::before {
    transform: rotate(90deg);
}

.pivot-dag-tool-meta-technical .pivot-dag-tool-meta-id {
    margin-top: 5px;
}

@media (max-width: 520px) {
    .pivot-dag-inspector-row-main,
    .pivot-dag-inspector-row-tool,
    .pivot-dag-inspector-row-runtime {
        grid-template-columns: 1fr;
    }

    .pivot-dag-tool-meta-id {
        grid-template-columns: 1fr;
    }

    .pivot-dag-tool-meta-id span {
        padding-top: 0;
    }
}

.pivot-dag-inspector-input textarea {
    min-height: 112px;
    height: auto;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    resize: vertical;
}

.pivot-dag-inspector-input textarea.is-invalid {
    border-color: #ef4444;
}

.pivot-dag-contract-panel {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 10px;
    border: 1px solid rgba(148, 163, 184, 0.25);
    border-radius: 8px;
    background: #f8fafc;
}

.pivot-dag-output-panel {
    display: flex;
    flex-direction: column;
    gap: 9px;
    padding: 11px;
    border: 1px solid rgba(14, 165, 164, 0.24);
    border-radius: 8px;
    background: #f5fffe;
}

.pivot-dag-output-panel-head,
.pivot-dag-output-contract {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.pivot-dag-output-panel-head > div,
.pivot-dag-output-contract > div {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
}

.pivot-dag-output-panel-head strong,
.pivot-dag-output-contract strong {
    color: #0f172a;
    font-size: 0.76rem;
}

.pivot-dag-output-panel-head span,
.pivot-dag-output-contract span {
    color: #64748b;
    font-size: 0.66rem;
}

.pivot-dag-output-current {
    flex: 0 0 auto;
    padding: 3px 7px;
    border-radius: 999px;
    background: #dff8f4;
    color: #047857 !important;
    font-size: 0.64rem !important;
    font-weight: 700;
}

.pivot-dag-output-modes {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 6px;
}

.pivot-dag-output-mode {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 3px;
    min-width: 0;
    min-height: 54px;
    padding: 8px;
    border: 1px solid rgba(148, 163, 184, 0.32);
    border-radius: 7px;
    background: #fff;
    color: #334155;
    text-align: left;
    cursor: pointer;
}

.pivot-dag-output-mode strong {
    font-size: 0.7rem;
    line-height: 1.2;
}

.pivot-dag-output-mode span {
    color: #64748b;
    font-size: 0.62rem;
    line-height: 1.2;
}

.pivot-dag-output-mode:hover,
.pivot-dag-output-mode.is-active {
    border-color: #0ea5a4;
    box-shadow: 0 0 0 2px rgba(14, 165, 164, 0.1);
}

.pivot-dag-output-mode.is-active {
    background: #ecfdf5;
    color: #065f46;
}

.pivot-dag-output-contract {
    padding-top: 8px;
    border-top: 1px solid rgba(148, 163, 184, 0.2);
}

.pivot-dag-output-contract .btn-secondary {
    min-height: 26px;
    padding: 3px 9px;
    font-size: 0.68rem;
}

.pivot-dag-output-presentation {
    padding-top: 8px;
    border-top: 1px solid rgba(148, 163, 184, 0.2);
}

.pivot-dag-output-presentation-modes {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 6px;
    margin-top: 7px;
}

.pivot-dag-output-presentation-note {
    margin-top: 6px;
    color: #64748b;
    font-size: 0.64rem;
    line-height: 1.35;
}

.pivot-dag-schema-builder-wrap {
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-width: 0;
}

.pivot-dag-schema-builder-head,
.pivot-dag-schema-preview-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.pivot-dag-schema-builder-head > span,
.pivot-dag-schema-preview-head > span {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.pivot-dag-schema-builder-head strong,
.pivot-dag-schema-preview-head strong {
    color: #0f172a;
    font-size: 0.76rem;
}

.pivot-dag-schema-builder-head em,
.pivot-dag-schema-preview-head span {
    color: #64748b;
    font-size: 0.66rem;
    font-style: normal;
}

.pivot-dag-schema-root-type,
.pivot-dag-schema-item-type {
    display: flex;
    align-items: center;
    gap: 8px;
    max-width: 260px;
}

.pivot-dag-schema-root-type span,
.pivot-dag-schema-item-type span {
    color: #475569;
    font-size: 0.68rem;
    white-space: nowrap;
}

.pivot-dag-schema-root-type select,
.pivot-dag-schema-item-type select {
    min-height: 30px;
}

.pivot-dag-schema-fields {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.pivot-dag-schema-field-block {
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.pivot-dag-schema-fields.is-nested {
    margin: 0 0 0 14px;
    padding-left: 9px;
    border-left: 2px solid rgba(14, 165, 164, 0.2);
}

.pivot-dag-schema-field {
    display: grid;
    grid-template-columns: minmax(110px, 1fr) 92px minmax(120px, 1.2fr) auto auto;
    align-items: center;
    gap: 6px;
    padding: 7px;
    border: 1px solid rgba(148, 163, 184, 0.25);
    border-radius: 7px;
    background: #f8fafc;
}

