/* ── 抽屉过渡动画（取代 display:none 切换）───── */
.agent-dag-node-drawer {
    transition: opacity 0.18s ease, transform 0.18s ease;
    opacity: 1;
    transform: translateX(0);
}

.agent-dag-node-drawer.hidden {
    display: none;
    opacity: 0;
    transform: translateX(16px);
}

/* ── when 条件面板 ───────────────────────────── */
.pivot-dag-when-panel {
    padding: 8px 10px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 7px;
    background: #fafafa;
}

.pivot-dag-when-panel.is-active {
    border-color: rgba(59, 130, 246, 0.4);
    background: rgba(59, 130, 246, 0.03);
}

.pivot-dag-when-head {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.pivot-dag-when-toggle {
    display: flex !important;
    align-items: center !important;
    gap: 5px !important;
    cursor: pointer;
}

.pivot-dag-when-toggle input[type="checkbox"] {
    width: 14px;
    height: 14px;
    cursor: pointer;
    accent-color: #3b82f6;
}

.pivot-dag-when-toggle strong {
    color: #1e293b;
    font-size: 0.77rem;
    font-weight: 800;
}

.pivot-dag-when-head > span {
    color: #64748b;
    font-size: 0.67rem;
}

.pivot-dag-when-body {
    display: grid;
    grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr);
    gap: 6px;
    margin-top: 8px;
}

.pivot-dag-when-body label {
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.pivot-dag-when-body label span {
    color: #64748b;
    font-size: 0.65rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.pivot-dag-when-body input,
.pivot-dag-when-body select {
    height: 28px;
    padding: 0 7px;
    border: 1px solid rgba(148, 163, 184, 0.4);
    border-radius: 5px;
    background: #fff;
    color: #0f172a;
    font-family: inherit;
    font-size: 0.74rem;
}

.pivot-dag-when-body input:focus,
.pivot-dag-when-body select:focus {
    border-color: #3b82f6;
    outline: none;
}

.pivot-dag-when-source { grid-column: 1; }
.pivot-dag-when-operator { grid-column: 2; }
.pivot-dag-when-value { grid-column: 1 / -1; }

.pivot-dag-when-hint {
    margin-top: 5px;
    color: #94a3b8;
    font-size: 0.64rem;
    line-height: 1.5;
}

.pivot-dag-when-hint code {
    padding: 0 3px;
    border-radius: 3px;
    background: rgba(15, 23, 42, 0.06);
    font-size: 0.6rem;
}

/* 深色模式 */
body.dark-mode .pivot-dag-when-panel,
.dark-mode .pivot-dag-when-panel {
    border-color: rgba(148, 163, 184, 0.22);
