.dark-mode .pivot-dag-when-toggle strong { color: #e2e8f0; }

body.dark-mode .pivot-dag-when-body input,
body.dark-mode .pivot-dag-when-body select,
.dark-mode .pivot-dag-when-body input,
.dark-mode .pivot-dag-when-body select {
    border-color: rgba(148, 163, 184, 0.28);
    background: #1e293b;
    color: #e2e8f0;
}


