}

.pivot-dag-query-filter-row .form-input {
    min-width: 0;
    width: 100%;
    height: 32px;
    min-height: 32px;
    margin: 0;
    padding: 6px 8px;
    border-radius: 6px;
    background: #fff;
    font-size: 0.72rem;
}

.pivot-dag-query-filter-row .btn-danger-outline {
    height: 30px;
    padding: 0 8px;
    border-radius: 6px;
    font-size: 0.68rem;
    white-space: nowrap;
}

.pivot-dag-query-filter-type {
    grid-column: 3 / 5;
    min-width: 0;
    color: #047857;
    font-size: 0.62rem;
    line-height: 1.35;
    overflow-wrap: anywhere;
}

.pivot-dag-query-preview {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 6px;
    padding-top: 10px;
    border-top: 1px solid rgba(148, 163, 184, 0.22);
}

.pivot-dag-query-preview pre {
    min-height: 86px;
    max-height: 220px;
    margin: 0;
    padding: 10px;
    overflow: auto;
    border: 1px solid rgba(15, 23, 42, 0.1);
    border-radius: 7px;
    background: #0f172a;
    color: #dbeafe;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-size: 0.7rem;
    line-height: 1.5;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
}

.pivot-dag-query-status {
    min-width: 0;
    color: var(--text-muted);
    font-size: 0.68rem;
    line-height: 1.35;
    text-align: right;
}

.pivot-dag-query-status.success {
    color: #047857;
}

.pivot-dag-query-status.warn {
    color: #b45309;
}

.pivot-dag-query-status.error {
    color: #b91c1c;
}

.pivot-dag-query-sql-field textarea {
    min-height: 260px;
    resize: vertical;
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    font-size: 0.78rem;
    line-height: 1.55;
}

.pivot-dag-query-sql-field small {
    margin-top: 1px;
}

.pivot-dag-query-empty {
    color: var(--text-muted);
    font-size: 0.7rem;
    line-height: 1.4;
}

@media (max-width: 980px) {
    .pivot-dag-query-source,
    .pivot-dag-query-options {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .pivot-dag-query-source-actions {
        grid-column: 1 / -1;
    }

    .pivot-dag-query-columns {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

@media (max-width: 640px) {
    .pivot-dag-query-builder-head,
    .pivot-dag-query-section-head,
    .pivot-dag-query-preview-head {
        flex-direction: column;
        align-items: stretch;
    }

    .pivot-dag-query-mode {
        align-self: flex-start;
    }

    .pivot-dag-query-filter-actions {
        justify-content: flex-start;
    }

    .pivot-dag-query-source,
    .pivot-dag-query-options,
    .pivot-dag-query-filter-row {
        grid-template-columns: 1fr;
    }

    .pivot-dag-query-source-actions {
        grid-column: auto;
    }

    .pivot-dag-query-columns {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .pivot-dag-query-status {
        text-align: left;
    }

    .pivot-dag-query-filter-type {
        grid-column: 1;
    }
}


/* === styles/workspaces/agent/agent-dag-minimap.css === */
/* 拆自 agent-dag-editor.css。 */
