/* === styles/workspaces/personal.css === */
/* 个人工作台：沿用系统绿色/主色主题，提供现代清爽的工作流导航、Hero、KPI 统计与卡片排版。 */
.personal-workspace-view {
    background: var(--bg-side);
}

.personal-workbench-shell {
    display: flex;
    flex: 1;
    min-width: 0;
    min-height: 0;
    background: var(--bg-side);
    color: var(--text-main);
}

/* 左侧精简导轨 */
.personal-rail {
    width: 80px;
    flex: 0 0 80px;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 16px 8px 16px;
    border-right: 1px solid var(--border);
    background: var(--surface);
}

.personal-rail-brand {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    user-select: none;
}

.personal-rail-brand img {
    width: 100%;
    height: 100%;
    object-fit: contain;
    display: block;
    background: transparent;
    border: none;
    box-shadow: none;
    filter: none;
}

.personal-rail-nav {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 28px;
}

.personal-rail-bottom {
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    margin-top: auto;
}

.personal-rail-item {
    width: 100%;
    min-height: 56px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 5px;
    padding: 8px 2px;
    border: 1.5px solid transparent;
    border-radius: 12px;
