    border-radius: 50%;
    border: none;
    background: var(--primary) !important;
    color: #ffffff !important;
    font-size: 0.85rem;
    font-weight: 700;
    cursor: pointer;
    box-shadow: 0 2px 6px rgba(16, 163, 127, 0.25);
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    outline: none;
}

.personal-rail-avatar:hover,
.personal-top-avatar:hover {
    opacity: 1 !important;
    background: var(--primary-hover, #0d8c6d) !important;
    color: #ffffff !important;
    transform: scale(1.06);
    box-shadow: 0 4px 12px rgba(16, 163, 127, 0.35);
}

.personal-rail-avatar:active,
.personal-top-avatar:active {
    transform: scale(0.96);
}

.personal-rail-avatar span,
.personal-top-avatar span {
    color: #ffffff !important;
    line-height: 1;
    font-weight: 700;
    user-select: none;
}


/* 主内容容器 */
.personal-workbench-content {
    display: flex;
    flex: 1;
    min-width: 0;
    min-height: 0;
    flex-direction: column;
}

/* 顶部导航条 */
.personal-workbench-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    min-height: 66px;
    padding: 0 28px;
    border-bottom: 1px solid var(--border);
    background: var(--surface);
}

.personal-workbench-heading {
    display: flex;
    align-items: baseline;
    min-width: 0;
    gap: 12px;
}

.personal-workbench-heading h1 {
    margin: 0;
    color: var(--text-main);
    font-size: 1.35rem;
    font-weight: 700;
    line-height: 1.2;
    white-space: nowrap;
}

.personal-workbench-heading span {
    color: var(--text-muted);
    font-size: 0.82rem;
    font-weight: 400;
    white-space: nowrap;
}

.personal-workbench-header-actions {
    display: flex;
    align-items: center;
    gap: 10px;
}

.personal-top-search {
    width: min(320px, 32vw);
    min-height: 36px;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 14px;
    border: 1px solid var(--border);
    border-radius: 9999px;
    background: var(--surface);
    color: var(--text-muted);
    font-size: 0.76rem;
    white-space: nowrap;
    cursor: pointer;
    transition: all 0.2s ease;
}

.personal-top-search:hover {
    border-color: var(--primary);
    color: var(--text-main);
}

.personal-search-icon {
    flex-shrink: 0;
    color: var(--text-muted);
}

.personal-top-search kbd {
    margin-left: auto;
    padding: 1px 6px;
    border: 1px solid var(--border);
    border-radius: 4px;
    background: var(--bg-side);
    color: var(--text-muted);
    font-size: 0.68rem;
    font-weight: 500;
}

.personal-top-icon {
    width: 36px;
    min-width: 36px;
