}

/* ==========================================================================
   6. Quality Report Area (Tab 2)
   ========================================================================== */
.data-cleaning-quality-bar {
    justify-content: space-between;
    margin-bottom: 6px;
    gap: 8px;
}

.data-cleaning-quality-title {
    gap: 6px;
    color: var(--text-main);
    font-size: 0.80rem;
}

.data-cleaning-quality-title svg {
    color: var(--primary, #0f766e);
    width: 15px;
    height: 15px;
}

.data-cleaning-health-badge {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 0 8px;
    height: 22px;
    border-radius: 999px;
    font-size: 0.68rem;
    font-weight: 600;
}

.data-cleaning-health-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: currentColor;
}

.data-cleaning-health-badge.health-good {
    background: rgba(16, 185, 129, 0.12);
    color: #059669;
    border: 1px solid rgba(16, 185, 129, 0.3);
}

.data-cleaning-health-badge.health-fair {
    background: rgba(245, 158, 11, 0.12);
    color: #d97706;
    border: 1px solid rgba(245, 158, 11, 0.3);
}

.data-cleaning-health-badge.health-warning {
    background: rgba(239, 68, 68, 0.12);
    color: #dc2626;
    border: 1px solid rgba(239, 68, 68, 0.3);
}

.data-cleaning-kpis {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 8px;
    margin-bottom: 8px;
}

.data-cleaning-kpi-card {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 10px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 6px;
    background: var(--bg-card, #fff);
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.02);
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.data-cleaning-kpi-card:hover {
    transform: translateY(-1px);
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
}

.data-cleaning-kpi-icon {
    display: grid;
    place-items: center;
    width: 28px;
    height: 28px;
    border-radius: 6px;
    flex-shrink: 0;
}

.data-cleaning-kpi-icon svg {
    width: 14px;
    height: 14px;
}

.kpi-rows .data-cleaning-kpi-icon {
    background: rgba(59, 130, 246, 0.12);
    color: #2563eb;
}

.kpi-columns .data-cleaning-kpi-icon {
    background: rgba(20, 184, 166, 0.12);
    color: #0d9488;
}

.kpi-missing .data-cleaning-kpi-icon {
    background: rgba(245, 158, 11, 0.12);
    color: #d97706;
}

.kpi-duplicates .data-cleaning-kpi-icon {
    background: rgba(139, 92, 246, 0.12);
    color: #7c3aed;
}

.data-cleaning-kpi-meta span {
    display: block;
    color: var(--text-muted);
    font-size: 0.66rem;
    font-weight: 500;
    line-height: 1.1;
}

.data-cleaning-kpi-meta strong {
    display: block;
    margin-top: 1px;
    color: var(--text-main);
    font-size: 0.90rem;
    font-weight: 700;
    line-height: 1.2;
}

/* Field Quality Table */
.data-cleaning-field-quality-wrap,
.data-cleaning-preview-table-wrap {
    overflow: auto;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 6px;
    background: var(--bg-card, #fff);
    max-height: calc(100vh - 280px);
}

.data-cleaning-field-quality {
    min-width: 720px;
    margin: 0;
    width: 100%;
    border-collapse: collapse;
}

.data-cleaning-field-quality th {
    padding: 5px 8px;
    height: 30px;
    min-height: 30px;
    background: rgba(248, 250, 252, 0.95);
    font-size: 0.68rem;
    font-weight: 700;
    color: #475569;
    white-space: nowrap;
    border-bottom: 1px solid rgba(148, 163, 184, 0.18);
    position: sticky;
    top: 0;
    z-index: 2;
    box-sizing: border-box;
}

.data-cleaning-field-quality td {
    padding: 4px 8px;
    height: 28px;
    font-size: 0.72rem;
    white-space: nowrap;
    border-bottom: 1px solid rgba(148, 163, 184, 0.08);
    box-sizing: border-box;
}

.data-cleaning-field-quality tbody tr:hover {
    background: #f8fafc;
}

.data-cleaning-fill-bar-wrap {
    display: flex;
    align-items: center;
    gap: 6px;
    min-width: 110px;
}

.data-cleaning-fill-bar {
    flex: 1;
    height: 4px;
    border-radius: 999px;
    background: rgba(148, 163, 184, 0.2);
    overflow: hidden;
}

.data-cleaning-fill-bar span {
    display: block;
    height: 100%;
    border-radius: 999px;
}

.data-cleaning-fill-bar.rate-high span {
    background: linear-gradient(90deg, #10b981, #059669);
}

.data-cleaning-fill-bar.rate-med span {
    background: linear-gradient(90deg, #f59e0b, #d97706);
}

.data-cleaning-fill-bar.rate-low span {
    background: linear-gradient(90deg, #ef4444, #dc2626);
}

.data-cleaning-fill-text {
    font-size: 0.66rem;
    font-weight: 700;
    min-width: 30px;
}

.data-cleaning-sample-cell {
    max-width: 220px;
    overflow: hidden;
    text-overflow: ellipsis;
    color: var(--text-muted);
}

.data-cleaning-type {
    display: inline-flex;
    padding: 1px 6px;
    border-radius: 3px;
    background: rgba(20, 184, 166, 0.11);
    color: #0f766e;
    font-size: 0.64rem;
    font-weight: 700;
}

.data-cleaning-type.type-number,
.data-cleaning-type.type-integer,
.data-cleaning-type.type-float {
    background: rgba(59, 130, 246, 0.12);
    color: #2563eb;
}

.data-cleaning-type.type-date,
.data-cleaning-type.type-timestamp {
    background: rgba(139, 92, 246, 0.12);
    color: #7c3aed;
}

/* ==========================================================================
