    margin-top: 8px;
}

.data-cleaning-recommendations,
.data-cleaning-rules-panel,
.data-cleaning-preview,
.data-cleaning-runs-panel {
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: var(--bg-card, #fff);
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.02);
}

.data-cleaning-recommendations,
.data-cleaning-rules-panel,
.data-cleaning-runs-panel {
    padding: 8px 10px;
}

.data-cleaning-section-heading {
    justify-content: space-between;
    margin-bottom: 6px;
    gap: 6px;
}

.data-cleaning-section-title-wrap {
    display: flex;
    align-items: center;
    gap: 5px;
}

.data-cleaning-section-title-wrap svg {
    color: var(--primary, #0f766e);
