}

.data-cleaning-rule-actions .btn-secondary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 24px;
    height: 24px;
    padding: 0 5px;
    font-size: 0.68rem;
    border-radius: 4px;
}

.data-cleaning-rule-actions .btn-secondary svg {
    width: 10px;
    height: 10px;
}

.data-cleaning-rule-delete {
    color: var(--danger, #dc2626);
    gap: 2px;
}

.data-cleaning-rule-delete:hover {
    background: rgba(239, 68, 68, 0.1);
    border-color: rgba(239, 68, 68, 0.3);
}

.data-cleaning-dedup-fields {
    grid-column: 1 / -1;
    display: grid;
    gap: 3px;
    padding: 4px 6px;
    background: rgba(148, 163, 184, 0.08);
