/* ==========================================================================
   13. Responsive Adaptations
   ========================================================================== */
@media (max-width: 980px) {
    .data-cleaning-header,
    .data-cleaning-preview-head {
        align-items: flex-start;
        flex-direction: column;
    }
    .data-cleaning-header-actions,
    .data-cleaning-preview-kpis {
        justify-content: flex-start;
        width: 100%;
    }
    .data-cleaning-tabs-nav {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .data-cleaning-layout {
        grid-template-columns: 1fr;
    }
    .data-cleaning-kpis {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .data-cleaning-rule-fields {
        grid-template-columns: repeat(2, minmax(110px, 1fr));
    }
}

@media (max-width: 640px) {
    .data-cleaning-tabs-nav {
        grid-template-columns: 1fr;
    }
    .data-cleaning-pane-bottom-cta {
        flex-direction: column;
        align-items: stretch;
    }
    .data-cleaning-pane-cta-desc {
        margin-right: 0;
        margin-bottom: 6px;
        text-align: center;
    }
    .data-cleaning-kpis,
    .data-cleaning-rule-fields {
        grid-template-columns: 1fr;
    }
    .data-cleaning-rule {
        grid-template-columns: 20px minmax(0, 1fr);
    }
    .data-cleaning-rule-actions {
        grid-column: 2;
    }
    .data-cleaning-actions {
        justify-content: stretch;
    }
    .data-cleaning-name-label {
        width: 100%;
    }
}


