}

.data-analysis-ai-step code {
    display: block;
    padding: 4px 6px;
    border-radius: 4px;
    background: rgba(15, 23, 42, 0.05);
    color: #334155;
    font-size: 0.72rem;
    word-break: break-all;
}

.data-analysis-ai-step em {
