    font-size: 0.7rem;
    font-style: normal;
}

.data-analysis-ai-step.is-error em {
    color: #b91c1c;
}

.data-analysis-empty {
    display: grid;
    place-items: center;
    min-height: 90px;
    color: var(--text-muted);
    font-size: 0.78rem;
}

@media (max-width: 1120px) {
    .data-analysis-panel {
        grid-template-columns: 220px minmax(0, 1fr);
