/* === styles/workspaces/apps/apps-grid.css === */
.apps-home-view .apps-panel,
.apps-panel {
    flex: 0 0 auto;
    height: auto !important;
    min-height: 0 !important;
    width: 100%;
    max-width: 1160px;
    margin: 0 auto !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important;
    padding: 10px 4px 24px !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: flex-start !important;
    align-items: stretch !important;
    gap: 0;
}

/* 应用网格布局：标准 3 列等宽，靠左自然对齐 */
.apps-home-view .apps-grid,
.apps-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 24px;
    width: 100%;
    padding: 8px 4px 16px;
    margin: 0;
    overflow: visible;
}

.app-card {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    min-height: 204px;
    padding: 24px 26px 20px;
    border: 1px solid rgba(226, 232, 240, 0.95);
    border-radius: 16px;
    background: #ffffff;
    color: var(--text-main);
    text-align: left;
    cursor: pointer;
    box-shadow: 0 4px 16px -2px rgba(15, 23, 42, 0.04), 0 1px 2px rgba(15, 23, 42, 0.02);
    transition: border-color 0.22s ease, box-shadow 0.22s ease, transform 0.22s cubic-bezier(0.16, 1, 0.3, 1);
    position: relative;
    outline: none;
}

.app-card:disabled {
    cursor: not-allowed;
    opacity: 0.62;
    transform: none;
}

.app-card:hover,
.app-card:focus,
.app-card:focus-visible {
    border-color: rgba(16, 185, 129, 0.48);
    background: #ffffff;
    box-shadow: 0 16px 32px -4px rgba(15, 23, 42, 0.08), 0 4px 12px -2px rgba(16, 185, 129, 0.08);
    transform: translateY(-4px);
    z-index: 2;
}

.app-card-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 14px;
    margin-bottom: 14px;
}

.app-card-icon {
    width: 48px;
    height: 48px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    border-radius: 12px;
    border: 1px solid rgba(16, 185, 129, 0.2);
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.12) 0%, rgba(16, 185, 129, 0.03) 100%);
    color: var(--primary, #059669);
    transition: transform 0.22s ease, box-shadow 0.22s ease;
}

.app-card-icon svg {
    width: 22px;
    height: 22px;
}

/* 场景专属配色 */
.app-card-icon-official-writing {
    background: linear-gradient(135deg, rgba(16, 185, 129, 0.15) 0%, rgba(16, 185, 129, 0.04) 100%);
    border-color: rgba(16, 185, 129, 0.25);
    color: #059669;
}

.app-card-icon-data-analysis {
    background: linear-gradient(135deg, rgba(37, 99, 235, 0.14) 0%, rgba(37, 99, 235, 0.04) 100%);
    border-color: rgba(37, 99, 235, 0.25);
    color: #2563eb;
}

.app-card-icon-regulations {
    background: linear-gradient(135deg, rgba(139, 92, 246, 0.14) 0%, rgba(139, 92, 246, 0.04) 100%);
    border-color: rgba(139, 92, 246, 0.25);
    color: #7c3aed;
}

.app-card-icon-ocr {
    background: linear-gradient(135deg, rgba(14, 165, 233, 0.14) 0%, rgba(14, 165, 233, 0.04) 100%);
    border-color: rgba(14, 165, 233, 0.25);
    color: #0284c7;
}

.app-card-icon-pdf-tools {
    background: linear-gradient(135deg, rgba(245, 158, 11, 0.14) 0%, rgba(245, 158, 11, 0.04) 100%);
    border-color: rgba(245, 158, 11, 0.25);
    color: #d97706;
}

.app-card:hover .app-card-icon,
.app-card:focus-visible .app-card-icon {
    transform: scale(1.08);
    box-shadow: 0 4px 12px rgba(15, 23, 42, 0.08);
}

.app-card-badges {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
    justify-content: flex-end;
}

.app-card-category {
    font-size: 0.72rem;
    font-weight: 600;
    color: #475569;
    background: #f1f5f9;
    padding: 3px 9px;
    border-radius: 6px;
}

.app-card-status {
    font-style: normal;
    font-size: 0.7rem;
    font-weight: 600;
    color: #059669;
    background: rgba(16, 185, 129, 0.1);
    border: 1px solid rgba(16, 185, 129, 0.22);
    border-radius: 6px;
    padding: 2px 8px;
}

.app-card-main {
    display: flex;
    flex-direction: column;
    gap: 8px;
    flex: 1 1 auto;
}

.app-card-title {
    font-size: 1.15rem;
    font-weight: 700;
    color: #0f172a;
    letter-spacing: -0.01em;
}

.app-card-desc {
    font-size: 0.84rem;
    line-height: 1.6;
    color: #64748b;
    margin: 0;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.app-card-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin-top: 10px;
}

.app-card-tag {
    font-size: 0.72rem;
    color: #475569;
    background: #f8fafc;
    padding: 3px 8px;
    border-radius: 6px;
    border: 1px solid rgba(226, 232, 240, 0.9);
    font-weight: 500;
}

.app-card-footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding-top: 14px;
    margin-top: 14px;
    border-top: 1px solid rgba(241, 245, 249, 0.95);
}

.app-card-action {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.78rem;
    font-weight: 600;
    color: #94a3b8;
    transition: all 0.2s ease;
}

.app-card:hover .app-card-action {
    color: #059669;
    transform: translateX(3px);
}

.apps-empty {
    grid-column: 1 / -1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 220px;
    padding: 40px 20px;
    border: 1px dashed rgba(203, 213, 225, 0.8);
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.7);
    color: #64748b;
    font-size: 0.88rem;
}

/* 暗黑模式适配 */
body.dark-mode .apps-home-view,
.dark-mode .apps-home-view {
    background: #0f172a;
}

body.dark-mode .app-card,
.dark-mode .app-card {
    background: #1e293b;
    border-color: rgba(148, 163, 184, 0.18);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.24);
}

body.dark-mode .app-card:hover,
body.dark-mode .app-card:focus,
body.dark-mode .app-card:focus-visible,
.dark-mode .app-card:hover,
.dark-mode .app-card:focus,
.dark-mode .app-card:focus-visible {
    border-color: rgba(16, 185, 129, 0.5);
    box-shadow: 0 14px 28px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(16, 185, 129, 0.22);
}

body.dark-mode .app-card-title,
.dark-mode .app-card-title {
    color: #f8fafc;
}

body.dark-mode .app-card-desc,
.dark-mode .app-card-desc {
    color: #94a3b8;
}

body.dark-mode .app-card-category,
.dark-mode .app-card-category {
    background: rgba(51, 65, 85, 0.7);
    color: #cbd5e1;
}

body.dark-mode .app-card-tag,
.dark-mode .app-card-tag {
    background: rgba(51, 65, 85, 0.6);
    color: #cbd5e1;
    border-color: rgba(148, 163, 184, 0.2);
}

body.dark-mode .app-card-footer,
.dark-mode .app-card-footer {
    border-top-color: rgba(148, 163, 184, 0.12);
}

body.dark-mode .app-card-action,
.dark-mode .app-card-action {
    color: #64748b;
}

body.dark-mode .app-card:hover .app-card-action,
.dark-mode .app-card:hover .app-card-action {
    color: #34d399;
}

body.dark-mode .apps-empty,
.dark-mode .apps-empty {
    background: rgba(30, 41, 59, 0.6);
    border-color: rgba(148, 163, 184, 0.2);
    color: #94a3b8;
}

/* 响应式断点适配 */
@media (max-width: 1120px) {
    .apps-home-view .apps-grid,
    .apps-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 20px;
    }
}

@media (max-width: 720px) {
    .apps-home-view {
        padding: 24px 16px 40px;
    }

    .apps-home-view .apps-grid,
    .apps-grid {
        grid-template-columns: 1fr;
        gap: 16px;
    }

    .app-card {
        padding: 20px;
        min-height: 180px;
    }
}


/* === styles/workspaces/apps/official-writing.css === */
.official-writing-panel[data-official-writing-screen="library"] .official-writing-detail-header,
.official-writing-panel[data-official-writing-screen="library"] .official-writing-toolbar,
.official-writing-panel[data-official-writing-screen="library"] .official-writing-workbench,
.official-writing-panel[data-official-writing-screen="library"] .official-writing-diff-modal {
    display: none;
}

.official-writing-panel[data-official-writing-screen="editor"] .official-writing-library-home {
    display: none;
}

.official-writing-detail-header {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 8px;
    background: #fff;
    box-shadow: 0 6px 16px rgba(15, 23, 42, 0.035);
}

.official-writing-detail-title {
    min-width: 0;
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.official-writing-detail-title strong {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: #0f172a;
    font-size: 0.94rem;
}

.official-writing-detail-title span {
    color: #64748b;
    font-size: 0.74rem;
    font-weight: 700;
}

.official-writing-detail-actions {
    display: flex;
    gap: 8px;
    flex: 0 0 auto;
}

.official-writing-detail-header .btn-secondary {
    height: 32px;
    padding: 0 10px;
    border-radius: 8px;
}

.official-writing-left-rail .official-writing-doc-library {
    display: none;
}

.official-writing-panel {
    flex: 1;
    width: 100%;
    height: 100%;
    min-height: 0;
    min-width: 0;
    gap: 8px;
    padding: 0;
    border: 0;
    background: transparent;
    box-shadow: none;
    position: relative;
}

.official-writing-toolbar {
    flex: 0 0 auto;
    display: grid;
    grid-template-columns: 112px 152px 132px minmax(280px, 1fr) auto;
    align-items: end;
    gap: 8px;
    padding: 8px 10px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 8px;
    background: #fff;
    box-shadow: 0 6px 16px rgba(15, 23, 42, 0.035);
}

.official-writing-field {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.official-writing-field label {
    color: #475569;
    font-size: 0.72rem;
    font-weight: 800;
}

.official-writing-toolbar .form-input {
    height: 32px;
    min-width: 0;
    margin-bottom: 0;
    padding: 0 10px;
    border-radius: 8px;
    font-size: 0.8rem;
}

.official-writing-view-switch {
    display: inline-grid;
    grid-template-columns: repeat(2, 1fr);
    align-self: end;
    justify-self: end;
    width: 100%;
    height: 32px;
    padding: 2px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 8px;
    background: #f8fafc;
}

.official-writing-mode-toggle {
    min-width: 0;
    border: 0;
    border-radius: 6px;
    background: transparent;
    color: #64748b;
    font-size: 0.74rem;
    font-weight: 800;
    cursor: pointer;
}

.official-writing-mode-toggle.active {
    background: #fff;
    color: var(--primary);
    box-shadow: 0 1px 5px rgba(15, 23, 42, 0.08);
}

.official-writing-command-row {
    grid-column: 5 / 6;
    grid-row: 1;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    flex-wrap: wrap;
    min-width: 0;
    padding-top: 0;
    border-top: 0;
    overflow: visible;
}

.official-writing-model-selector {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    min-width: 0;
    color: #64748b;
    font-size: 0.72rem;
    font-weight: 800;
    white-space: nowrap;
}

.official-writing-model-selector select {
    width: 164px;
    height: 32px;
    margin: 0;
    padding: 0 8px;
    font-size: 0.76rem;
}

.official-writing-command-group {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    flex: 0 0 auto;
    padding-right: 8px;
    border-right: 1px solid rgba(148, 163, 184, 0.16);
}

.official-writing-command-group:last-of-type {
    border-right: 0;
    padding-right: 0;
}

.official-writing-command-group span {
    color: #64748b;
    font-size: 0.68rem;
    font-weight: 900;
    white-space: nowrap;
}

.official-writing-command-group .btn-primary,
.official-writing-command-group .btn-secondary,
.official-writing-command-action {
    height: 32px;
    padding: 0 9px;
    border-radius: 8px;
    font-size: 0.74rem;
}

.official-writing-ai-command-group .btn-secondary {
    min-width: 48px;
}

.official-writing-ai-indicator {
    flex: 0 0 auto;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: #2563eb;
    font-size: 0.72rem;
    font-weight: 800;
    white-space: nowrap;
}

.official-writing-ai-indicator.hidden {
    display: none;
}

.official-writing-ai-indicator::before {
    content: "";
    width: 12px;
    height: 12px;
    border-radius: 50%;
    border: 2px solid rgba(37, 99, 235, 0.3);
    border-top-color: #2563eb;
    animation: official-writing-spin 0.8s linear infinite;
}

@keyframes official-writing-spin {
    to { transform: rotate(360deg); }
}

.official-writing-command-action:disabled,
.official-writing-command-group button:disabled,
.official-writing-selection-toolbar button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* 键盘可达性：为公文写作工作台内的可聚焦控件提供清晰的焦点环。 */
.official-writing-panel button:focus-visible,
.official-writing-panel select:focus-visible,
.official-writing-panel input:focus-visible,
.official-writing-panel textarea:focus-visible,
.official-writing-drawer-tab:focus-visible {
    outline: 2px solid #2563eb;
    outline-offset: 1px;
}

.official-writing-command-action {
    flex: 0 0 auto;
    white-space: nowrap;
}

.official-writing-command-menu {
    position: relative;
    flex: 0 0 auto;
}

.official-writing-command-menu > summary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    list-style: none;
    cursor: pointer;
}

.official-writing-command-menu > summary::-webkit-details-marker {
    display: none;
}

.official-writing-command-menu-panel {
    position: absolute;
    top: calc(100% + 6px);
    right: 0;
    z-index: 20;
    display: grid;
    grid-template-columns: minmax(120px, 1fr);
    gap: 6px;
    width: 176px;
    padding: 8px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 8px;
    background: #fff;
    box-shadow: 0 14px 32px rgba(15, 23, 42, 0.14);
}

.official-writing-command-menu-item {
    justify-content: center;
    min-height: 32px;
    padding: 0 8px;
    font-size: 0.74rem;
}

.official-writing-command-group .btn-secondary.active {
    border-color: rgba(16, 185, 129, 0.34);
    background: rgba(16, 185, 129, 0.08);
    color: var(--primary);
}

.official-writing-layout-group .official-writing-command-action {
    min-width: 64px;
}

.official-writing-layout-group .official-writing-command-action:not(.active) {
    border-style: dashed;
    background: #fff;
    color: #94a3b8;
}

.official-writing-command-group button span {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 16px;
    height: 16px;
    margin-left: 4px;
    padding: 0 4px;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.08);
    color: #475569;
    font-size: 0.64rem;
    font-weight: 800;
}

.official-writing-command-group .btn-secondary.active span {
    background: rgba(16, 185, 129, 0.16);
    color: var(--primary);
}

.official-writing-workbench {
    flex: 1;
    min-height: 0;
    display: grid;
    grid-template-columns: 200px minmax(0, 1fr);
    gap: 8px;
}

.official-writing-workbench.is-left-rail-hidden {
    grid-template-columns: minmax(0, 1fr);
}

.official-writing-workbench.is-left-rail-hidden .official-writing-left-rail {
    display: none;
}

.official-writing-left-rail {
    min-width: 0;
    min-height: 0;
    display: flex;
    flex-direction: column;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 8px;
    background: #fff;
    overflow: visible;
}

.official-writing-rail-head {
    min-height: 40px;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 8px;
    padding: 7px 8px 7px 10px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
    background: #f8fafc;
}

.official-writing-rail-head strong {
    min-width: 0;
    color: var(--text-main);
    font-size: 0.82rem;
}

.official-writing-material-tabs {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 3px;
    padding: 7px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.12);
    background: #fff;
}

.official-writing-material-tab {
    height: 28px;
    min-width: 0;
    border: 1px solid transparent;
    border-radius: 7px;
    background: #f8fafc;
    color: #64748b;
    font-size: 0.7rem;
    font-weight: 800;
    cursor: pointer;
}

.official-writing-material-tab.active {
    border-color: rgba(16, 185, 129, 0.26);
    background: rgba(16, 185, 129, 0.08);
    color: var(--primary);
}

.official-writing-rail-body {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 8px;
}

.official-writing-material-panel {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.official-writing-material-panel.hidden {
    display: none;
}

.official-writing-material-intro {
    display: grid;
    gap: 6px;
    padding: 12px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: #fff;
}

.official-writing-material-intro strong {
    color: var(--text-main);
    font-size: 0.86rem;
    font-weight: 800;
}

.official-writing-material-intro p {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.76rem;
    line-height: 1.55;
}

.official-writing-material-summary {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
}

.official-writing-material-summary span {
    min-height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 7px 9px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: #fff;
    color: #475569;
    font-size: 0.74rem;
    font-weight: 800;
}

.official-writing-material-summary b {
    color: var(--primary);
    font-size: 0.82rem;
}

.official-writing-material-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
}

.official-writing-material-actions .official-writing-material-action {
    text-align: center;
}

.official-writing-material-editor-card {
    display: grid;
    gap: 9px;
    padding: 10px;
    border: 1px solid rgba(16, 185, 129, 0.2);
    border-radius: 8px;
    background: #fff;
}

.official-writing-material-editor-card.hidden {
    display: none;
}

.official-writing-material-editor-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.official-writing-material-editor-head strong {
    color: var(--text-main);
    font-size: 0.8rem;
    font-weight: 800;
