.official-writing-drawer-head h4 {
    margin: 0;
    color: var(--text-main);
    font-size: 0.86rem;
}

.official-writing-drawer-head span {
    display: block;
    margin-top: 2px;
    color: var(--text-muted);
    font-size: 0.7rem;
    line-height: 1.35;
}

.official-writing-drawer-tabs {
    display: flex;
    flex-wrap: nowrap;
    align-items: center;
    gap: 5px;
    padding: 6px 8px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: thin;
}

.official-writing-drawer-tab {
    flex: 0 0 auto;
    min-width: max-content;
    height: 26px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 0 8px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 7px;
    background: #fff;
    color: #64748b;
    font-size: 0.7rem;
    font-weight: 800;
    line-height: 1;
    white-space: nowrap;
    cursor: pointer;
}

.official-writing-drawer-tab.active {
    border-color: rgba(16, 185, 129, 0.32);
    background: rgba(16, 185, 129, 0.08);
    color: var(--primary);
}

.official-writing-drawer-tab span {
    min-width: 16px;
    height: 16px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0 4px;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.08);
    color: #475569;
    font-size: 0.64rem;
}

.official-writing-drawer-section {
    flex: 1;
    min-height: 0;
    display: flex;
}

.official-writing-drawer-section.hidden {
    display: none;
}

.official-writing-drawer-section .official-writing-subpanel {
    flex: 1;
    border: 0;
    border-radius: 0;
    box-shadow: none;
}

.official-writing-comment-form,
.official-writing-version-controls {
    display: grid;
    gap: 8px;
    padding: 10px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
    background: #fff;
}

.official-writing-comment-form {
    grid-template-columns: 92px minmax(0, 1fr);
}

.official-writing-comment-form .form-input,
.official-writing-version-controls .form-input {
    min-width: 0;
    height: 34px;
    margin-bottom: 0;
    padding: 0 11px;
    border-radius: 8px;
    font-size: 0.82rem;
}

.official-writing-comment-form textarea {
    grid-column: 1 / -1;
    height: 54px;
    min-height: 54px;
    padding-top: 8px;
    padding-bottom: 8px;
    resize: none;
}

.official-writing-comment-form .btn-primary {
    grid-column: 2;
    justify-self: end;
    min-width: 88px;
    height: 34px;
    padding: 0 11px;
    border-radius: 8px;
    font-size: 0.78rem;
}

.official-writing-version-controls {
    grid-template-columns: 1fr;
}

.official-writing-version-controls .btn-primary {
    min-width: 72px;
    height: 34px;
    justify-self: end;
    padding: 0 12px;
    border-radius: 8px;
    font-size: 0.78rem;
}

.official-writing-versions-panel {
    display: flex;
    flex-direction: column;
    min-height: 0;
}

.official-writing-version-history-head {
    min-height: 34px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    padding: 8px 10px 0;
    background: #fff;
}

.official-writing-version-history-head strong {
    color: var(--text-main);
    font-size: 0.78rem;
}

.official-writing-version-history-head span {
    color: var(--text-muted);
    font-size: 0.67rem;
    font-weight: 700;
}

.official-writing-comments-list,
.official-writing-version-list,
.official-writing-diff-result,
.official-writing-compliance-list,
.official-writing-reference-list,
.official-writing-suggestion-list {
    min-height: 0;
    overflow: auto;
}

.official-writing-suggestion-list {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 10px;
}

.official-writing-suggestion-item {
    display: grid;
    gap: 7px;
    padding: 9px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: #f8fafc;
}

.official-writing-suggestion-item.is-accepted {
    opacity: 0.62;
    border-color: rgba(16, 185, 129, 0.24);
}

.official-writing-suggestion-item.is-rejected {
    opacity: 0.48;
}

.official-writing-suggestion-item > div:first-child {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.official-writing-suggestion-meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    color: #64748b;
    font-size: 0.66rem;
    font-weight: 700;
}

.official-writing-suggestion-status {
    display: inline-flex;
    align-items: center;
    height: 18px;
    padding: 0 6px;
    border-radius: 999px;
    background: rgba(148, 163, 184, 0.12);
    color: #475569;
}

.official-writing-suggestion-status.is-pending {
    background: rgba(245, 158, 11, 0.08);
    color: #92400e;
}

.official-writing-suggestion-status.is-accepted {
    background: rgba(16, 185, 129, 0.08);
    color: var(--primary);
}

.official-writing-suggestion-status.is-rejected {
    background: rgba(148, 163, 184, 0.12);
    color: #475569;
}

/* 流式生成中：徽章脉冲提示文本正在逐字写入。 */
.official-writing-suggestion-status.is-streaming {
    background: rgba(59, 130, 246, 0.1);
    color: #1d4ed8;
    animation: official-writing-streaming-pulse 1.2s ease-in-out infinite;
}

.official-writing-suggestion-item.is-streaming {
    border-color: rgba(59, 130, 246, 0.32);
}

@keyframes official-writing-streaming-pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.5; }
}

.official-writing-suggestion-item strong {
    color: var(--text-main);
    font-size: 0.78rem;
}

.official-writing-suggestion-item span {
    color: var(--primary);
    font-size: 0.68rem;
    font-weight: 900;
}

.official-writing-suggestion-original,
.official-writing-suggestion-text {
    margin: 0;
    padding: 7px 8px;
    border-radius: 7px;
    white-space: pre-wrap;
    word-break: break-word;
    font-size: 0.74rem;
    line-height: 1.45;
}

.official-writing-suggestion-original {
    background: rgba(239, 68, 68, 0.06);
    color: #7f1d1d;
}

.official-writing-suggestion-text {
    background: rgba(16, 185, 129, 0.08);
    color: #064e3b;
}

.official-writing-suggestion-actions {
    display: flex;
    gap: 5px;
    flex-wrap: wrap;
}

.official-writing-suggestion-actions .btn-primary,
.official-writing-suggestion-actions .btn-secondary {
    height: 28px;
    padding: 0 8px;
    border-radius: 7px;
    font-size: 0.68rem;
}

.official-writing-comments-list,
.official-writing-version-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 10px;
}

.official-writing-comments-list {
    flex: 1;
}

.official-writing-version-list {
    flex: 0 0 auto;
    max-height: 156px;
    padding-top: 8px;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.12);
    background: #fff;
}

.official-writing-comment {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 6px 8px;
    padding: 8px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: #f8fafc;
}

.official-writing-comment div {
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 6px;
}

.official-writing-comment strong {
    color: var(--primary);
    font-size: 0.74rem;
}

.official-writing-comment span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: #475569;
    font-size: 0.74rem;
    font-weight: 700;
}

.official-writing-comment p {
    grid-column: 1 / -1;
    margin: 0;
    color: var(--text-main);
    font-size: 0.78rem;
    line-height: 1.45;
}

.official-writing-comment .btn-secondary {
    grid-column: 2;
    grid-row: 1;
    height: 26px;
    padding: 0 8px;
    font-size: 0.7rem;
}

.official-writing-version-item {
    min-height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 8px 10px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: #fff;
    color: var(--text-main);
    cursor: pointer;
    transition: 0.16s ease;
}

.official-writing-version-item:hover {
    border-color: rgba(16, 185, 129, 0.34);
    background: rgba(16, 185, 129, 0.05);
}

.official-writing-version-item > span {
    width: 100%;
    min-width: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.official-writing-version-item strong {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 0.78rem;
}

.official-writing-version-item em {
    flex: 0 0 auto;
    padding: 2px 6px;
    border-radius: 999px;
    background: rgba(16, 185, 129, 0.08);
    color: var(--primary);
    font-size: 0.64rem;
    font-style: normal;
    font-weight: 800;
}

.official-writing-version-item small {
    width: 100%;
    color: var(--text-muted);
    font-size: 0.68rem;
    text-align: left;
}

.official-writing-check-item,
.official-writing-reference-item {
    display: grid;
    gap: 5px;
    margin: 10px;
    padding: 9px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: #f8fafc;
}

.official-writing-check-item strong {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    color: var(--text-main);
    font-size: 0.78rem;
}

.official-writing-check-item strong span {
    min-width: 24px;
    height: 20px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: rgba(239, 68, 68, 0.08);
    color: #b91c1c;
    font-size: 0.68rem;
}

.official-writing-check-item em {
    color: #475569;
    font-size: 0.72rem;
    font-style: normal;
    line-height: 1.45;
}

.official-writing-reference-item strong {
    color: var(--primary);
    font-size: 0.74rem;
}

.official-writing-diff-summary {
    min-height: 28px;
    padding: 6px 10px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
    background: #f8fafc;
    color: #475569;
    font-size: 0.74rem;
    font-weight: 700;
}

.official-writing-diff-result {
    flex: 1;
    display: flex;
    flex-direction: column;
    font-size: 0.74rem;
}

.official-writing-diff-row {
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr) minmax(0, 1fr);
    border-bottom: 1px solid rgba(148, 163, 184, 0.1);
}

.official-writing-diff-row span {
    padding: 7px 8px;
    color: var(--text-muted);
    background: #f8fafc;
    text-align: right;
    font-weight: 700;
}

.official-writing-diff-row p {
    min-width: 0;
    margin: 0;
    padding: 7px 9px;
    white-space: pre-wrap;
    word-break: break-word;
}

.official-writing-diff-row.is-changed p:nth-child(2) {
    background: rgba(239, 68, 68, 0.06);
}

.official-writing-diff-row.is-changed p:nth-child(3) {
    background: rgba(16, 185, 129, 0.07);
}

.official-writing-diff-row.is-removed p:nth-child(2) {
    background: rgba(239, 68, 68, 0.08);
}

.official-writing-diff-row.is-added p:nth-child(3) {
    background: rgba(16, 185, 129, 0.09);
}

.official-writing-empty-note {
    display: grid;
    place-items: center;
    min-height: 72px;
    color: var(--text-muted);
    font-size: 0.76rem;
    text-align: center;
}

@media (max-width: 1180px) {
    .official-writing-toolbar {
        grid-template-columns: repeat(4, minmax(118px, 1fr));
    }

    .official-writing-view-switch,
    .official-writing-requirements-field,
    .official-writing-command-row {
        grid-column: 1 / -1;
    }

    .official-writing-command-row {
        grid-row: auto;
        padding-top: 7px;
        border-top: 1px solid rgba(148, 163, 184, 0.12);
    }

    .official-writing-view-switch {
        max-width: 220px;
        justify-self: start;
    }

    .official-writing-command-row {
        flex-wrap: wrap;
        justify-content: flex-start;
        overflow-x: visible;
    }

    .official-writing-workbench {
        grid-template-columns: 180px minmax(0, 1fr);
    }

    .official-writing-shell {
        grid-template-columns: 1fr;
    }

    .official-writing-drawer {
        width: 100%;
        min-width: 0;
        max-height: 340px;
    }
}

@media (max-width: 980px) {
    .official-writing-toolbar,
    .official-writing-workbench,
    .official-writing-editor-grid,
    .official-writing-comment-form,
    .official-writing-version-controls {
        grid-template-columns: 1fr;
    }

    .official-writing-editor-toolbar {
        align-items: flex-start;
        flex-direction: column;
        gap: 7px;
    }

    .official-writing-editor-toolbar-actions {
        width: 100%;
        justify-content: flex-start;
        flex-wrap: wrap;
    }

    .official-writing-status-metrics {
        justify-content: flex-start;
        flex-wrap: wrap;
    }

    .official-writing-left-rail {
        width: auto;
        min-width: 0;
    }

    .official-writing-panel[data-writing-view-mode="document"] .official-writing-page-wrap {
        padding: 6px 0 20px;
    }

    .official-writing-panel[data-writing-view-mode="document"] .official-writing-draft-pane .official-writing-editor-stack {
        width: min(100%, 720px);
        min-height: 920px;
        padding: 56px 42px 52px;
        font-size: 15px;
    }

    .official-writing-panel[data-writing-view-mode="document"] .official-writing-draft-pane .official-writing-document-surface {
        min-height: calc(920px - 108px);
        font-size: 15px;
    }

    .official-writing-comment-form textarea,
    .official-writing-comment-form .btn-primary,
    .official-writing-view-switch,
    .official-writing-requirements-field,
    .official-writing-command-row {
        grid-column: auto;
        grid-row: auto;
    }

    .official-writing-command-row {
        justify-content: flex-start;
    }

}

@media (max-height: 760px) {
    .apps-workspace-modal .workspace-modal-body {
        padding: 8px;
    }

    .official-writing-toolbar {
        padding: 8px;
    }

    .official-writing-editor-grid {
        min-height: 250px;
    }

    .official-writing-panel[data-writing-view-mode="document"] .official-writing-draft-pane .official-writing-editor-stack {
        min-height: 860px;
        padding-top: 64px;
        padding-bottom: 60px;
    }

    .official-writing-panel[data-writing-view-mode="document"] .official-writing-draft-pane .official-writing-document-surface {
        min-height: calc(860px - 124px);
    }
}

/* === styles/workspaces/apps/official-writing-extras.css === */


/* ===== 多文档库 ===== */
.official-writing-doc-library {
    display: flex;
    flex-direction: column;
    border-bottom: 1px solid rgba(148, 163, 184, 0.2);
    max-height: 220px;
}

.official-writing-doc-library-head {
    justify-content: space-between;
}

.official-writing-doc-library-head .btn-secondary {
    height: 26px;
    padding: 0 8px;
    font-size: 0.7rem;
    border-radius: 6px;
}

.official-writing-doc-count {
    color: #64748b;
    font-size: 0.7rem;
    font-weight: 700;
}

.official-writing-doc-list {
    overflow-y: auto;
    padding: 6px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.official-writing-doc-item {
    display: flex;
    align-items: center;
    gap: 4px;
    border: 1px solid transparent;
    border-radius: 7px;
    padding: 2px;
}

.official-writing-doc-item.active {
    border-color: rgba(37, 99, 235, 0.35);
    background: rgba(37, 99, 235, 0.06);
}

.official-writing-doc-open {
    flex: 1 1 auto;
    min-width: 0;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 1px;
    padding: 5px 7px;
    border: 0;
    background: transparent;
    cursor: pointer;
    text-align: left;
}

.official-writing-doc-open strong {
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 0.78rem;
    color: var(--text-main);
}

.official-writing-doc-open small {
    color: #94a3b8;
    font-size: 0.66rem;
}

.official-writing-doc-actions {
    display: flex;
    gap: 2px;
    flex: 0 0 auto;
}

.official-writing-doc-actions button {
    border: 0;
    background: transparent;
    color: #64748b;
    font-size: 0.68rem;
    padding: 3px 5px;
    border-radius: 5px;
    cursor: pointer;
}

.official-writing-doc-actions button:hover {
    background: rgba(148, 163, 184, 0.18);
    color: #ef4444;
}

/* ===== 知识库检索 ===== */
.official-writing-kb-search {
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 8px;
}

.official-writing-kb-search-row {
    display: flex;
    gap: 6px;
}

.official-writing-kb-search .form-input {
    min-width: 0;
    height: 34px;
    margin-bottom: 0;
    padding: 0 8px;
    border-radius: 8px;
    font-size: 0.76rem;
}

.official-writing-kb-search-row .form-input {
    flex: 1 1 auto;
}

.official-writing-kb-search-row .btn-secondary {
    flex: 0 0 auto;
    height: 34px;
    padding: 0 10px;
    font-size: 0.74rem;
}

.official-writing-kb-results {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.official-writing-kb-result {
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 7px;
    padding: 7px 8px;
    background: #f8fafc;
}

.official-writing-kb-result-head {
    display: flex;
    justify-content: space-between;
    gap: 8px;
    font-size: 0.68rem;
    color: #64748b;
}

.official-writing-kb-result-head em {
    flex: 0 0 auto;
    color: #2563eb;
    font-style: normal;
    font-weight: 700;
}

.official-writing-kb-result p {
    margin: 4px 0 6px;
    font-size: 0.74rem;
    color: #334155;
    line-height: 1.5;
}

.official-writing-kb-result-actions {
    display: flex;
    gap: 6px;
}

.official-writing-kb-result-actions button {
    border: 1px solid rgba(148, 163, 184, 0.3);
    border-radius: 6px;
    background: #fff;
    color: #475569;
    font-size: 0.7rem;
    padding: 3px 8px;
    cursor: pointer;
}

.official-writing-kb-result-actions button:hover {
    border-color: rgba(37, 99, 235, 0.4);
    color: #2563eb;
}

.official-writing-kb-divider {
    padding: 6px 10px 2px;
    font-size: 0.68rem;
    font-weight: 700;
    color: #94a3b8;
}

/* ===== 发文要素表单 ===== */
.official-writing-elements-form {
    flex: 1;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 4px 10px 12px 2px;
}

.official-writing-elements-form .form-input {
    min-width: 0;
    height: 34px;
    margin-bottom: 10px;
    padding: 0 11px;
    border-radius: 8px;
    font-size: 0.82rem;
}

.official-writing-elements-form .form-input:last-child {
    margin-bottom: 0;
}

.official-writing-elements-group {
    border: 1px solid rgba(148, 163, 184, 0.25);
    border-radius: 8px;
    padding: 8px 10px 10px;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.official-writing-elements-group legend {
    padding: 0 4px;
    font-size: 0.74rem;
    font-weight: 800;
    color: #2563eb;
}

.official-writing-elements-group label {
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--text-muted);
    margin-top: 6px;
    margin-bottom: 2px;
}

.official-writing-elements-note {
    font-size: 0.68rem;
    color: #94a3b8;
    line-height: 1.5;
    margin: 0;
}

/* ===== 逐句改写对比弹窗 ===== */
.official-writing-diff-modal {
    position: absolute;
    inset: 0;
    z-index: 20;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    background: rgba(15, 23, 42, 0.4);
}

.official-writing-diff-modal.hidden {
    display: none;
}

.official-writing-diff-dialog {
    width: min(820px, 96%);
    max-height: 88%;
    display: flex;
    flex-direction: column;
    background: #fff;
    border-radius: 12px;
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.3);
    overflow: hidden;
}

.official-writing-diff-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 12px 16px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.2);
    background: #f8fafc;
}

.official-writing-diff-head h4 {
    margin: 0;
    font-size: 0.92rem;
}

.official-writing-diff-head span {
    font-size: 0.72rem;
    color: #64748b;
}

.official-writing-diff-stream {
