.regulations-query-input {
    width: min(320px, 100%);
    flex: 0 1 300px;
}

.regulations-filter-input {
    width: 132px;
    flex: 0 1 132px;
}

.regulations-toolbar h4 {
    margin: 0 0 3px;
    color: var(--text-main);
    font-size: 1rem;
}

.regulations-section-head.compact {
    align-items: baseline;
}

.regulations-ai-card {
    padding: 12px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: #fff;
}

.regulations-ai-card p,
.regulations-match p,
.regulations-article p {
    margin: 0;
    color: var(--text-main);
    line-height: 1.65;
    word-break: break-word;
}

.regulations-original-document {
    padding: 14px;
    border: 1px solid rgba(148, 163, 184, 0.14);
    border-radius: 8px;
    background: #fff;
}

.regulations-article {
    padding: 12px;
    border: 1px solid rgba(148, 163, 184, 0.14);
    border-radius: 8px;
    background: #fff;
}

/* 条文与 AI 回答正文的 Markdown 排版 */
.regulations-article-body {
    color: var(--text-main);
    font-size: 0.85rem;
    line-height: 1.7;
    word-break: break-word;
}

.regulations-article-body > *:first-child {
    margin-top: 0;
}

.regulations-article-body > *:last-child {
    margin-bottom: 0;
}

.regulations-article-body h1,
.regulations-article-body h2,
.regulations-article-body h3,
.regulations-article-body h4 {
    margin: 16px 0 8px;
    color: var(--text-main);
    font-weight: 800;
    line-height: 1.4;
}

.regulations-article-body h1 { font-size: 1.04rem; }
.regulations-article-body h2 { font-size: 0.96rem; }
.regulations-article-body h3 { font-size: 0.9rem; }
.regulations-article-body h4 { font-size: 0.85rem; }

.regulations-article-body h2 {
    padding-bottom: 5px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.18);
}

.regulations-article-body p {
    margin: 8px 0;
    color: var(--text-main);
    line-height: 1.7;
}

.regulations-article-body ul,
.regulations-article-body ol {
    margin: 8px 0;
    padding-left: 20px;
}

.regulations-article-body li {
    margin: 4px 0;
    line-height: 1.65;
}

.regulations-article-body li::marker {
    color: var(--primary);
}

.regulations-article-body strong {
    color: var(--text-main);
    font-weight: 800;
}

.regulations-article-body a {
    color: var(--primary);
    text-decoration: none;
}

.regulations-article-body a:hover {
    text-decoration: underline;
}

.regulations-article-body code {
    padding: 1px 5px;
    border-radius: 4px;
    background: rgba(15, 23, 42, 0.06);
    color: #be123c;
    font-size: 0.82em;
    word-break: break-all;
}

.regulations-article-body pre {
    margin: 10px 0;
    padding: 10px 12px;
    overflow-x: auto;
    border-radius: 8px;
    background: #f8fafc;
    border: 1px solid rgba(148, 163, 184, 0.18);
}

.regulations-article-body pre code {
    padding: 0;
    background: transparent;
    color: var(--text-main);
}

.regulations-article-body blockquote {
    margin: 10px 0;
    padding: 4px 12px;
    border-left: 3px solid rgba(16, 163, 127, 0.45);
    color: var(--text-muted);
    background: rgba(16, 163, 127, 0.04);
    border-radius: 0 6px 6px 0;
}

.regulations-article-body table {
    width: 100%;
    margin: 10px 0;
    border-collapse: collapse;
    font-size: 0.8rem;
}

.regulations-article-body th,
.regulations-article-body td {
    padding: 6px 10px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    text-align: left;
}

.regulations-article-body th {
    background: #f8fafc;
    font-weight: 700;
}

.regulations-article-body hr {
    margin: 14px 0;
    border: 0;
    border-top: 1px solid rgba(148, 163, 184, 0.22);
}

.regulations-ai-question-input {
    min-height: 96px;
    resize: vertical;
}

.regulations-ai-answer,
.regulations-search-results {
    min-height: 0;
}

.regulations-search-results {
    overflow-y: auto;
}

.regulations-match span {
    color: var(--primary);
    font-size: 0.76rem;
    font-weight: 800;
}

.regulations-match p {
    color: var(--text-muted);
    font-size: 0.78rem;
}

/* 检索词高亮 */
.regulations-hl {
    padding: 0 1px;
    border-radius: 3px;
    background: rgba(250, 204, 21, 0.38);
    color: inherit;
}

/* 跳转命中条文后的短暂高亮 */
.regulations-article-flash {
    animation: regulations-article-flash 1.8s ease;
}

@keyframes regulations-article-flash {
    0%, 30% {
        border-color: rgba(16, 163, 127, 0.55);
        background: rgba(16, 163, 127, 0.1);
        box-shadow: 0 0 0 2px rgba(16, 163, 127, 0.18);
    }
    100% {
        border-color: rgba(148, 163, 184, 0.14);
        background: #fff;
        box-shadow: none;
    }
}

/* 加载态提示 */
.regulations-loading {
    display: grid;
    min-height: 60px;
    place-items: center;
    color: var(--text-muted);
    font-size: 0.82rem;
}

.regulations-loading::before {
    content: '';
    width: 15px;
    height: 15px;
    margin-right: 8px;
    border: 2px solid rgba(16, 163, 127, 0.25);
    border-top-color: var(--primary);
    border-radius: 50%;
    grid-row: 1;
    animation: regulations-spin 0.7s linear infinite;
}

@keyframes regulations-spin {
    to { transform: rotate(360deg); }
}

/* AI 回答的引用条文 */
.regulations-ai-sources {
    display: grid;
    gap: 6px;
    margin-top: 12px;
    padding-top: 10px;
    border-top: 1px solid rgba(148, 163, 184, 0.18);
}

.regulations-ai-sources-head {
    color: var(--text-muted);
    font-size: 0.72rem;
    font-weight: 700;
}

.regulations-ai-source {
    display: grid;
    gap: 3px;
    width: 100%;
    padding: 7px 9px;
    text-align: left;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: #f8fafc;
    cursor: pointer;
    transition: border-color 0.16s ease, background 0.16s ease;
}

.regulations-ai-source:hover {
    border-color: rgba(16, 163, 127, 0.32);
    background: rgba(16, 163, 127, 0.05);
}

.regulations-ai-source-label {
    color: var(--primary);
    font-size: 0.76rem;
    font-weight: 800;
    display: flex;
    align-items: center;
    gap: 6px;
}

.regulations-ai-source-rel {
    display: inline-block;
    padding: 2px 6px;
    font-size: 0.68rem;
    font-weight: 600;
    font-style: normal;
    color: var(--primary);
    background: rgba(16, 163, 127, 0.12);
    border-radius: 4px;
}

.regulations-ai-source.viaLink {
    background: rgba(16, 163, 127, 0.04);
    border-color: rgba(16, 163, 127, 0.22);
}

.regulations-ai-source.viaLink:hover {
    border-color: rgba(16, 163, 127, 0.4);
    background: rgba(16, 163, 127, 0.08);
}

.regulations-ai-source-excerpt {
    color: var(--text-muted);
    font-size: 0.74rem;
    line-height: 1.5;
    overflow: hidden;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    -webkit-box-orient: vertical;
}

.regulations-admin-panel:not(.hidden) {
    position: fixed;
    inset: 0;
    z-index: 6200;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0;
    padding: 20px;
    border: 0;
    background: rgba(15, 23, 42, 0.42);
}

.workspace-modal.regulations-admin-dialog,
.regulations-inline-form:not(.hidden) {
    width: min(760px, calc(100vw - 32px));
    height: auto;
    max-height: calc(100vh - 32px);
    overflow: hidden;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: #fff;
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.22);
    display: flex;
    flex-direction: column;
}

.workspace-modal.regulations-admin-dialog {
    padding: 0;
}

.workspace-modal.regulations-search-dialog {
    width: min(840px, calc(100vw - 32px));
}

.workspace-modal.regulations-detail-dialog {
    width: min(1120px, calc(100vw - 32px));
}

.workspace-modal.regulations-ai-dialog {
    width: min(1120px, calc(100vw - 32px));
}

.workspace-modal.regulations-graph-dialog {
    width: min(1600px, calc(100vw - 24px));
}

.workspace-modal.regulations-similar-dialog {
    width: min(760px, calc(100vw - 32px));
}

.regulations-dialog-body,
.regulations-ai-modal-body {
    display: grid;
    gap: 12px;
}

.regulations-search-modal-body,
.regulations-ai-modal-body {
    background: #fff !important;
}

.regulations-inline-form:not(.hidden) {
    position: fixed;
    top: 50%;
    left: 50%;
    z-index: 6300;
    display: grid;
    gap: 10px;
    margin: 0;
    padding: 0;
    transform: translate(-50%, -50%);
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.22), 0 0 0 9999px rgba(15, 23, 42, 0.42);
}

.regulations-admin-form {
    display: grid;
    gap: 14px;
    padding: 14px;
}

.regulations-admin-group {
    display: grid;
    gap: 10px;
    padding: 12px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 10px;
    background: #f8fafc;
}

.regulations-admin-group-head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
}

.regulations-admin-group-head strong {
    color: var(--text-main);
    font-size: 0.84rem;
}

.regulations-admin-group-head span {
    color: var(--text-muted);
    font-size: 0.74rem;
}

.regulations-inline-form .regulations-admin-group,
.regulations-inline-form .regulations-admin-actions {
    margin-right: 14px;
    margin-left: 14px;
}

.regulations-inline-form .regulations-admin-actions {
    margin-bottom: 14px;
}

.regulations-dialog-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    padding: 14px;
    border-bottom: 1px solid var(--border);
}

.regulations-dialog-head h3 {
    margin: 0 0 4px;
    color: var(--text-main);
    font-size: 1rem;
}

.regulations-dialog-head p {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.78rem;
    line-height: 1.55;
}

#regulations-detail-admin-actions {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
}

.regulations-admin-form label,
.regulations-inline-form label {
    display: grid;
    gap: 5px;
    color: #475569;
    font-size: 0.78rem;
    font-weight: 700;
}

.regulations-file-field {
    display: grid;
    gap: 6px;
}

.regulations-file-field span {
    color: #475569;
    font-size: 0.78rem;
    font-weight: 700;
}

.regulations-file-control {
    position: relative;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    min-height: 38px;
    overflow: hidden;
    border: 1px dashed rgba(16, 163, 127, 0.32);
    border-radius: 8px;
    background: #fff;
    transition: border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease;
}

.regulations-file-control:hover {
    border-color: rgba(16, 163, 127, 0.52);
    background: rgba(16, 163, 127, 0.035);
}

.regulations-file-input {
    position: absolute;
    inset: 0;
    z-index: 2;
    width: 100%;
    height: 100%;
    opacity: 0;
    cursor: pointer;
}

.regulations-file-input:focus-visible + .regulations-file-button {
    box-shadow: inset 0 0 0 2px rgba(16, 163, 127, 0.24);
}

.regulations-file-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 38px;
    padding: 0 12px;
    border-right: 1px solid rgba(148, 163, 184, 0.2);
    background: rgba(248, 250, 252, 0.92);
    color: var(--text-main);
    font-size: 0.78rem;
    font-weight: 800;
    white-space: nowrap;
}

.regulations-file-summary {
    min-width: 0;
    overflow: hidden;
    padding: 0 12px;
    color: var(--text-muted);
    font-size: 0.78rem;
    font-weight: 600;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.regulations-empty,
.regulations-placeholder {
    display: grid;
    min-height: 90px;
    place-items: center;
    color: var(--text-muted);
    font-size: 0.82rem;
    text-align: center;
    border: 1px dashed rgba(148, 163, 184, 0.28);
    border-radius: 8px;
    background: rgba(248, 250, 252, 0.74);
}

.regulations-empty.compact {
    min-height: 48px;
}

.regulations-panel.is-busy {
    cursor: progress;
}

.regulations-panel.is-busy button,
.regulations-panel.is-busy input,
.regulations-panel.is-busy textarea,
.regulations-panel.is-busy select {
    pointer-events: none;
}

@media (max-width: 1100px) {
    .regulations-query-input,
    .regulations-filter-input {
        flex: 1 1 180px;
        width: auto;
    }
}

@media (max-width: 720px) {
    .regulations-admin-grid {
        grid-template-columns: 1fr;
    }

    .regulations-admin-group-head {
        flex-direction: column;
        align-items: flex-start;
    }

    .regulations-toolbar,
    .regulations-ai-actions,
    .regulations-admin-actions {
        align-items: stretch;
        flex-direction: column;
    }

    .regulations-query-input,
    .regulations-filter-input {
        flex-basis: auto;
        width: 100%;
    }

}

.regulations-file-hint {
    color: var(--text-muted);
    font-size: 0.74rem;
    line-height: 1.5;
}

/* 快速预设模板 */
.regulations-preset-row {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.regulations-preset-btn {
    padding: 6px 14px;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: #fff;
    color: var(--text-main);
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
}

.regulations-preset-btn:hover {
    border-color: var(--primary);
    background: var(--bg-hover, #f8f9fa);
    color: var(--primary);
}

.regulations-preset-btn:active {
    transform: translateY(1px);
}

/* 徽章：归档、已废止、重复提醒 */
.regulations-badge {
    display: inline-block;
    padding: 2px 6px;
    border-radius: 3px;
    font-size: 0.7rem;
    font-weight: 600;
    vertical-align: middle;
    margin-left: 6px;
}

.regulations-badge.archived {
    background: var(--bg-secondary);
    color: var(--text-muted);
}

.regulations-badge.expired {
    background: var(--color-warning-bg, #fff4e5);
    color: var(--color-warning, #d97706);
}

.regulations-badge.warning {
    background: var(--color-warning-bg, #fff4e5);
    color: var(--color-warning, #d97706);
}

/* 多轮问答气泡 */
.regulations-ai-turn {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-bottom: 16px;
}

.regulations-ai-turn:last-child {
    margin-bottom: 0;
}

.regulations-ai-question {
    align-self: flex-end;
    max-width: 75%;
    padding: 10px 14px;
    background: var(--primary);
    color: white;
    border-radius: 12px 12px 2px 12px;
    font-size: 0.9rem;
    line-height: 1.5;
    white-space: pre-wrap;
    word-wrap: break-word;
}

.regulations-ai-card {
    align-self: flex-start;
    max-width: 85%;
}

/* 导入结果面板 */
.regulations-import-result-panel {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 9999;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.regulations-import-result-panel.hidden {
    display: none;
}

.regulations-import-section {
    margin-bottom: 20px;
}

.regulations-import-section:last-child {
    margin-bottom: 0;
}

.regulations-import-item {
    padding: 10px 12px;
    margin-bottom: 8px;
    border-radius: 6px;
    font-size: 0.85rem;
    line-height: 1.5;
}

.regulations-import-item:last-child {
    margin-bottom: 0;
}

.regulations-import-item.success {
    background: var(--color-success-bg, #f0fdf4);
    border-left: 3px solid var(--color-success, #22c55e);
}

.regulations-import-item.error {
    background: var(--color-error-bg, #fef2f2);
    border-left: 3px solid var(--color-error, #ef4444);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.regulations-import-item.error strong {
    font-weight: 600;
    color: var(--text);
}

.regulations-import-item.error span {
    color: var(--text-secondary);
    font-size: 0.8rem;
}

/* 版本对比面板 */
.regulations-compare-panel .regulations-admin-dialog {
    max-width: 900px;
}

.regulations-diff-summary {
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 16px;
    margin-bottom: 20px;
    background: var(--bg-secondary);
    border-radius: 8px;
    border-left: 4px solid var(--primary);
}

.regulations-diff-summary strong {
    font-size: 1.05rem;
    font-weight: 600;
    color: var(--text);
}

.regulations-diff-summary span {
    font-size: 0.85rem;
    color: var(--text-secondary);
}

.regulations-diff-section {
    margin-bottom: 24px;
}

.regulations-diff-section:last-child {
    margin-bottom: 0;
}

.regulations-diff-article {
    padding: 14px;
    margin-bottom: 12px;
    border-radius: 6px;
    border-left: 4px solid;
}

.regulations-diff-article:last-child {
    margin-bottom: 0;
}

.regulations-diff-article.added {
    background: var(--color-success-bg, #f0fdf4);
    border-color: var(--color-success, #22c55e);
}

.regulations-diff-article.removed {
    background: var(--color-error-bg, #fef2f2);
    border-color: var(--color-error, #ef4444);
}

.regulations-diff-article.changed {
    background: var(--bg-secondary);
    border-color: var(--color-warning, #d97706);
}

.regulations-diff-article strong {
    display: block;
    font-weight: 600;
    margin-bottom: 4px;
    color: var(--text);
}

.regulations-diff-article > span {
    display: block;
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 8px;
}

.regulations-diff-article pre {
    font-family: var(--font-mono, monospace);
    font-size: 0.85rem;
    line-height: 1.6;
    white-space: pre-wrap;
    word-wrap: break-word;
    margin: 0;
    color: var(--text);
}

.regulations-diff-lines {
    display: flex;
    flex-direction: column;
    gap: 2px;
    font-family: var(--font-mono, monospace);
    font-size: 0.85rem;
}

.diff-line {
    padding: 4px 8px;
    line-height: 1.5;
    white-space: pre-wrap;
    word-wrap: break-word;
}

.diff-line.added {
    background: var(--color-success-bg, #f0fdf4);
    color: var(--color-success, #16a34a);
}

.diff-line.removed {
    background: var(--color-error-bg, #fef2f2);
    color: var(--color-error, #dc2626);
}

.diff-line.eq {
    color: var(--text-secondary);
}

/* #5 废止/修订提醒横幅 */
.regulations-supersede-banner {
    margin: 0 0 12px;
    padding: 10px 14px;
    border-left: 4px solid var(--color-warning, #d97706);
    border-radius: 6px;
    background: var(--color-warning-bg, #fff4e5);
}

.regulations-supersede-banner strong {
    color: var(--color-warning, #b45309);
    font-size: 0.85rem;
    margin-right: 6px;
}

.regulations-supersede-banner span {
    color: var(--text-secondary);
    font-size: 0.8rem;
}

.regulations-supersede-banner ul {
    margin: 6px 0 0;
    padding-left: 18px;
}

.regulations-supersede-banner li {
    font-size: 0.8rem;
    line-height: 1.7;
    color: var(--text);
}

.regulations-supersede-link {
    background: none;
    border: none;
    padding: 0;
    color: var(--primary);
    font-size: 0.8rem;
    cursor: pointer;
    text-decoration: underline;
}

/* #6 变更影响分析 */
.regulations-impact-referers {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin-top: 6px;
}

.regulations-impact-referer {
    padding: 4px 10px;
    border: 1px solid rgba(16, 163, 127, 0.25);
    border-radius: 6px;
    background: rgba(16, 163, 127, 0.05);
    color: var(--primary);
    font-size: 0.78rem;
    cursor: pointer;
    transition: all 0.15s ease;
}

.regulations-impact-referer:hover {
    background: rgba(16, 163, 127, 0.12);
    border-color: var(--primary);
}

.regulations-impact-referer.cross {
    border-color: rgba(37, 99, 235, 0.25);
    background: rgba(37, 99, 235, 0.05);
    color: #2563eb;
}

.regulations-impact-referer.cross:hover {
    background: rgba(37, 99, 235, 0.12);
    border-color: #2563eb;
}

/* #4 条文引用网络 */
.regulations-graph-dialog {
    width: min(1600px, calc(100vw - 24px));
}

.regulations-graph-body {
    padding: 14px;
    overflow: hidden;
    max-height: calc(100vh - 150px);
}

.regulations-graph-summary {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 10px;
}

.regulations-graph-summary span {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 4px 8px;
    border: 1px solid #dbe3ef;
    border-radius: 6px;
    background: #fff;
    color: var(--text-secondary);
    font-size: 0.78rem;
}

.regulations-graph-summary strong {
    color: var(--text-main);
}

.regulations-graph-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    margin-bottom: 10px;
    font-size: 0.76rem;
    color: var(--text-secondary);
}

.regulations-graph-legend-item {
    display: inline-flex;
    align-items: center;
    gap: 5px;
}

.regulations-graph-legend-item i {
    width: 12px;
    height: 3px;
    border-radius: 2px;
    display: inline-block;
}

.regulations-graph-layout {
    display: grid;
    grid-template-columns: minmax(620px, 1fr) minmax(360px, 430px);
    gap: 12px;
    align-items: stretch;
    min-height: 0;
}

.regulations-graph-canvas-wrap {
    min-width: 0;
    overflow: hidden;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    background: #f8fafc;
    display: flex;
    flex-direction: column;
}

.regulations-graph-canvas-head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
    padding: 9px 10px;
    border-bottom: 1px solid #e2e8f0;
    background: #fff;
}

.regulations-graph-canvas-head strong {
    color: var(--text-main);
    font-size: 0.82rem;
}

.regulations-graph-canvas-head span {
    color: var(--text-secondary);
    font-size: 0.74rem;
}

.regulations-graph-canvas-scroll {
    min-height: 430px;
    max-height: calc(100vh - 315px);
    overflow-y: auto;
    overflow-x: hidden;
}

.regulations-graph-svg {
    display: block;
    width: 100%;
    max-width: 100%;
    height: auto;
    background: #f8fafc;
}

.regulations-graph-node {
    cursor: pointer;
}

.regulations-graph-node rect {
    fill: #fff;
    stroke: rgba(16, 163, 127, 0.46);
    stroke-width: 1.2;
    filter: drop-shadow(0 1px 1px rgba(15, 23, 42, 0.08));
}

.regulations-graph-node text {
    fill: #25364a;
    font-size: 10.5px;
    font-weight: 700;
    pointer-events: none;
}

.regulations-graph-node tspan {
    dominant-baseline: middle;
}

.regulations-graph-node:hover rect,
.regulations-graph-node:focus rect {
    fill: rgba(16, 163, 127, 0.08);
    stroke: var(--primary);
    stroke-width: 2;
}

.regulations-graph-node:hover text,
.regulations-graph-node:focus text {
    fill: var(--primary);
}

.regulations-graph-note {
    padding: 8px 10px;
    border-top: 1px solid #e2e8f0;
    color: var(--text-secondary);
    font-size: 0.78rem;
}

.regulations-graph-edge-list {
    max-height: calc(100vh - 255px);
    min-height: 430px;
    overflow: auto;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    background: #fff;
}

.regulations-graph-edge-list-head {
    position: sticky;
    top: 0;
    z-index: 1;
    padding: 9px 10px;
    border-bottom: 1px solid #e2e8f0;
    background: #fff;
    font-size: 0.82rem;
    font-weight: 700;
    color: var(--text-main);
}

.regulations-graph-edge-item {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    gap: 8px;
    align-items: center;
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f7;
}

.regulations-graph-edge-item:last-child {
    border-bottom: 0;
}

.regulations-graph-edge-link {
    min-width: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: #1f3b57;
    text-align: left;
    font: inherit;
    font-size: 0.78rem;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    cursor: pointer;
}

.regulations-graph-edge-link:hover,
.regulations-graph-edge-link:focus {
    color: var(--primary);
    text-decoration: underline;
}

.regulations-graph-edge-type {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 46px;
    padding: 2px 6px;
    border-radius: 999px;
    background: color-mix(in srgb, var(--edge-color) 12%, white);
    color: var(--edge-color);
    font-size: 0.7rem;
    font-weight: 700;
}

@media (max-width: 860px) {
    .regulations-graph-layout {
        grid-template-columns: 1fr;
    }

    .regulations-graph-canvas-scroll,
    .regulations-graph-edge-list {
        max-height: 300px;
        min-height: 260px;
    }
}
/* 分条渲染：每条带锚点，便于精确跳转 */
.regulations-article-block {
    margin-bottom: 18px;
    padding: 12px 14px;
    border-left: 3px solid rgba(16, 163, 127, 0.15);
    border-radius: 6px;
    background: rgba(16, 163, 127, 0.02);
    scroll-margin-top: 80px;
}

.regulations-article-block-head {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 8px;
    font-size: 0.88rem;
}

.regulations-article-block-head strong {
    color: var(--primary);
}

/* #8 条文状态徽章 */
.regulations-article-badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 0.72rem;
    font-weight: 500;
}

.regulations-article-badge.superseded {
    background: var(--color-warning-bg, #fff4e5);
    color: var(--color-warning, #d97706);
}

.regulations-article-badge.repealed {
    background: var(--color-error-bg, #fef2f2);
    color: var(--color-error, #dc2626);
}

.regulations-article-badge.amended {
    background: rgba(37, 99, 235, 0.08);
    color: #2563eb;
}

/* #13 修订时间线 */
.regulations-timeline-body {
    padding: 16px;
    max-height: calc(100vh - 180px);
    overflow: auto;
}

.regulations-timeline {
    position: relative;
    padding-left: 32px;
}

.regulations-timeline::before {
    content: '';
    position: absolute;
    left: 11px;
    top: 0;
    bottom: 0;
    width: 2px;
    background: linear-gradient(to bottom, var(--primary), rgba(16, 163, 127, 0.2));
}

.regulations-timeline-node {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
    padding: 12px 14px;
    margin-bottom: 14px;
    border: 1px solid rgba(16, 163, 127, 0.2);
    border-radius: 8px;
    background: #fff;
    cursor: pointer;
    transition: all 0.2s ease;
    text-align: left;
}

.regulations-timeline-node:hover {
    border-color: var(--primary);
    background: rgba(16, 163, 127, 0.04);
    transform: translateX(3px);
}

.regulations-timeline-node.active {
    border-color: var(--primary);
    background: rgba(16, 163, 127, 0.08);
    font-weight: 600;
}

.regulations-timeline-dot {
    position: absolute;
    left: -26px;
    top: 18px;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--primary);
    box-shadow: 0 0 0 3px #fff, 0 0 0 5px rgba(16, 163, 127, 0.2);
}

.regulations-timeline-node.active .regulations-timeline-dot {
    width: 14px;
    height: 14px;
    top: 16px;
    left: -28px;
    box-shadow: 0 0 0 3px #fff, 0 0 0 6px rgba(16, 163, 127, 0.35);
}

.regulations-timeline-label {
    font-size: 0.9rem;
    color: var(--text);
}

.regulations-timeline-meta {
    font-size: 0.75rem;
    color: var(--text-secondary);
}

/* #7 导入预览 */
.regulations-preview-body {
    padding: 14px;
    max-height: calc(100vh - 180px);
    overflow: auto;
}

.regulations-preview-summary {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--border);
}

.regulations-preview-summary strong {
    font-size: 0.92rem;
    color: var(--text);
}

.regulations-preview-summary span {
    font-size: 0.78rem;
    color: var(--text-secondary);
}

.regulations-preview-articles {
    margin-bottom: 14px;
}

.regulations-preview-article {
    padding: 10px 12px;
    margin-bottom: 8px;
    border: 1px solid var(--border);
    border-radius: 6px;
    background: #fafafa;
}

.regulations-preview-article-head {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 6px;
}

.regulations-preview-article-head strong {
    font-size: 0.85rem;
    color: var(--primary);
}

.regulations-preview-title {
    font-size: 0.78rem;
    color: var(--text-secondary);
}

.regulations-preview-content {
    font-size: 0.8rem;
    color: var(--text);
    line-height: 1.5;
}

.regulations-preview-checkbox {
    width: 16px;
    height: 16px;
    cursor: pointer;
}

.regulations-graph-node:hover text,
.regulations-graph-node:focus text {
    font-weight: 700;
    fill: var(--primary);
}

/* 条文块头部工具区 */
.regulations-article-block-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.regulations-article-block-tools {
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

/* #10 批注 */
.regulations-article-annotate {
    padding: 2px 10px;
    border: 1px solid rgba(16, 163, 127, 0.25);
    border-radius: 12px;
    background: rgba(16, 163, 127, 0.04);
    color: var(--primary);
    font-size: 0.72rem;
    cursor: pointer;
    transition: all 0.15s ease;
}

.regulations-article-annotate:hover {
    background: rgba(16, 163, 127, 0.12);
    border-color: var(--primary);
}

.regulations-annotation-body {
    padding: 16px;
    max-height: calc(100vh - 180px);
    overflow: auto;
}

.regulations-annotation-form {
    margin-bottom: 16px;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--border);
}

.regulations-annotation-form textarea {
    width: 100%;
    margin-bottom: 8px;
}

.regulations-annotation-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.regulations-annotation-item {
    padding: 10px 12px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: #fafafa;
}

.regulations-annotation-meta {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 6px;
    font-size: 0.78rem;
    color: var(--text-secondary);
}

.regulations-annotation-meta strong {
    color: var(--text);
}

.regulations-annotation-delete {
    margin-left: auto;
    color: var(--color-error, #dc2626);
}

.regulations-annotation-content {
    font-size: 0.85rem;
    line-height: 1.6;
    color: var(--text);
    white-space: pre-wrap;
    word-wrap: break-word;
}

/* #11 AI 报告导出按钮 */
.regulations-ai-turn-actions {
    display: flex;
    justify-content: flex-end;
    margin-top: 12px;
    padding-top: 12px;
    border-top: 1px solid rgba(148, 163, 184, 0.18);
}

.regulations-ai-export-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 96px;
    min-height: 34px;
    padding: 0 14px;
    border: 1px solid rgba(16, 163, 127, 0.28);
    border-radius: 8px;
    background: #fff;
    color: var(--primary);
    font-size: 0.8rem;
    font-weight: 800;
    line-height: 1;
    cursor: pointer;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.06);
    transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
}

.regulations-ai-export-btn:hover,
.regulations-ai-export-btn:focus-visible {
    border-color: rgba(16, 163, 127, 0.48);
    background: rgba(16, 163, 127, 0.06);
    box-shadow: 0 6px 14px rgba(15, 23, 42, 0.08);
    outline: none;
}

.regulations-ai-export-btn:active {
    transform: translateY(1px);
}






/* #2 / #14 语义混合检索、保存检索、相似条文 */
.regulations-search-results.hidden {
    display: none;
}

.regulations-search-modal-results,
.regulations-ai-search-results {
    display: grid;
    gap: 8px;
    padding: 10px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.94);
    scrollbar-gutter: stable;
}

.regulations-search-modal-results {
    max-height: min(420px, 46vh);
    margin-top: 10px;
}

.regulations-ai-search-results {
    max-height: 280px;
}

.regulations-search-modal-results .regulations-section-head,
.regulations-ai-search-results .regulations-section-head {
    min-height: 22px;
    padding-bottom: 2px;
}

.regulations-match {
    display: grid;
    width: 100%;
    min-width: 0;
    gap: 3px;
    padding: 8px 10px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: rgba(248, 250, 252, 0.72);
    color: var(--text-main);
    text-align: left;
    cursor: pointer;
    transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}

.regulations-match strong,
.regulations-match span,
.regulations-match p {
    min-width: 0;
}

.regulations-match strong {
    overflow: hidden;
    color: var(--text-main);
    font-size: 0.8rem;
    font-weight: 850;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.regulations-match:hover,
.regulations-match:focus-visible {
    border-color: rgba(16, 163, 127, 0.34);
    background: rgba(16, 163, 127, 0.055);
    box-shadow: 0 0 0 2px rgba(16, 163, 127, 0.08);
    outline: none;
}

.regulations-mode-select {
    width: 104px;
    flex: 0 0 104px;
}

.regulations-saved-searches {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    gap: 8px 10px;
    margin: -2px 0 8px;
    padding: 8px 10px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: rgba(248, 250, 252, 0.72);
}

.regulations-saved-searches.hidden {
    display: none;
}

.regulations-saved-searches-head {
    display: inline-flex;
    align-items: baseline;
    gap: 6px;
    white-space: nowrap;
}

.regulations-saved-searches-head strong {
    color: var(--text-main);
    font-size: 0.78rem;
    font-weight: 800;
}

.regulations-saved-searches-head span {
    color: var(--text-muted);
    font-size: 0.7rem;
    font-weight: 700;
}

.regulations-saved-search-list {
    display: flex;
    min-width: 0;
    flex-wrap: wrap;
    gap: 6px;
}

.regulations-saved-search-item {
    display: inline-flex;
    min-width: 0;
    align-items: stretch;
}

.regulations-saved-search-chip,
.regulations-saved-search-delete,
.regulations-article-tool {
    border: 1px solid rgba(148, 163, 184, 0.22);
    background: #fff;
    color: var(--text-main);
    cursor: pointer;
    transition: border-color 0.15s ease, background 0.15s ease, color 0.15s ease;
}

.regulations-saved-search-chip {
    display: inline-grid;
    max-width: 260px;
    min-height: 30px;
    min-width: 0;
    gap: 1px;
    padding: 3px 9px;
    border-radius: 7px 0 0 7px;
    text-align: left;
}

.regulations-saved-search-chip strong,
.regulations-saved-search-chip span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.regulations-saved-search-chip strong {
    font-size: 0.72rem;
    font-weight: 800;
}

.regulations-saved-search-chip span {
    color: var(--text-muted);
    font-size: 0.66rem;
    font-weight: 650;
}

.regulations-saved-search-delete {
    min-height: 30px;
    padding: 0 8px;
    border-left: 0;
    border-radius: 0 7px 7px 0;
    color: #b91c1c;
    font-size: 0.68rem;
    font-weight: 800;
}

.regulations-saved-search-chip:hover,
.regulations-article-tool:hover {
    border-color: rgba(16, 163, 127, 0.35);
    background: rgba(16, 163, 127, 0.06);
    color: var(--primary);
}

.regulations-saved-search-delete:hover {
    border-color: rgba(220, 38, 38, 0.28);
    background: rgba(254, 242, 242, 0.9);
}

.regulations-match-score {
    margin-left: 6px;
    color: var(--text-muted);
    font-size: 0.68rem;
    font-style: normal;
    font-weight: 800;
}

.regulations-match-score.muted {
    color: #64748b;
}

.regulations-similar-dialog {
    width: min(760px, calc(100vw - 32px));
}

.regulations-similar-body {
    display: grid;
    gap: 10px;
    max-height: calc(100vh - 180px);
    overflow: auto;
    padding: 14px;
}

.regulations-similar-source {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 7px;
    padding: 9px 10px;
    border: 1px solid rgba(16, 163, 127, 0.16);
    border-radius: 8px;
    background: rgba(16, 163, 127, 0.04);
}

.regulations-similar-source strong {
    color: var(--primary);
    font-size: 0.82rem;
    font-weight: 850;
}

.regulations-similar-source span {
    color: var(--text-muted);
    font-size: 0.74rem;
    font-weight: 700;
}

.regulations-similar-list {
    display: grid;
    gap: 8px;
}

.regulations-similar-match {
    width: 100%;
}

.regulations-article-block-tools {
    flex-wrap: wrap;
    justify-content: flex-end;
}

.regulations-article-tool {
    min-height: 24px;
    padding: 2px 8px;
    border-radius: 12px;
    font-size: 0.72rem;
    font-weight: 800;
    line-height: 18px;
    white-space: nowrap;
}

.regulations-article-tool.regulations-article-annotate {
    border-color: rgba(16, 163, 127, 0.25);
    background: rgba(16, 163, 127, 0.04);
    color: var(--primary);
}

@media (max-width: 720px) {
    .regulations-mode-select {
        flex-basis: auto;
        width: 100%;
    }

    .regulations-saved-searches {
        grid-template-columns: 1fr;
    }

    .regulations-saved-search-chip {
        max-width: min(100%, 280px);
    }

    .regulations-search-modal-results,
    .regulations-ai-search-results {
        max-height: 42vh;
        padding: 8px;
    }

    .regulations-match {
        padding: 8px;
    }

    .regulations-match strong {
        white-space: normal;
    }

    .regulations-match-score {
        display: inline-flex;
        margin-left: 0;
        margin-top: 2px;
    }

    .regulations-article-block-head {
        align-items: flex-start;
        flex-direction: column;
    }

    .regulations-article-block-tools {
        justify-content: flex-start;
    }
}

/* 检索弹窗表单布局与样式优化 */
.regulations-search-form {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 16px;
    margin-bottom: 14px;
    padding: 6px 4px;
}

.regulations-search-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.regulations-search-field span {
    font-size: 0.8rem;
    color: var(--text-main);
    font-weight: 700;
}

.regulations-search-field .form-input {
    width: 100% !important;
    height: 36px;
    padding: 0 12px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: #fff;
    font-size: 0.85rem;
    box-sizing: border-box;
    flex: none !important; /* 重置 flex-basis，防止垂直 Flex 下高度被拉伸 */
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.regulations-search-field .form-input:focus {
    border-color: var(--primary);
    box-shadow: 0 0 0 3px rgba(16, 163, 127, 0.1);
    outline: none;
}

.regulations-search-field-wide {
    grid-column: span 2;
}

.regulations-search-archived {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-top: 26px;
    font-weight: 700;
    color: var(--text-main);
}

.regulations-search-archived input[type="checkbox"] {
    width: 16px;
    height: 16px;
    cursor: pointer;
}

.regulations-saved-searches {
    margin: 12px 0;
    padding: 10px 12px;
}

.regulations-search-modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 14px 4px 6px;
    border-top: 1px solid var(--border);
    margin-top: 12px;
}

.regulations-search-modal-actions .btn-primary,
.regulations-search-modal-actions .btn-secondary {
    height: 36px;
    min-width: 90px;
    font-size: 0.85rem;
    font-weight: 700;
    border-radius: 8px;
}


/* === styles/workspaces/apps/ocr.css === */
.ocr-view,
.pdf-tools-view {
    flex: 1;
    min-height: 0;
    min-width: 0;
    width: 100%;
    display: flex;
}

.doc-tool-layout {
    flex: 1;
    min-height: 0;
    min-width: 0;
    height: 100%;
    display: grid;
    grid-template-columns: minmax(260px, 300px) minmax(0, 1fr);
    gap: 10px;
    align-items: stretch;
}

.doc-tool-sidebar,
.doc-tool-main {
    min-height: 0;
    min-width: 0;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: #fff;
    box-shadow: none;
}

.doc-tool-sidebar {
    align-self: start;
    height: auto;
    max-height: 100%;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 10px;
    overflow: auto;
}

.doc-tool-main {
    height: 100%;
    display: flex;
    flex-direction: column;
    gap: 0;
    padding: 0;
    overflow: hidden;
}

.doc-tool-form,
.doc-tool-filter {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.doc-tool-filter {
    padding-top: 10px;
    border-top: 1px solid rgba(148, 163, 184, 0.14);
}

.doc-tool-field-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
}

.doc-tool-field {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 0;
    color: var(--text-muted);
    font-size: 0.72rem;
    font-weight: 800;
    line-height: 1.35;
}

.doc-tool-field-wide {
    grid-column: 1 / -1;
}

.doc-tool-field .form-input {
    width: 100%;
    height: 34px;
    min-height: 34px;
    margin: 0;
    padding: 0 10px;
    border-radius: 6px;
    font-size: 0.8rem;
    font-weight: 500;
    color: var(--text-main);
}

.doc-tool-field input[type="file"].form-input {
    height: 36px;
    min-height: 36px;
    padding: 3px 8px;
    line-height: 28px;
}

.doc-tool-field input[type="file"].form-input::file-selector-button,
.doc-tool-field input[type="file"].form-input::-webkit-file-upload-button {
    height: 28px;
    margin-right: 8px;
    padding: 0 10px;
    border-radius: 6px;
    font-size: 0.78rem;
}

.doc-tool-actions,
.doc-tool-head-actions,
.ocr-detail-actions,
.pdf-detail-actions,
.ocr-review-actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 7px;
}

.doc-tool-actions {
    padding-top: 2px;
}

.doc-tool-actions .btn-primary,
.doc-tool-actions .btn-secondary,
.doc-tool-head-actions .btn-secondary,
.ocr-detail-actions .btn-secondary,
.pdf-detail-actions .btn-secondary,
.ocr-review-actions .btn-primary,
.doc-tool-output-btn {
    height: 32px;
    min-height: 32px;
    padding: 0 11px;
    border-radius: 6px;
    font-size: 0.78rem;
    font-weight: 700;
    line-height: 1;
    white-space: nowrap;
}

.doc-tool-main-head,
.ocr-detail-head,
.pdf-detail-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    flex: 0 0 auto;
}

.doc-tool-main-head {
    min-height: 54px;
    padding: 10px 12px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
    background: #fff;
}

.doc-tool-main-head h4 {
    margin: 0 0 3px;
    color: var(--text-main);
    font-size: 1rem;
    line-height: 1.25;
}

.doc-tool-main-head span,
.ocr-detail-head span,
.pdf-detail-head span,
.ocr-text-head span {
    color: var(--text-muted);
    font-size: 0.74rem;
}

.doc-tool-head-actions {
    flex: 0 0 auto;
}

.doc-tool-table-wrap {
    flex: 0 0 auto;
    max-height: 220px;
    border: 1px solid rgba(148, 163, 184, 0.14);
    border-radius: 8px;
    background: #fff;
    overflow: auto;
}

.doc-tool-table {
    min-width: 760px;
    border-collapse: collapse;
}

.doc-tool-table th,
.doc-tool-table td {
    height: 38px;
    min-height: 38px;
    padding: 6px 8px;
    border: 1px solid rgba(148, 163, 184, 0.13);
    line-height: 1.25;
    vertical-align: middle;
}

.doc-tool-table th {
    background: #f8fafc;
}

.doc-tool-row {
    cursor: pointer;
}

.doc-tool-row.is-active td {
    background: rgba(16, 185, 129, 0.08);
}

.doc-tool-link {
    display: block;
    max-width: 100%;
    line-height: 1.25;
    border: 0;
    background: transparent;
    color: var(--text-main);
    font: inherit;
    font-weight: 700;
    text-align: left;
    cursor: pointer;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    padding: 0;
}

.doc-tool-link:hover,
.doc-tool-link:focus-visible {
    color: var(--primary);
    outline: none;
}

.doc-tool-table small {
    display: block;
    color: var(--text-muted);
    font-size: 0.7rem;
    line-height: 1.25;
    margin-top: 2px;
}

.doc-tool-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 54px;
    min-height: 22px;
    padding: 0 8px;
    border-radius: 999px;
    background: rgba(100, 116, 139, 0.12);
    color: #475569;
    font-size: 0.7rem;
    font-weight: 800;
    white-space: nowrap;
}

.doc-tool-badge.is-success,
.doc-tool-engine.is-success {
    background: rgba(16, 185, 129, 0.1);
    color: #047857;
}

.doc-tool-badge.is-warning,
.doc-tool-engine.is-warning {
    background: rgba(245, 158, 11, 0.12);
    color: #92400e;
}

.doc-tool-engine.is-muted {
    background: rgba(100, 116, 139, 0.08);
    color: #64748b;
}

.doc-tool-badge.is-danger {
    background: rgba(239, 68, 68, 0.1);
    color: #b91c1c;
}

.doc-tool-badge.is-info {
    background: rgba(59, 130, 246, 0.1);
    color: #1d4ed8;
}

.doc-tool-empty-cell,
.doc-tool-empty-detail,
.doc-tool-empty-small {
    color: var(--text-muted);
    font-size: 0.8rem;
    text-align: center;
}

.doc-tool-empty-cell {
    padding: 22px 12px !important;
}

.doc-tool-empty-detail {
    flex: 1;
    min-height: 240px;
    height: 100%;
    display: grid;
    place-items: center;
    border: 0;
    border-radius: 0;
    background: #fff;
}

.doc-tool-empty-small {
    padding: 10px;
    border: 1px dashed rgba(148, 163, 184, 0.26);
    border-radius: 8px;
    background: rgba(248, 250, 252, 0.74);
}

.doc-tool-engine-list {
    display: grid;
    gap: 6px;
    max-height: 156px;
    padding-top: 10px;
    border-top: 1px solid rgba(148, 163, 184, 0.14);
    overflow: auto;
}

.doc-tool-settings {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding-top: 10px;
    border-top: 1px solid rgba(148, 163, 184, 0.14);
}

.doc-tool-settings.hidden {
    display: none;
}

.doc-tool-engine {
    display: grid;
    grid-template-columns: minmax(76px, 0.7fr) minmax(0, 1fr);
    align-items: center;
    gap: 8px;
    min-height: 32px;
    padding: 7px 9px;
    border-radius: 8px;
    font-size: 0.74rem;
    line-height: 1.35;
}

.doc-tool-engine strong,
.doc-tool-engine span {
    min-width: 0;
    overflow-wrap: anywhere;
}

.doc-tool-engine span {
    color: inherit;
    text-align: right;
}

.ocr-detail,
.pdf-detail {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 10px;
    overflow: hidden;
}

.ocr-detail-head,
.pdf-detail-head {
    min-height: 46px;
    padding: 8px 10px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: rgba(248, 250, 252, 0.78);
}

.ocr-detail-head > div:first-child,
.pdf-detail-head > div:first-child {
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.ocr-detail-head strong,
.pdf-detail-head strong {
    max-width: min(420px, 46vw);
    overflow: hidden;
    color: var(--text-main);
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ocr-detail-head em,
.pdf-detail-head em {
    color: #b91c1c;
    font-style: normal;
    font-size: 0.76rem;
    overflow-wrap: anywhere;
}

.ocr-output-strip,
.pdf-output-list {
    display: flex;
    flex-wrap: wrap;
    gap: 7px;
    min-height: 34px;
}

.ocr-review-grid {
    flex: 1;
    min-height: 0;
    display: grid;
    grid-template-columns: 126px minmax(250px, 0.95fr) minmax(300px, 1.05fr);
    gap: 10px;
}

.ocr-page-list,
.ocr-preview-pane,
.ocr-text-pane {
    min-width: 0;
    min-height: 0;
    overflow: auto;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: #fff;
}

.ocr-page-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 8px;
}

.ocr-page-pill {
    min-height: 38px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 8px;
    background: #fff;
    color: var(--text-main);
    cursor: pointer;
    padding: 0 9px;
    font-size: 0.76rem;
}

.ocr-page-pill.is-active {
    border-color: rgba(16, 185, 129, 0.42);
    background: rgba(16, 185, 129, 0.08);
}

.ocr-page-pill em {
    color: var(--text-muted);
    font-style: normal;
    font-size: 0.7rem;
}

.ocr-preview-pane {
    display: grid;
    place-items: center;
    background: #f8fafc;
    padding: 10px;
}

.ocr-preview-pane img {
    display: block;
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
    border-radius: 6px;
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.1);
}

.ocr-text-pane {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 10px;
}

.ocr-text-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.ocr-review-textarea {
    flex: 0 0 170px;
    min-height: 140px;
    resize: vertical;
    line-height: 1.6;
    font-family: inherit;
}

.ocr-confirm-low {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--text-muted);
    font-size: 0.76rem;
    font-weight: 700;
}

.ocr-block-list {
    flex: 1;
    min-height: 0;
    overflow: auto;
    display: grid;
    align-content: start;
    gap: 6px;
}

.ocr-block-row {
    display: grid;
    grid-template-columns: 46px minmax(0, 1fr);
    gap: 8px;
    padding: 7px 8px;
    border-radius: 8px;
    background: rgba(248, 250, 252, 0.78);
    font-size: 0.76rem;
}

.ocr-block-row span {
    color: var(--text-muted);
    font-weight: 700;
}

.ocr-block-row p {
    margin: 0;
    color: var(--text-main);
    line-height: 1.45;
    word-break: break-word;
}

.ocr-preview-canvas {
    position: relative;
    width: 100%;
    max-width: 100%;
    margin: auto;
    background: #e5e7eb;
    border-radius: 6px;
    overflow: hidden;
    box-shadow: 0 8px 18px rgba(15, 23, 42, 0.1);
}

.ocr-preview-canvas img {
    width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    object-fit: contain;
    border-radius: 0;
    box-shadow: none;
}

.ocr-overlay-layer {
    position: absolute;
    inset: 0;
    pointer-events: none;
}

.ocr-overlay-box {
    position: absolute;
    padding: 0;
    border: 1.5px solid rgba(37, 99, 235, 0.86);
    background: rgba(37, 99, 235, 0.1);
    box-sizing: border-box;
    cursor: pointer;
    pointer-events: auto;
    transition: background 0.14s ease, border-color 0.14s ease, box-shadow 0.14s ease;
}

.ocr-overlay-box:hover,
.ocr-overlay-box.is-selected {
    border-color: #2563eb;
    background: rgba(37, 99, 235, 0.18);
    box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.18);
}

.ocr-overlay-box.is-low {
    border-color: rgba(217, 119, 6, 0.95);
    background: rgba(245, 158, 11, 0.18);
}

.ocr-overlay-box.is-low:hover,
.ocr-overlay-box.is-low.is-selected {
    border-color: #b45309;
    background: rgba(245, 158, 11, 0.26);
    box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.22);
}

.ocr-block-row.is-low {
    background: rgba(255, 251, 235, 0.88);
    box-shadow: inset 3px 0 0 rgba(245, 158, 11, 0.8);
}

.ocr-block-row.is-selected {
    background: rgba(219, 234, 254, 0.86);
    box-shadow: inset 3px 0 0 rgba(37, 99, 235, 0.85);
}


/* Regulations-style task table and modal layout for OCR / PDF tools. */
.doc-tool-main {
    padding: 12px 14px 10px;
    gap: 0;
}

.doc-tool-toolbar {
    flex: 0 0 auto;
    min-height: 0;
    justify-content: space-between;
    padding: 0 0 8px;
    margin: 0 0 8px;
    border-bottom: 1px solid var(--border);
}

.doc-tool-toolbar-title {
    min-width: 0;
    display: grid;
    gap: 2px;
}

.doc-tool-toolbar-title h4 {
    margin: 0;
    color: var(--text-main);
    font-size: 1rem;
    line-height: 1.25;
}

.doc-tool-toolbar-title span {
    color: var(--text-muted);
    font-size: 0.74rem;
}

.doc-tool-table-wrap {
    flex: 1 1 auto;
    max-height: none;
    min-height: 0;
    margin: 0;
    scrollbar-gutter: stable;
}

.ocr-job-table,
.pdf-job-table {
    min-width: 1080px;
}

.doc-tool-table tbody td {
    height: 40px;
    padding-top: 4px;
    padding-bottom: 4px;
    vertical-align: middle;
}

.doc-tool-file-title {
    display: block;
    min-width: 0;
    overflow: hidden;
    color: var(--text-main);
    font-size: 0.78rem;
    font-weight: 800;
    line-height: 1.25;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.doc-tool-file-meta {
    display: block;
    min-width: 0;
    overflow: hidden;
    color: var(--text-muted);
    font-size: 0.68rem;
    font-weight: 600;
    line-height: 1.25;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.doc-tool-table .doc-tool-file-meta {
    display: none;
}

.doc-tool-row-actions {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
    gap: 4px;
    min-height: 24px;
}

.doc-tool-row-actions .doc-tool-row-action {
    display: inline-flex;
    min-width: 0;
    height: 22px;
    min-height: 22px;
    align-items: center;
    justify-content: center;
    padding: 0 7px;
    border-radius: 6px;
    font-size: 0.66rem;
    font-weight: 800;
    line-height: 1;
    white-space: nowrap;
}

.doc-tool-row-actions .doc-tool-row-action:disabled {
    opacity: 0.48;
    cursor: not-allowed;
}

.doc-tool-detail-panel:not(.hidden) {
    position: fixed;
    inset: 0;
    z-index: 6200;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0;
    padding: 20px;
    border: 0;
    background: rgba(15, 23, 42, 0.42);
}

.workspace-modal.doc-tool-dialog {
    width: min(1120px, calc(100vw - 32px));
    height: min(760px, calc(100vh - 32px));
    max-height: calc(100vh - 32px);
    overflow: hidden;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: #fff;
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.22);
}

.workspace-modal.ocr-detail-dialog {
    width: min(1500px, calc(100vw - 28px));
    height: min(860px, calc(100vh - 28px));
}

.workspace-modal.pdf-detail-dialog {
    width: min(1040px, calc(100vw - 32px));
    height: min(620px, calc(100vh - 32px));
}

.doc-tool-modal-body.ocr-detail,
.doc-tool-modal-body.pdf-detail {
    flex: 1;
    min-height: 0;
    padding: 12px 14px 14px;
    overflow: hidden;
    background: #f8fafc;
}

.pdf-output-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    align-content: start;
    gap: 8px;
    overflow: auto;
}

.pdf-output-list .doc-tool-output-btn,
.ocr-output-strip .doc-tool-output-btn {
    justify-content: flex-start;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}
@media (max-width: 1180px) {
    .doc-tool-layout {
        grid-template-columns: 1fr;
        overflow: auto;
    }

    .doc-tool-sidebar,
    .doc-tool-main {
        height: auto;
        max-height: none;
    }

    .doc-tool-main {
        min-height: 620px;
    }

    .ocr-review-grid {
        grid-template-columns: 1fr;
    }

    .ocr-page-list {
        flex-direction: row;
        overflow-x: auto;
    }

    .ocr-page-pill {
        min-width: 118px;
    }
}

@media (max-width: 760px) {
    .doc-tool-layout {
        gap: 8px;
    }

    .doc-tool-field-row,
    .doc-tool-engine {
        grid-template-columns: 1fr;
    }

    .doc-tool-main-head,
    .ocr-detail-head,
    .pdf-detail-head {
        align-items: flex-start;
        flex-direction: column;
    }

    .doc-tool-head-actions,
    .ocr-detail-actions,
    .pdf-detail-actions {
        width: 100%;
    }

    .doc-tool-head-actions .btn-secondary,
    .ocr-detail-actions .btn-secondary,
    .pdf-detail-actions .btn-secondary {
        flex: 1 1 110px;
    }

    .doc-tool-table {
        min-width: 680px;
    }
}


/* === styles/workspaces/apps/pdf-tools.css === */
.pdf-tools-layout .doc-tool-sidebar {
    overflow: auto;
}

.pdf-detail {
    overflow: auto;
}

.pdf-output-list {
    align-content: flex-start;
    padding: 10px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: #fff;
}

.pdf-result-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(136px, 1fr));
    gap: 8px;
}

.pdf-result-grid div {
    min-height: 58px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 4px;
    padding: 9px 11px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 8px;
    background: rgba(248, 250, 252, 0.76);
}

.pdf-result-grid span {
    color: var(--text-muted);
    font-size: 0.72rem;
    font-weight: 800;
}

.pdf-result-grid strong {
    min-width: 0;
    overflow: hidden;
    color: var(--text-main);
    font-size: 0.92rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.pdf-tools-view [data-pdf-option].hidden {
    display: none;
}

@media (max-width: 760px) {
    .pdf-result-grid {
        grid-template-columns: 1fr;
    }
}



/* === styles/workspaces/knowledge.css === */
.knowledge-summary-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: nowrap;
    margin: 0 0 8px;
    width: 100%;
}

.knowledge-panel .rag-summary {
    display: inline-flex;
    align-items: center;
    flex: 0 0 auto;
    margin: 0;
}

.knowledge-workbench-state {
    display: none !important;
}

.knowledge-panel .rag-summary-items {
    display: inline-flex;
    align-items: center;
    flex-wrap: nowrap;
    gap: 7px;
}

.knowledge-panel .rag-summary-items span {
    min-height: 24px;
    padding: 3px 8px;
    border-radius: 6px;
    font-size: 0.7rem;
}


.knowledge-summary-primary {
    display: inline-flex;
    align-items: center;
    flex-wrap: nowrap;
    gap: 7px;
}

.knowledge-summary-group {
    display: inline-flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 4px;
    min-height: 28px;
    padding: 3px 5px 3px 8px;
    border: 1px solid var(--border);
    border-radius: 7px;
    background: var(--bg-secondary, rgba(248, 250, 252, 0.72));
}

.knowledge-summary-group-label {
    display: inline;
    min-height: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
    margin-right: 2px;
    color: var(--text-muted);
    font-size: 0.68rem;
    font-weight: 700;
}

.knowledge-toolbar {
    flex: 0 0 auto;
    justify-content: space-between;
    align-items: center;
    gap: 10px;
    padding-bottom: 8px;
    border-bottom: 1px solid var(--border);
    margin-bottom: 8px;
}

.knowledge-toolbar-filters,
.knowledge-toolbar-actions {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
}

.knowledge-toolbar-filters {
    flex: 1 1 320px;
}

.knowledge-toolbar-actions {
    justify-content: flex-end;
}

.knowledge-toolbar-actions > button,
.knowledge-action-menu > summary {
    min-height: 30px;
    margin: 0;
    padding: 0 10px;
    white-space: nowrap;
}

.knowledge-action-menu {
    position: relative;
}

.knowledge-action-menu > summary {
    display: inline-flex;
    align-items: center;
    list-style: none;
    cursor: pointer;
}

.knowledge-action-menu > summary::-webkit-details-marker { display: none; }

.knowledge-action-menu-panel {
    position: absolute;
    z-index: 20;
    top: calc(100% + 5px);
    right: 0;
    display: grid;
    min-width: 138px;
    gap: 3px;
    padding: 5px;
    border: 1px solid var(--border);
    border-radius: 7px;
    background: var(--bg-primary, #fff);
    box-shadow: 0 8px 22px rgba(15, 23, 42, 0.14);
}

.knowledge-action-menu-panel .btn-secondary {
    width: 100%;
    min-height: 28px;
    justify-content: flex-start;
    margin: 0;
    padding: 0 9px;
    border: 0;
    border-radius: 5px;
    background: transparent;
    text-align: left;
    white-space: nowrap;
}

.knowledge-action-menu-panel .btn-secondary:hover,
.knowledge-action-menu-panel .btn-secondary:focus-visible {
    background: rgba(16, 163, 127, 0.08);
    outline: none;
}

.knowledge-collection-filter,
.knowledge-tag-filter,
.knowledge-upload-collection {
    height: 30px;
    margin: 0;
    border-radius: 6px;
    font-size: 0.76rem;
}

.knowledge-collection-filter {
    width: 150px;
}

.knowledge-tag-filter {
    width: 130px;
}

.knowledge-upload-meta {
    display: grid;
    grid-template-columns: minmax(180px, 0.42fr) minmax(0, 1fr);
    gap: 14px;
    align-items: start;
    margin: 4px 0 6px;
}

.knowledge-upload-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
}

.knowledge-upload-field-label {
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--text-main);
}

.knowledge-upload-zone {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    gap: 12px;
    width: 100%;
    min-height: 170px;
    margin: 14px 0 0;
    padding: 24px;
    border: 1px dashed rgba(16, 163, 127, 0.32);
    border-radius: 8px;
    color: inherit;
    background: rgba(16, 163, 127, 0.035);
    cursor: pointer;
    text-align: center;
}

.knowledge-upload-zone:hover,
.knowledge-upload-zone:focus-visible,
.knowledge-upload-zone.is-dragging {
    border-color: rgba(16, 163, 127, 0.58);
    background: rgba(16, 163, 127, 0.08);
    outline: none;
}

.knowledge-upload-zone strong {
    color: var(--text-main);
    font-size: 0.92rem;
}

.knowledge-upload-zone span {
    color: var(--text-muted);
    font-size: 0.76rem;
    line-height: 1.45;
}

.knowledge-upload-modal {
    width: min(820px, calc(100vw - 28px));
    max-height: min(680px, calc(100vh - 28px));
    overflow-y: auto;
}

.knowledge-upload-zone {
    min-height: 150px;
}

/* 待上传文件列表 */
.knowledge-upload-list {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-top: 12px;
    max-height: 230px;
    overflow-y: auto;
    padding-right: 2px;
}

.knowledge-upload-item {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px 10px;
    padding: 8px 10px;
    border: 1px solid rgba(16, 163, 127, 0.18);
    border-radius: 8px;
    background: rgba(16, 163, 127, 0.04);
}

.knowledge-upload-item[data-status="error"] {
    border-color: rgba(239, 68, 68, 0.32);
    background: rgba(239, 68, 68, 0.04);
}

.knowledge-upload-item-name {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--text-main);
    font-size: 0.84rem;
}

/* 状态徽标：待上传 / 上传中 N% / 已加入索引 / 失败 */
.knowledge-upload-item-badge {
    flex: 0 0 auto;
    padding: 1px 9px;
    border-radius: 10px;
    font-size: 0.7rem;
    line-height: 1.6;
    white-space: nowrap;
    background: rgba(0, 0, 0, 0.06);
    color: var(--text-muted);
}

.knowledge-upload-item-badge.is-uploading {
    background: rgba(16, 163, 127, 0.12);
    color: #10a37f;
}

.knowledge-upload-item-badge.is-success {
    background: rgba(16, 163, 127, 0.18);
    color: #0f9d77;
}

.knowledge-upload-item-badge.is-error {
    background: rgba(239, 68, 68, 0.12);
    color: #ef4444;
}

/* 进度条：随上传字节进度填充，失败项变红 */
.knowledge-upload-item-bar {
    flex: 1 1 100%;
    height: 3px;
    border-radius: 2px;
    overflow: hidden;
    background: rgba(16, 163, 127, 0.14);
}

.knowledge-upload-item-bar-fill {
    width: 0;
    height: 100%;
    background: #10a37f;
    transition: width 0.15s ease;
}

.knowledge-upload-item[data-status="error"] .knowledge-upload-item-bar-fill {
    background: #ef4444;
}

.knowledge-upload-item-size {
    flex: 0 0 auto;
    color: var(--text-muted);
    font-size: 0.74rem;
}

.knowledge-upload-item-remove {
    flex: 0 0 auto;
    width: 22px;
    height: 22px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: none;
    border-radius: 50%;
    background: rgba(239, 68, 68, 0.1);
    color: #ef4444;
    font-size: 1rem;
    line-height: 1;
    cursor: pointer;
}

.knowledge-upload-item-remove:hover {
    background: rgba(239, 68, 68, 0.18);
}

/* 底部：摘要 + 操作按钮 */
.knowledge-upload-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-top: 14px;
    padding-top: 12px;
    border-top: 1px solid var(--border-color, rgba(0, 0, 0, 0.08));
}

.knowledge-upload-summary {
    flex: 1 1 auto;
    min-width: 0;
    color: var(--text-muted);
    font-size: 0.8rem;
}

.knowledge-upload-summary.is-over-limit {
    color: #ef4444;
    font-weight: 600;
}

.knowledge-upload-actions {
    flex: 0 0 auto;
    display: flex;
    gap: 8px;
}

.knowledge-doc-meta-modal {
    width: min(520px, calc(100vw - 28px));
}

.knowledge-doc-meta-modal .model-form {
    gap: 14px;
}

.knowledge-panel #rag-quality-report {
    display: inline-flex;
    flex-direction: row;
    flex-wrap: nowrap;
    align-items: center;
    gap: 8px;
    margin: 0;
    margin-left: auto;
    padding: 3px 10px;
    min-height: 28px;
    border-radius: 7px;
    border: 1px solid rgba(245, 158, 11, 0.25);
    background: rgba(245, 158, 11, 0.08);
    box-shadow: none;
    font-size: 0.72rem;
    flex: 0 1 auto;
    white-space: nowrap;
}

.knowledge-panel #rag-quality-report:empty {
    display: none !important;
}

.knowledge-panel #rag-quality-report .governance-head {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    flex: 0 0 auto;
}

.knowledge-panel #rag-quality-report .governance-head strong {
    color: #b45309;
    font-size: 0.74rem;
    white-space: nowrap;
}

.knowledge-panel #rag-quality-report .governance-head span {
    color: var(--text-muted);
    font-size: 0.7rem;
    font-weight: 500;
    white-space: nowrap;
}

.knowledge-panel #rag-quality-report .governance-metrics {
    display: inline-flex;
    align-items: center;
    flex: 0 0 auto;
    gap: 4px;
}

.knowledge-panel #rag-quality-report .governance-metrics span,
.knowledge-panel #rag-quality-report .governance-list span {
    display: inline-flex;
    align-items: center;
    min-height: 20px;
    padding: 1px 6px;
    border-radius: 5px;
    font-size: 0.68rem;
    white-space: nowrap;
}

.knowledge-panel #rag-quality-report .governance-list {
    display: inline-flex;
    align-items: center;
    flex: 0 1 auto;
    gap: 4px;
}

.knowledge-panel #rag-quality-report .governance-note {
    display: inline-flex;
    align-items: center;
    color: var(--text-muted);
    font-size: 0.7rem;
    white-space: nowrap;
}

.rag-debug-helper {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
    margin-top: 10px;
    color: var(--text-muted);
    font-size: 0.72rem;
}

.rag-debug-helper strong {
    color: var(--text-main);
    font-size: 0.74rem;
}

.rag-debug-sample {
    min-height: 24px;
    margin: 0;
    padding: 0 8px;
    border: 1px solid rgba(16, 163, 127, 0.2);
    border-radius: 6px;
    color: var(--primary);
    background: var(--bg-primary, #ffffff);
    cursor: pointer;
    font-size: 0.68rem;
    font-weight: 700;
}

.rag-debug-sample:hover,
.rag-debug-sample:focus-visible {
    border-color: rgba(16, 163, 127, 0.42);
    background: rgba(16, 163, 127, 0.08);
    outline: none;
}

.rag-debug-helper small {
    flex-basis: 100%;
    color: var(--text-muted);
    font-size: 0.7rem;
    line-height: 1.4;
}

.rag-debug-verdict {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 9px 10px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.16);
    background: var(--bg-secondary, #f8fafc);
}

.rag-debug-verdict strong,
.rag-debug-verdict span {
    display: block;
}

.rag-debug-verdict strong {
    color: var(--text-main);
    font-size: 0.82rem;
}

.rag-debug-verdict span {
    margin-top: 2px;
    color: var(--text-muted);
    font-size: 0.72rem;
    line-height: 1.4;
}

.rag-debug-verdict.is-ready {
    background: rgba(34, 197, 94, 0.1);
}

.rag-debug-verdict.is-warning {
    background: rgba(245, 158, 11, 0.1);
}

.rag-debug-verdict.is-empty {
    background: var(--bg-secondary, #f8fafc);
}

.rag-debug-verdict button {
    flex: 0 0 auto;
    min-height: 26px;
    padding: 0 9px;
    border: 1px solid rgba(16, 163, 127, 0.24);
    border-radius: 6px;
    color: var(--primary);
    background: var(--bg-primary, #ffffff);
    cursor: pointer;
    font-size: 0.7rem;
    font-weight: 800;
    white-space: nowrap;
}

.rag-debug-verdict button:hover,
.rag-debug-verdict button:focus-visible {
    border-color: rgba(16, 163, 127, 0.44);
    background: rgba(16, 163, 127, 0.08);
    outline: none;
}

.knowledge-panel .workspace-table-wrap {
    flex: 0 0 auto;
    margin-bottom: 10px;
}

.knowledge-panel .workspace-table-wrap+.workspace-pagination {
    margin-top: 0;
    padding-top: 10px;
}

.knowledge-panel .data-table {
    line-height: 1.15;
}

.knowledge-panel .data-table th,
.knowledge-panel .data-table td {
    height: 30px;
    min-height: 30px;
    padding: 3px 7px;
}

.knowledge-panel .data-table th {
    height: 32px;
}

.knowledge-collection-pill,
.knowledge-tag-pill,
.knowledge-empty-meta {
    display: inline-flex;
    max-width: 100%;
    min-height: 22px;
    align-items: center;
    border-radius: 6px;
    font-size: 0.7rem;
    line-height: 1.2;
    white-space: nowrap;
}

.knowledge-collection-pill {
    padding: 2px 7px;
    border: 1px solid rgba(16, 185, 129, 0.18);
    background: rgba(236, 253, 245, 0.78);
    color: var(--text-main);
    font-weight: 700;
}

.knowledge-collection-pill.is-muted,
.knowledge-empty-meta {
    border-color: rgba(148, 163, 184, 0.18);
    background: var(--bg-secondary, rgba(248, 250, 252, 0.82));
    color: var(--text-muted);
    font-weight: 600;
}

.knowledge-tag-list {
    display: flex;
    min-width: 0;
    max-width: 100%;
    flex-wrap: wrap;
    gap: 3px;
}

.knowledge-tag-pill {
    padding: 2px 6px;
    border: 1px solid rgba(59, 130, 246, 0.16);
    background: rgba(239, 246, 255, 0.78);
    color: var(--text-main);
    font-weight: 700;
}

.knowledge-tag-picker {
    display: flex;
    min-height: 40px;
    max-height: 138px;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 6px;
    padding: 8px;
    overflow: auto;
    border: 1.5px solid var(--border);
    border-radius: 8px;
    background: var(--bg-primary, #ffffff);
    text-align: left;
}

.knowledge-upload-meta .knowledge-tag-picker {
    min-height: 30px;
    max-height: 92px;
    padding: 5px 7px;
}

.knowledge-tag-check {
    display: inline-flex;
    max-width: 100%;
    min-height: 28px;
    align-items: center;
    gap: 6px;
    padding: 0 9px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 6px;
    background: var(--bg-secondary, #f8fafc);
    color: var(--text-main);
    cursor: pointer;
    font-size: 0.74rem;
    font-weight: 700;
    line-height: 1.2;
}

.knowledge-tag-check input {
    flex: 0 0 auto;
    width: 13px;
    height: 13px;
    margin: 0;
}

.knowledge-tag-check span {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.knowledge-tag-check:has(input:checked) {
    border-color: rgba(59, 130, 246, 0.34);
    background: rgba(59, 130, 246, 0.12);
    color: var(--text-main);
}

.knowledge-tag-picker-empty {
    display: flex;
    min-height: 24px;
    align-items: center;
    color: var(--text-muted);
    font-size: 0.74rem;
    font-weight: 600;
}

.knowledge-panel .rag-actions {
    height: 22px;
    gap: 4px;
}

.knowledge-panel .rag-actions .btn-secondary,
.knowledge-panel .rag-actions .btn-danger {
    height: 22px;
    min-height: 22px;
    padding: 0 7px;
    font-size: 0.66rem;
    line-height: 1;
    border-radius: 6px;
}

.knowledge-panel .status-badge {
    min-height: 20px;
    padding: 1px 7px;
    line-height: 18px;
}

.knowledge-panel input[type="checkbox"] {
    width: 12px;
    height: 12px;
}

@media (max-width: 760px) {
    .knowledge-toolbar {
        align-items: stretch;
        flex-direction: column;
    }

    .knowledge-toolbar-filters,
    .knowledge-toolbar-actions {
        width: 100%;
    }

    .knowledge-toolbar-actions {
        justify-content: flex-start;
    }

    .knowledge-action-menu-panel {
        left: 0;
        right: auto;
    }

    .knowledge-toolbar-filters select,
    .knowledge-toolbar-actions > button,
    .knowledge-action-menu > summary {
        min-height: 36px;
    }

    .knowledge-toolbar-filters select {
        flex: 1 1 0;
        width: auto;
    }

    .knowledge-toolbar-actions {
        gap: 8px;
    }

    .knowledge-toolbar-actions > button,
    .knowledge-action-menu {
        flex: 1 1 calc(50% - 8px);
    }

    .knowledge-action-menu > summary {
        justify-content: center;
    }
}


