/* === styles/workspaces/rag-graph-map.css === */
/* 拆自 rag-graph-styles.js：图谱地图与提示浮层样式。 */
.rag-graph-map {
        position: relative;
        width: 100%;
        height: calc(100% - 42px);
        min-height: 360px;
        overflow: hidden;
        cursor: grab;
        user-select: none;
        touch-action: none;
    }
    .rag-graph-map.is-panning {
        cursor: grabbing;
    }
    .rag-graph-map-stage {
        position: absolute;
        inset: 0;
        z-index: 1;
        transform-origin: 0 0;
        will-change: transform;
        transition: transform 120ms ease;
    }
    .rag-graph-map.is-panning .rag-graph-map-stage {
        transition: none;
    }
    .rag-graph-map-controls {
        position: absolute;
        top: 10px;
        right: 10px;
        z-index: 8;
        display: flex;
        align-items: center;
        gap: 4px;
        padding: 4px;
        border: 1px solid rgba(148, 163, 184, 0.22);
        border-radius: 8px;
        background: rgba(255, 255, 255, 0.92);
        box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
        backdrop-filter: blur(8px);
        cursor: default;
    }
    .rag-graph-map-controls button {
        width: 28px;
        height: 28px;
        min-height: 28px;
        padding: 0;
        border-radius: 7px;
        font-size: 0.78rem;
        font-weight: 900;
        line-height: 1;
    }
    .rag-graph-map-controls button[data-graph-zoom-action="reset"] {
        width: 38px;
        font-size: 0.68rem;
    }
    .rag-graph-map-controls button:disabled {
        opacity: 0.46;
        cursor: not-allowed;
    }
    #rag-graph-zoom-value {
        width: 42px;
        color: #475569;
        font-size: 0.68rem;
        font-weight: 900;
        text-align: center;
        font-variant-numeric: tabular-nums;
    }
    .rag-graph-svg {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        pointer-events: none;
    }
    .rag-graph-svg marker path {
        fill: #64748b;
    }
    .rag-graph-link {
        fill: none;
        stroke: #64748b;
        stroke-width: 0.55;
        opacity: 0.72;
        vector-effect: non-scaling-stroke;
    }
    .rag-graph-link.is-owner { stroke: #059669; }
    .rag-graph-link.is-belong { stroke: #2563eb; }
    .rag-graph-link.is-depend { stroke: #7c3aed; }
