    }
    .rag-graph-node-tooltip strong {
        color: #fff;
        font-size: 0.78rem;
        line-height: 1.35;
    }
    .rag-graph-node-tooltip span {
        color: rgba(226, 232, 240, 0.9);
        white-space: pre-wrap;
    }
    .rag-graph-map-footer {
        position: absolute;
        left: 12px;
        right: 12px;
        bottom: 10px;
        z-index: 5;
        display: flex;
        justify-content: space-between;
        gap: 10px;
        padding: 7px 10px;
        border: 1px solid rgba(148, 163, 184, 0.2);
        border-radius: 8px;
        background: rgba(255, 255, 255, 0.88);
        color: #64748b;
        font-size: 0.7rem;
        font-weight: 700;
        backdrop-filter: blur(8px);
    }
    .rag-graph-summary span {
        background: #fff;
    }
    .rag-graph-summary span small {
        color: var(--text-muted);
        font-size: 0.7rem;
        font-weight: 800;
    }
    .rag-graph-summary-main b {
        font-size: 0.86rem;
    }
    .rag-graph-entity {
        border-radius: 8px;
        box-sizing: border-box;
        min-width: 0;
        overflow: hidden;
        transition: border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease;
    }
    .rag-graph-entity > span {
        min-width: 0;
        flex: 1 1 calc(100% - 90px);
    }
    .rag-graph-entity-list,
    .rag-graph-relation-list {
        overflow-x: hidden;
    }
    .rag-graph-entity.active {
        border-color: rgba(16, 185, 129, 0.55);
        background: #ecfdf5;
        box-shadow: inset 3px 0 0 rgba(16, 185, 129, 0.78);
    }
    .rag-graph-entity small b {
        color: #047857;
        font-weight: 900;
    }
    .rag-graph-entity em {
        flex: 0 0 82px;
        width: 82px;
        padding: 2px 7px;
        border-radius: 999px;
        background: rgba(148, 163, 184, 0.1);
        color: #475569;
        font-size: 0.66rem;
        font-weight: 800;
        text-align: center;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: clip;
    }
    .rag-graph-relation {
