    }
    .rag-graph-relation.is-owner { border-left: 2px solid #059669; }
    .rag-graph-relation.is-belong { border-left: 2px solid #2563eb; }
    .rag-graph-relation.is-depend { border-left: 2px solid #7c3aed; }
    .rag-graph-relation.is-contain { border-left: 2px solid #0f766e; }
    .rag-graph-relation.is-affect { border-left: 2px solid #dc2626; }
    .rag-graph-relation.is-pending {
        border-color: rgba(245, 158, 11, 0.45);
        background: #fffbeb;
    }
    .rag-graph-relation.is-pending header strong b {
        background: rgba(245, 158, 11, 0.12);
        color: #b45309;
    }
    .rag-graph-relation header {
        align-items: center;
        gap: 6px;
        font-size: 0.75rem;
        line-height: 1.2;
    }
    .rag-graph-relation header strong {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
        align-items: center;
        gap: 5px;
        min-width: 0;
        flex: 1 1 auto;
    }
    .rag-graph-relation header strong span {
        min-width: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }
    .rag-graph-relation header strong b {
        padding: 2px 6px;
        border-radius: 999px;
        background: rgba(16, 185, 129, 0.08);
        color: #047857;
        font-size: 0.64rem;
        line-height: 1;
        white-space: nowrap;
    }
    .rag-graph-relation-foot {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: center;
        gap: 6px;
        margin-top: 4px;
    }
    .rag-graph-relation-foot p {
        display: flex;
        align-items: center;
        gap: 8px;
        min-width: 0;
        margin: 0;
        color: var(--text-muted);
        font-size: 0.68rem;
        line-height: 1.2;
    }
    .rag-graph-relation-foot p span {
        min-width: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }
    .rag-graph-relation-foot p span:first-child {
        flex: 0 0 auto;
        max-width: 108px;
    }
    .rag-graph-relation .rag-graph-actions {
        margin: 0;
        gap: 4px;
    }
    .rag-graph-relation .rag-graph-actions button {
        height: 22px;
        min-height: 22px;
        padding: 0 7px;
        font-size: 0.66rem;
        border-radius: 6px;
    }
    .rag-graph-source-snippet {
        margin: 5px 0 0;
        padding-top: 5px;
        border-top: 1px dashed rgba(148, 163, 184, 0.28);
        color: #64748b;
        font-size: 0.68rem;
        line-height: 1.4;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
        overflow: hidden;
        white-space: normal;
    }
    .rag-graph-confidence {
        flex: 0 0 auto;
        color: #64748b;
        font-size: 0.64rem;
        font-weight: 800;
        white-space: nowrap;
    }
    .rag-graph-editor {
        display: flex;
        flex-direction: column;
        gap: 8px;
    }
    .rag-graph-editor-head {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 12px;
        color: var(--text-main);
        font-size: 0.82rem;
    }
    .rag-graph-editor-head span {
        color: var(--text-muted);
        font-size: 0.72rem;
        font-weight: 800;
    }
    .rag-graph-editor-grid textarea.form-input {
        min-height: 54px;
        height: auto;
        padding: 8px 10px;
        resize: vertical;
        line-height: 1.35;
    }
    .rag-graph-editor-grid input[readonly] {
        color: var(--text-muted);
        background: #f8fafc;
    }
    @media (max-width: 1200px) {
        .rag-graph-layout {
            grid-template-columns: minmax(240px, 0.9fr) minmax(420px, 1.3fr) minmax(280px, 1fr);
        }
    }
    @media (max-width: 720px) {
        .rag-detail-modal { width: calc(100vw - 20px); max-height: calc(100vh - 20px); padding: 16px; }
        .rag-detail-header { align-items: stretch; flex-direction: column; }
        .rag-detail-header h3 { max-width: 100%; white-space: normal; }
        .rag-graph-modal { width: 100vw; height: 100vh; padding: 14px; border-radius: 0; }
        .rag-graph-editor-modal { width: calc(100vw - 20px); max-height: calc(100vh - 20px); border-radius: 8px; }
        .rag-graph-editor-modal-head { padding: 14px; }
        .rag-graph-editor-modal-body { padding: 14px; }
        .rag-graph-topbar { align-items: stretch; padding: 10px 14px 12px; }
        .rag-graph-topbar,
        .rag-graph-summary,
        .rag-graph-toolbar { width: 100%; }
        .rag-graph-toolbar,
        .rag-graph-topbar,
        .rag-graph-layout,
        .rag-graph-editor-grid { grid-template-columns: 1fr; }
        .rag-graph-query-panel,
        .rag-graph-filter-row,
        .rag-graph-path {
            grid-template-columns: 1fr;
        }
        .rag-graph-query-panel {
            padding: 0 14px 10px;
        }
        .rag-graph-query-results {
            max-height: 210px;
        }
        .rag-graph-path b {
            justify-self: start;
        }
        .rag-graph-layout { overflow: auto; }
        .rag-graph-panel { min-height: 280px; }
    }


/* === styles/workspaces/mcp/mcp-forms.css === */
/* 拆自 workspaces/mcp.css。 */
/* MCP 分页、表单、编辑弹窗与空服务面板样式。 */
.workspace-pagination {
    flex: 0 0 auto;
    margin-top: 10px;
    padding-top: 10px;
}

.mcp-form {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 16px;
    border-radius: 10px;
}

.mcp-form .form-input {
    margin: 0;
    height: 36px;
    padding: 6px 12px;
    font-size: 0.84rem;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 8px;
    background-color: #ffffff;
    color: var(--text-main);
    box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.02);
    transition: border-color 0.2s cubic-bezier(0.4, 0, 0.2, 1),
                box-shadow 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.mcp-form .form-input:focus {
    outline: none;
    border-color: var(--primary);
    box-shadow: 0 0 0 3px rgba(16, 163, 127, 0.12), inset 0 1px 2px rgba(15, 23, 42, 0.02);
}

.mcp-field-group {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.mcp-form-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 10px;
}

.mcp-form textarea {
    min-height: 84px;
    resize: vertical;
}

.mcp-edit-modal {
    width: min(720px, calc(100vw - 32px));
    max-height: calc(100vh - 32px);
    padding: 0;
    overflow: hidden;
    text-align: left;
    background: #ffffff;
    border-radius: 14px;
    box-shadow: 0 20px 25px -5px rgba(15, 23, 42, 0.08), 0 10px 10px -5px rgba(15, 23, 42, 0.03);
}

.mcp-edit-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 16px 20px 14px;
    border-bottom: 1px solid var(--border);
    background: #ffffff;
}

.mcp-edit-header h3 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 800;
    color: var(--text-main);
}

.mcp-edit-form {
    display: flex;
    flex-direction: column;
    gap: 10px;
    max-height: calc(100vh - 110px);
    padding: 16px 20px 20px;
    overflow: auto;
}

.mcp-edit-form .form-input {
    margin: 0;
    height: 36px;
    padding: 6px 12px;
    font-size: 0.84rem;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 8px;
    background-color: #ffffff;
    color: var(--text-main);
    box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.02);
    transition: border-color 0.2s cubic-bezier(0.4, 0, 0.2, 1),
                box-shadow 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.mcp-edit-form .form-input:focus {
    outline: none;
    border-color: var(--primary);
    box-shadow: 0 0 0 3px rgba(16, 163, 127, 0.12), inset 0 1px 2px rgba(15, 23, 42, 0.02);
}

.mcp-edit-form textarea {
    min-height: 80px;
    resize: vertical;
}

.mcp-config-helper {
    display: grid;
    gap: 8px;
    padding: 12px 14px;
    border: 1px solid rgba(16, 163, 127, 0.16);
    border-radius: 10px;
    background: #f8fdfa;
}

.mcp-config-helper:empty {
    display: none;
}

.mcp-config-helper strong {
    color: var(--text-main);
    font-size: 0.84rem;
    font-weight: 800;
}

.mcp-config-helper div {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.mcp-config-helper span {
    padding: 4px 8px;
    border: 1px solid rgba(16, 163, 127, 0.18);
    border-radius: 6px;
    color: var(--primary);
    background: #ffffff;
    font-size: 0.7rem;
    font-weight: 700;
}

.mcp-config-helper small {
    color: var(--text-muted);
    font-size: 0.74rem;
    line-height: 1.45;
}

.mcp-edit-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    margin-top: 6px;
    padding-top: 12px;
    border-top: 1px solid var(--border);
}

.mcp-edit-actions .btn-primary,
.mcp-edit-actions .btn-secondary {
    height: 34px;
    padding: 0 16px;
    font-size: 0.82rem;
    font-weight: 700;
    border-radius: 8px;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.mcp-shared-row {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: var(--text-muted);
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
}

.mcp-db-field-group {
    gap: 7px;
}

.mcp-db-inline-option {
    min-height: 26px;
}

.mcp-db-advanced {
    border: 1px solid var(--border);
    border-radius: 8px;
    background: #ffffff;
    overflow: hidden;
}

.mcp-db-advanced summary {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 36px;
    padding: 0 10px;
    color: var(--text-main);
    cursor: pointer;
    font-size: 0.78rem;
    font-weight: 800;
    list-style: none;
}

.mcp-db-advanced summary::-webkit-details-marker {
    display: none;
}

.mcp-db-advanced summary::after {
    content: "+";
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    width: 20px;
    height: 20px;
    border: 1px solid rgba(148, 163, 184, 0.3);
    border-radius: 999px;
    color: var(--text-muted);
    font-size: 0.8rem;
    line-height: 1;
}

.mcp-db-advanced[open] summary::after {
    content: "-";
}

.mcp-db-advanced summary small {
    min-width: 0;
    color: var(--text-muted);
    font-size: 0.7rem;
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-db-advanced-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
    padding: 8px;
    border-top: 1px solid var(--border);
    background: #fbfdff;
}

.mcp-db-advanced-grid textarea {
    min-height: 64px;
}

.mcp-db-advanced-grid textarea:nth-of-type(3),
.mcp-db-advanced-grid .mcp-form-row,
.mcp-db-advanced-grid .mcp-shared-row {
    grid-column: 1 / -1;
}

.mcp-inline-check {
    min-height: 34px;
    padding: 0 10px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: #ffffff;
}

.mcp-diagnostics-panel {
    display: none;
    min-height: 34px;
    padding: 8px 10px;
    border: 1px solid rgba(59, 130, 246, 0.2);
    border-radius: 8px;
    color: var(--text-muted);
    background: #eff6ff;
    font-size: 0.74rem;
    line-height: 1.45;
    white-space: pre-wrap;
}

.mcp-diagnostics-panel:not(:empty) {
    display: block;
}

.mcp-server-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.mcp-empty-panel {
    display: flex;
    flex-direction: column;
    gap: 8px;
    border: 1px dashed var(--border);
    border-radius: 8px;
    padding: 12px;
    background: #f8fafc;
    color: var(--text-muted);
    font-size: 0.78rem;
}

.mcp-empty-panel strong {
    color: var(--text-main);
    font-size: 0.88rem;
}

.mcp-empty-panel span {
    line-height: 1.45;
}

.mcp-empty-panel.compact {
    margin-top: 8px;
}

.mcp-server-card {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 14px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 10px;
    padding: 10px 14px;
    background: #ffffff;
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.015);
    transition: transform 0.22s cubic-bezier(0.4, 0, 0.2, 1),
                box-shadow 0.22s cubic-bezier(0.4, 0, 0.2, 1),
                border-color 0.22s ease;
}

.mcp-server-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 16px -4px rgba(15, 23, 42, 0.06), 0 2px 6px -1px rgba(15, 23, 42, 0.02);
    border-color: rgba(16, 163, 127, 0.3);
}

.mcp-list-head,
.mcp-system-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    color: var(--text-main);
}

.mcp-list-head {
    padding-top: 2px;
}

.mcp-list-head strong,
.mcp-system-head strong {
    display: block;
    font-size: 0.8rem;
}

.mcp-list-head span,
.mcp-system-head span {
    display: block;
    margin-top: 1px;
    color: var(--text-muted);
    font-size: 0.68rem;
    line-height: 1.25;
}

.mcp-list-head > span {
    display: inline-flex;
    align-items: center;
    height: 20px;
    margin-top: 0;
    padding: 0 7px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 999px;
    font-weight: 700;
    white-space: nowrap;
}
.mcp-form-tip {
    padding: 7px 9px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: #f8fafc;
    color: var(--text-muted);
    font-size: 0.72rem;
    line-height: 1.45;
}


/* === styles/workspaces/mcp/mcp-system-cards.css === */
/* Extracted from workspaces/mcp.css. */
/* MCP system service, connector, instance card and action styles. */
.mcp-system-services {
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding-bottom: 0;
}

.mcp-home-section {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.mcp-system-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(360px, 1fr));
    align-items: stretch;
    gap: 6px;
}

.mcp-system-card {
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    gap: 5px;
    min-width: 0;
    min-height: 70px;
    padding: 6px 10px;
    border: 1px solid rgba(148, 163, 184, 0.15);
    border-radius: 12px;
    background: linear-gradient(180deg, #ffffff 0%, #fbfdfe 100%);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.015), 0 1px 2px rgba(15, 23, 42, 0.005);
    transition: transform 0.22s cubic-bezier(0.4, 0, 0.2, 1),
                box-shadow 0.22s cubic-bezier(0.4, 0, 0.2, 1),
                border-color 0.22s ease,
                background 0.22s ease;
}

.mcp-system-card:hover {
    transform: translateY(-2px);
    border-color: rgba(16, 163, 127, 0.32);
    box-shadow: 0 10px 20px -4px rgba(15, 23, 42, 0.04), 0 4px 8px -2px rgba(15, 23, 42, 0.02);
}

.mcp-system-card.is-enabled {
    border-color: rgba(16, 163, 127, 0.28);
    background: linear-gradient(180deg, #ffffff 0%, #f6fdfa 100%);
    box-shadow: 0 4px 10px rgba(16, 163, 127, 0.01);
}

.mcp-system-card.is-enabled:hover {
    border-color: var(--primary);
    box-shadow: 0 12px 24px -4px rgba(16, 163, 127, 0.08), 0 4px 10px -2px rgba(16, 163, 127, 0.02);
}

.mcp-connector-card {
    background: #ffffff;
    border-style: dashed;
    border-color: rgba(148, 163, 184, 0.25);
}
.mcp-connector-card:hover {
    border-style: solid;
    border-color: rgba(16, 163, 127, 0.35);
}

.mcp-system-card.is-paused,
.mcp-server-card.is-paused {
    border-color: rgba(148, 163, 184, 0.2);
    border-style: solid;
    background: #f8fafc;
    opacity: 0.68;
    box-shadow: none !important;
    transform: none !important;
}

.mcp-system-card-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    min-width: 0;
}

.mcp-system-card-head strong {
    min-width: 0;
    overflow: hidden;
    color: var(--text-main);
    font-size: 0.82rem;
    font-weight: 700;
    line-height: 1.3;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-system-card-head em {
    flex: 0 0 auto;
    display: inline-flex;
    align-items: center;
    gap: 3px;
    max-width: 120px;
    height: 18px;
    padding: 0 7px;
    overflow: hidden;
    border: 1px solid rgba(16, 163, 127, 0.2);
    border-radius: 999px;
    background: #ffffff;
    color: var(--primary);
    font-size: 0.64rem;
    font-style: normal;
    font-weight: 700;
    line-height: 16px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-system-card.is-enabled .mcp-system-card-head em {
    border-color: rgba(16, 163, 127, 0.18);
    background: #ecfdf5;
    color: var(--primary);
}

.mcp-system-card.is-enabled .mcp-system-card-head em::before {
    content: '';
    display: inline-block;
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background-color: var(--primary);
    animation: mcp-pulse 2s infinite;
}

.mcp-system-card.is-paused .mcp-system-card-head em {
    border-color: rgba(148, 163, 184, 0.2);
    background: #f1f5f9;
    color: #64748b;
}

.mcp-status-toggle {
    flex: 0 0 auto;
    position: relative;
    width: 36px;
    height: 20px;
    padding: 0;
    border: 1px solid rgba(148, 163, 184, 0.3);
    border-radius: 999px;
    background: #e2e8f0;
    cursor: pointer;
    box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.05);
    transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.mcp-status-toggle span {
    position: absolute;
    top: 2px;
    left: 2px;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: #ffffff;
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.18);
    transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.mcp-status-toggle.is-on {
    border-color: rgba(16, 163, 127, 0.35);
    background: var(--primary);
}

.mcp-status-toggle.is-on span {
    transform: translateX(16px);
    box-shadow: 0 2px 4px rgba(6, 95, 70, 0.22);
}

.mcp-status-toggle:hover {
    border-color: rgba(16, 163, 127, 0.4);
    box-shadow: inset 0 1px 2px rgba(15, 23, 42, 0.05), 0 0 0 2px rgba(16, 163, 127, 0.08);
}

.mcp-system-card p {
    display: -webkit-box;
    margin: 0;
    overflow: hidden;
    color: #64748b;
    font-size: 0.68rem;
    line-height: 1.25;
    line-clamp: 2;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
}

.mcp-instance-card {
    min-height: 70px;
    border-color: rgba(16, 163, 127, 0.2);
    background: linear-gradient(180deg, #ffffff 0%, #fbfefd 100%);
}

.mcp-instance-head {
    align-items: flex-start;
}

.mcp-instance-title {
    display: grid;
    gap: 4px;
    min-width: 0;
}

.mcp-instance-title > span {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 4px;
    min-width: 0;
}

.mcp-instance-title strong {
    font-size: 0.82rem;
}

.mcp-instance-title em {
    justify-self: start;
    max-width: 100%;
    height: 18px;
    padding: 0 6px;
    overflow: hidden;
    border: 1px solid rgba(16, 163, 127, 0.2);
    border-radius: 5px;
    background: #ecfdf5;
    color: var(--primary);
    font-size: 0.64rem;
    font-style: normal;
    font-weight: 700;
    line-height: 16px;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-instance-title .mcp-owner-badge {
    border-color: rgba(100, 116, 139, 0.18);
    background: #f8fafc;
    color: #475569;
}

.mcp-system-card.is-enabled .mcp-instance-title .mcp-owner-badge::before {
    content: none;
}

.mcp-card-tags {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 3px 5px;
    min-width: 0;
    margin: 2px 0;
}

.mcp-card-tags .mcp-tag {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    padding: 1px 5px;
    border-radius: 5px;
    border: 1px solid rgba(148, 163, 184, 0.15);
    background-color: #f8fafc;
    color: #475569;
    font-size: 0.64rem;
    font-weight: 600;
    line-height: 1.2;
    white-space: nowrap;
}

.mcp-card-tags .mcp-tag b {
    color: #94a3b8;
    font-weight: 700;
}

/* Only apply soft custom colors to risk classes to prevent too many colors */
.mcp-tag-risk-low {
    background-color: #f0fdf4 !important;
    border-color: rgba(34, 197, 94, 0.15) !important;
    color: #15803d !important;
}

.mcp-tag-risk-medium {
    background-color: #fff7ed !important;
    border-color: rgba(194, 65, 12, 0.15) !important;
    color: #b45309 !important;
}

.mcp-tag-risk-high {
    background-color: #fef2f2 !important;
    border-color: rgba(185, 28, 28, 0.15) !important;
    color: #b91c1c !important;
}

.mcp-card-meta {
    display: -webkit-box;
    max-width: 100%;
    min-height: 0;
    margin: 0;
    padding: 0;
    overflow: hidden;
    border: 0;
    background: transparent;
    color: #64748b;
    font-size: 0.68rem;
    font-weight: 600;
    line-height: 1.3;
    line-clamp: 2;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    transition: color 0.2s ease;
}

.mcp-system-card:hover .mcp-card-meta {
    background: transparent;
    border-color: transparent;
    color: #334155;
}

.mcp-system-actions,
.mcp-card-actions,
.mcp-instance-actions {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
    min-width: 0;
}

.mcp-system-actions {
    margin-top: auto;
}

.mcp-card-actions {
    justify-content: flex-end;
}

.mcp-system-actions .btn-secondary,
.mcp-system-actions .btn-danger-outline,
.mcp-card-actions .btn-secondary,
.mcp-card-actions .btn-danger-outline {
    flex: 0 0 auto;
    height: 24px;
    padding: 0 9px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 7px;
    background: #ffffff;
    color: #475569;
    font-size: 0.68rem;
    font-weight: 700;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.01);
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.mcp-system-actions .btn-secondary:hover,
.mcp-card-actions .btn-secondary:hover {
    border-color: var(--primary);
    background: #ecfdf5;
    color: var(--primary);
    box-shadow: 0 4px 10px rgba(16, 163, 127, 0.06);
}

.mcp-system-actions .btn-danger-outline,
.mcp-card-actions .btn-danger-outline {
    border-color: rgba(239, 68, 68, 0.22);
    color: var(--danger);
}

.mcp-system-actions .btn-danger-outline:hover,
.mcp-card-actions .btn-danger-outline:hover {
    border-color: var(--danger);
    background: #fef2f2;
    box-shadow: 0 4px 10px rgba(239, 68, 68, 0.06);
}

.mcp-server-main {
    display: grid;
    grid-template-columns: minmax(200px, 1fr) minmax(240px, auto);
    align-items: center;
    gap: 20px;
    min-width: 0;
}

.mcp-server-summary {
    min-width: 0;
}

.mcp-server-card strong,
.mcp-server-card span,
.mcp-server-card small {
    display: block;
}

.mcp-server-card strong em,
.mcp-server-card strong i {
    display: inline-flex;
    align-items: center;
    height: 18px;
    margin-left: 6px;
    padding: 0 6px;
    border-radius: 5px;
    font-size: 0.62rem;
    font-style: normal;
    font-weight: 600;
    line-height: 1;
    vertical-align: middle;
}

.mcp-server-card strong em {
    border: 1px solid rgba(16, 163, 127, 0.2);
    background: #ecfdf5;
    color: var(--primary);
}

.mcp-server-card strong i {
    border: 1px solid rgba(148, 163, 184, 0.25);
    background: #f1f5f9;
    color: #64748b;
}

.mcp-server-card span {
    margin-top: 4px;
    color: #475569;
    font-size: 0.74rem;
    line-height: 1.45;
    word-break: break-all;
}

.mcp-server-card small {
    margin-top: 4px;
    color: #64748b;
    font-size: 0.68rem;
    line-height: 1.3;
}

.mcp-server-card small.error-text {
    display: inline-block;
    margin-top: 6px;
    padding: 2px 6px;
    border: 1px solid rgba(239, 68, 68, 0.15);
    border-radius: 4px;
    background-color: #fef2f2;
    color: var(--danger) !important;
}

.mcp-source-action-zone {
    display: grid;
    grid-template-columns: minmax(200px, 1fr) minmax(360px, 1fr);
    align-items: stretch;
    gap: 8px;
    min-width: 0;
}

.mcp-source-action-panel,
.mcp-data-management-panel {
    min-width: 0;
    min-height: 58px;
    padding: 6px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: #f8fafc;
}

.mcp-source-action-panel {
    display: grid;
    grid-template-columns: 120px minmax(0, 1fr);
    align-items: center;
    gap: 6px;
}

.mcp-source-action-head,
.mcp-data-management-head {
    display: grid;
    gap: 2px;
    min-width: 0;
    padding: 0 8px 0 2px;
    border-right: 1px solid rgba(148, 163, 184, 0.16);
}

.mcp-source-action-head strong,
.mcp-data-management-head strong {
    overflow: hidden;
    color: var(--text-main);
    font-size: 0.72rem;
    font-weight: 800;
    line-height: 1.18;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-source-action-head span,
.mcp-data-management-head span {
    display: -webkit-box;
    overflow: hidden;
    color: #64748b;
    font-size: 0.58rem;
    line-height: 1.18;
    line-clamp: 2;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
}

.mcp-source-action-list {
    display: flex;
    flex-direction: column;
    min-width: 0;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 7px;
    background: #ffffff;
    overflow: hidden;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.01);
}

.mcp-data-management-action {
    display: grid;
    align-items: center;
    gap: 6px;
    min-width: 0;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 7px;
    background: #ffffff;
    color: inherit;
    cursor: pointer;
    text-align: left;
    transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
}

.mcp-source-action {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 6px;
    min-width: 0;
    min-height: 38px;
    padding: 6px 10px;
    border: none;
    background: transparent;
    color: inherit;
    cursor: pointer;
    text-align: left;
    transition: background-color 0.2s ease;
}

.mcp-source-action:not(:last-child) {
    border-bottom: 1px solid rgba(148, 163, 184, 0.1);
}

.mcp-source-action:hover {
    background: #f0fdf4;
}

.mcp-data-management-action:hover {
    border-color: rgba(16, 163, 127, 0.3);
    background: #f0fdf4;
}

.mcp-data-management-action:hover {
    box-shadow: 0 4px 10px rgba(16, 163, 127, 0.08);
}

.mcp-source-action:focus-visible,
.mcp-data-management-action:focus-visible {
    outline: 2px solid rgba(16, 163, 127, 0.28);
    outline-offset: 2px;
}

.mcp-source-action-copy,
.mcp-data-management-action span {
    display: grid;
    gap: 2px;
    min-width: 0;
}

.mcp-source-action-copy strong,
.mcp-data-management-action strong {
    overflow: hidden;
    color: var(--text-main);
    font-size: 0.7rem;
    font-weight: 800;
    line-height: 1.14;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-source-action-copy span,
.mcp-source-action-copy small,
.mcp-data-management-action small {
    display: -webkit-box;
    overflow: hidden;
    line-clamp: 2;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
}

.mcp-source-action-copy span,
.mcp-data-management-action small {
    color: #475569;
    font-size: 0.58rem;
    line-height: 1.16;
}

.mcp-source-action-copy small {
    color: #94a3b8;
    font-size: 0.56rem;
    font-weight: 700;
    line-height: 1.14;
}

.mcp-source-action em,
.mcp-data-management-action em {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 22px;
    padding: 0 9px;
    border-radius: 6px;
    font-size: 0.62rem;
    font-style: normal;
    font-weight: 800;
    line-height: 1;
    white-space: nowrap;
    transition: all 0.2s ease;
}

.mcp-data-management-action em {
    min-width: 48px;
    border: 1px solid rgba(16, 163, 127, 0.24);
    background: #ecfdf5;
    color: var(--primary);
}

.mcp-source-action em.is-active {
    min-width: 48px;
    border: 1px solid rgba(16, 163, 127, 0.28);
    background: #ecfdf5;
    color: var(--primary);
}

.mcp-source-action em.is-active:hover {
    border-color: var(--primary);
    background: #10a37f;
    color: #ffffff;
    box-shadow: 0 2px 5px rgba(16, 163, 127, 0.12);
}

.mcp-source-action em:not(.is-active) {
    min-width: 48px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    background: #f8fafc;
    color: #64748b;
}

.mcp-source-action em:not(.is-active):hover {
    border-color: rgba(148, 163, 184, 0.36);
    background: #f1f5f9;
    color: #475569;
}

.mcp-source-action.is-disabled {
    cursor: not-allowed;
    background: #f8fafc;
    opacity: 0.82;
}

.mcp-source-action.is-disabled:hover {
    border-color: rgba(148, 163, 184, 0.16);
    background: #f8fafc;
}

.mcp-source-action.is-disabled em {
    border-color: rgba(148, 163, 184, 0.2);
    background: #f1f5f9;
    color: #94a3b8;
}

.mcp-data-management-panel {
    display: grid;
    grid-template-columns: 120px minmax(0, 1fr);
    align-items: center;
    gap: 8px;
    border-color: rgba(16, 163, 127, 0.18);
    background: linear-gradient(180deg, #f8fffc 0%, #ffffff 100%);
}

.mcp-data-management-head {
    border-right-color: rgba(16, 163, 127, 0.14);
}


.mcp-data-management-action {
    grid-template-columns: minmax(0, 1fr) auto;
    min-height: 46px;
    padding: 6px 8px;
    border-color: rgba(16, 163, 127, 0.16);
}

.mcp-data-management-action.is-primary {
    border-color: rgba(16, 163, 127, 0.28);
    background: linear-gradient(180deg, #ffffff 0%, #f6fffb 100%);
}


@media (max-width: 1280px) {
    .mcp-source-action-zone {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 900px) {
    .mcp-system-grid {
        grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    }

    .mcp-source-action-panel,
    .mcp-data-management-panel {
        grid-template-columns: 1fr;
    }

    .mcp-source-action-head,
    .mcp-data-management-head {
        padding: 0 2px;
        border-right: 0;
    }

    .mcp-source-action-list {
        grid-template-columns: 1fr;
    }

    .mcp-data-management-action {
        grid-template-columns: minmax(0, 1fr) auto;
    }
}

@media (max-width: 640px) {
    .mcp-system-grid {
        grid-template-columns: 1fr;
    }

    .mcp-server-main {
        grid-template-columns: 1fr;
        gap: 10px;
    }

    .mcp-card-actions {
        justify-content: flex-start;
    }
}
.mcp-source-action-zone {
    grid-template-columns: minmax(0, 1fr) minmax(360px, 1fr);
}

.mcp-data-management-panel {
    grid-template-columns: 120px minmax(0, 1fr);
    min-height: 60px;
}

.mcp-data-management-head span {
    display: block;
    overflow: visible;
    color: #0f766e;
    font-size: 0.62rem;
    font-weight: 800;
    line-height: 1.2;
    white-space: normal;
}

.mcp-data-management-action {
    grid-template-columns: minmax(0, 1fr) auto;
    min-height: 48px;
}

.mcp-data-management-action small {
    display: block;
    overflow: visible;
    color: #475569;
    font-size: 0.62rem;
    line-height: 1.28;
    white-space: normal;
    line-clamp: unset;
    -webkit-line-clamp: unset;
}

.mcp-other-tools-panel {
    grid-column: 1 / -1;
    min-width: 0;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 8px;
    background: #f8fafc;
}

.mcp-other-tools-panel summary {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
    min-height: 46px;
    padding: 7px 10px;
    cursor: pointer;
    list-style: none;
}

.mcp-other-tools-panel summary::-webkit-details-marker {
    display: none;
}

.mcp-other-tools-panel summary span {
    display: grid;
    gap: 2px;
    min-width: 0;
}

.mcp-other-tools-panel summary strong {
    overflow: hidden;
    color: var(--text-main);
    font-size: 0.76rem;
    font-weight: 800;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-other-tools-panel summary small {
    color: #64748b;
    font-size: 0.62rem;
    line-height: 1.25;
}

.mcp-other-tools-panel summary em {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 22px;
    padding: 0 8px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    border-radius: 999px;
    background: #ffffff;
    color: #475569;
    font-size: 0.62rem;
    font-style: normal;
    font-weight: 800;
    white-space: nowrap;
}

.mcp-other-tools-body {
    display: grid;
    gap: 6px;
    padding: 0 10px 9px;
}

.mcp-other-tools-body p,
.mcp-other-tools-body small {
    margin: 0;
    color: #64748b;
    font-size: 0.62rem;
    line-height: 1.3;
}

.mcp-other-tools-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 5px;
}

.mcp-other-tool-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: 6px;
    min-width: 0;
    padding: 5px 7px;
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 6px;
    background: #ffffff;
}

.mcp-other-tool-row strong,
.mcp-other-tool-row span,
.mcp-other-tool-row em {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-other-tool-row strong {
    color: var(--text-main);
    font-size: 0.68rem;
    font-weight: 800;
}

.mcp-other-tool-row span,
.mcp-other-tool-row em {
    color: #64748b;
    font-size: 0.58rem;
}

.mcp-other-tools-body .btn-secondary {
    justify-self: start;
    height: 24px;
    padding: 0 8px;
    font-size: 0.64rem;
}

@media (max-width: 900px) {
    .mcp-source-action-zone,
    .mcp-data-management-panel,
    .mcp-data-management-action,
    .mcp-other-tools-panel summary,
    .mcp-other-tool-row {
        grid-template-columns: 1fr;
    }
    .mcp-other-tools-panel summary em {
        justify-self: start;
    }
}
.mcp-source-action-main {
    display: contents;
}

.mcp-source-tool-btn {
    align-self: center;
    min-width: 76px;
    height: 28px;
    padding: 0 10px;
    border-radius: 8px;
    font-size: 0.72rem;
    font-weight: 700;
    white-space: nowrap;
}

/* --- 连接与安全凭据卡片样式 --- */
.mcp-card-slug {
    display: flex;
    align-items: center;
    gap: 6px;
    margin: 2px 0;
}

.mcp-card-slug code {
    font-family: 'JetBrains Mono', 'Fira Code', Consolas, monospace;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--primary);
    background: rgba(16, 163, 127, 0.08);
    border: 1px solid rgba(16, 163, 127, 0.2);
    border-radius: 4px;
    padding: 1px 6px;
}

.mcp-credential-manage-actions {
    display: flex;
    align-items: center;
    gap: 6px;
}

.mcp-credential-manage-actions .btn-primary,
.mcp-credential-manage-actions .btn-secondary,
.mcp-credential-manage-actions button {
    height: 24px !important;
    min-height: 24px !important;
    max-height: 24px !important;
    line-height: 22px !important;
    padding: 0 10px !important;
    font-size: 0.72rem !important;
