}


/* === styles/workspaces/mcp/mcp-call-logs.css === */
/* 拆自 workspaces/mcp.css。 */
/* MCP 服务调用日志、行内工具与通用操作按钮尺寸样式。 */
.mcp-server-call-logs {
    display: flex;
    flex-direction: column;
    gap: 6px;
    min-width: 0;
    width: 100%;
    max-width: 420px;
    align-content: start;
}

.mcp-call-log-title {
    color: #64748b;
    font-size: 0.66rem;
    font-weight: 700;
    letter-spacing: 0.03em;
    line-height: 1;
    margin-bottom: 2px;
}

.mcp-call-log {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    min-width: 0;
    height: 26px;
    padding: 0 10px;
    border: 1px solid rgba(148, 163, 184, 0.12);
    border-radius: 6px;
    background: #f8fafc;
    transition: all 0.2s ease;
    cursor: pointer;
}

.mcp-call-log:hover {
    background: #f1f5f9;
    border-color: rgba(148, 163, 184, 0.24);
    box-shadow: 0 2px 4px rgba(15, 23, 42, 0.02);
}

.mcp-call-log::before {
    content: '';
    display: inline-block;
    flex: 0 0 auto;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background-color: var(--primary);
    box-shadow: 0 0 0 2px rgba(16, 163, 127, 0.15);
}

.mcp-call-log.is-error::before {
    background-color: var(--danger);
    box-shadow: 0 0 0 2px rgba(239, 68, 68, 0.15);
}

.mcp-call-log strong {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    color: #334155;
    font-size: 0.68rem;
    font-weight: 500;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: left;
}

.mcp-call-log span {
    flex: 0 0 auto;
    margin-top: 0;
    color: var(--primary);
    font-size: 0.64rem;
    font-weight: 700;
    font-family: monospace, Consolas, Monaco;
    white-space: nowrap;
}

.mcp-call-log.is-error span {
    color: var(--danger);
}

.mcp-call-log small {
    display: none !important;
}

.mcp-call-log-empty {
    align-self: flex-start;
    height: 22px;
    padding: 0 10px;
    border: 1px dashed rgba(148, 163, 184, 0.28);
    border-radius: 6px;
    color: #64748b;
    background: #f8fafc;
    font-size: 0.68rem;
    font-weight: 600;
    line-height: 20px;
    white-space: nowrap;
}

.mcp-inline-tools {
    display: flex !important;
    flex-wrap: wrap;
    gap: 5px;
    margin-top: 8px;
}

.mcp-inline-tools span {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    max-width: 100%;
    min-height: 22px;
    margin: 0;
    padding: 2px 7px;
    overflow: hidden;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 7px;
    background: rgba(255, 255, 255, 0.78);
    color: var(--text-main);
    font-size: 0.68rem;
    font-weight: 800;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-inline-tools span em {
    overflow: hidden;
    color: var(--text-muted);
    font-size: 0.64rem;
    font-style: normal;
    font-weight: 700;
    text-overflow: ellipsis;
}

.mcp-inline-tools.empty {
    display: block !important;
    color: var(--text-muted);
    font-size: 0.68rem;
    font-weight: 700;
}

.mcp-card-actions .btn-secondary,
.mcp-card-actions .btn-danger-outline,
.workspace-modal .rag-actions .btn-secondary,
.workspace-modal .rag-actions .btn-danger {
    height: 28px;
    padding: 0 9px;
    font-size: 0.72rem;
    border-radius: 7px;
}

.knowledge-workspace-modal .rag-actions .btn-secondary,
.knowledge-workspace-modal .rag-actions .btn-danger {
    height: 22px;
    min-height: 22px;
    padding: 0 7px;
    font-size: 0.66rem;
    border-radius: 6px;
}

.error-text {
    color: var(--danger) !important;
}


/* === styles/workspaces/mcp/mcp-governance.css === */
/* MCP 治理指标、工作区布局与工具缓存卡片样式。 */
.mcp-primary-tabs {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 20px;
    min-height: 44px;
    padding: 0 20px;
    overflow-x: auto;
    border-bottom: 1px solid var(--border, #e2e8f0);
    background: #fff;
    scrollbar-width: none;
}

.mcp-primary-tabs::-webkit-scrollbar {
    display: none;
}

.mcp-primary-tab {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    align-self: stretch;
    flex: 0 0 auto;
    padding: 0 4px;
    border: 0;
    background: transparent;
    color: var(--text-muted, #64748b);
    font-size: 0.84rem;
    font-weight: 600;
    cursor: pointer;
    transition: color 0.15s ease;
}

.mcp-primary-tab::after {
    content: "";
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    height: 2.5px;
    border-radius: 2px 2px 0 0;
    background: transparent;
    transition: background 0.15s ease;
}

.mcp-primary-tab:hover {
    color: var(--text-main, #1e293b);
}

.mcp-primary-tab.active {
    color: var(--primary, #10a37f);
    font-weight: 700;
}

.mcp-primary-tab.active::after {
    background: var(--primary, #10a37f);
}

.mcp-tab-pane {
    display: flex;
    flex-direction: column;
    flex: 1 1 auto;
    min-height: 0;
    height: 100%;
}

.mcp-tab-pane.hidden {
    display: none !important;
}

.mcp-governance-panel {
    display: grid;
    grid-template-columns: minmax(220px, 1.2fr) minmax(0, 1.8fr);
    align-items: center;
    gap: 8px 16px;
    margin: 0 0 12px;
    padding: 10px 16px;
    min-height: 52px;
    background: linear-gradient(180deg, #ffffff 0%, #f9fcfb 100%);
    border: 1px solid rgba(16, 163, 127, 0.15);
    box-shadow: 0 4px 12px -2px rgba(15, 23, 42, 0.03), 0 1px 3px rgba(15, 23, 42, 0.01);
    border-radius: 10px;
    flex: 0 0 auto;
}

.mcp-governance-title {
    display: flex;
    align-items: center;
    justify-content: flex-start;
    gap: 12px;
    min-width: 0;
}

.mcp-governance-title > div {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
}

.mcp-governance-title strong {
    flex: 0 0 auto;
    color: var(--text-main);
    font-size: 0.88rem;
    font-weight: 800;
    letter-spacing: -0.01em;
}

.mcp-governance-title span {
    min-width: 0;
    overflow: hidden;
    color: #475569;
    font-size: 0.7rem;
    font-weight: 600;
    text-overflow: ellipsis;
    white-space: nowrap;
    background: #f1f5f9;
    padding: 3px 8px;
    border-radius: 6px;
    border: 1px solid rgba(148, 163, 184, 0.12);
}

.mcp-governance-title .btn-secondary {
    flex: 0 0 auto;
    height: 26px;
    padding: 0 10px;
    border-radius: 8px;
    font-size: 0.7rem;
    font-weight: 700;
    border-color: rgba(16, 163, 127, 0.25);
    color: var(--primary);
    background: #ffffff;
    box-shadow: 0 1px 2px rgba(16, 163, 127, 0.05);
    transition: all 0.2s ease;
}

.mcp-governance-title .btn-secondary:hover {
    background: #ecfdf5;
    border-color: var(--primary);
}

.mcp-governance-panel .governance-metrics,
.mcp-governance-panel .governance-list {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
    min-width: 0;
}

.mcp-governance-panel .governance-metrics {
    justify-content: flex-end;
}

.mcp-governance-panel .governance-list {
    grid-column: 1 / -1;
    margin-top: 6px;
    padding-top: 8px;
    border-top: 1px dashed rgba(16, 163, 127, 0.12);
    justify-content: flex-start;
    overflow: visible;
}

.mcp-governance-panel .governance-metrics span,
.mcp-governance-panel .governance-list span {
    display: inline-flex;
    align-items: center;
    min-height: 24px;
    padding: 2px 8px;
    font-size: 0.68rem;
    font-weight: 600;
    border-radius: 6px;
    border: 1px solid transparent;
    white-space: nowrap;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

.mcp-governance-panel .governance-metrics span {
    background-color: #f8fafc;
    border: 1px solid rgba(148, 163, 184, 0.18);
    color: #475569;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.02);
}

.mcp-governance-panel .governance-metrics span:hover {
    transform: translateY(-1px);
    border-color: rgba(148, 163, 184, 0.3);
    box-shadow: 0 3px 6px rgba(15, 23, 42, 0.04);
}

.mcp-governance-panel .governance-metrics span b {
    font-size: 0.8rem;
    font-weight: 800;
    margin-right: 4px;
    color: #1e293b;
}

.mcp-governance-panel .governance-metrics .btn-secondary,
.mcp-governance-panel .governance-metrics #mcp-refresh-btn,
.mcp-governance-panel .governance-metrics #mcp-health-check-btn {
    height: 24px;
    padding: 0 8px;
    border-radius: 6px;
    font-size: 0.68rem;
    font-weight: 700;
    border: 1px solid rgba(148, 163, 184, 0.24);
    color: #475569;
    background: #ffffff;
    cursor: pointer;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.02);
    transition: all 0.2s ease;
    margin-right: 4px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    white-space: nowrap;
    line-height: 1;
}

.mcp-governance-panel .governance-metrics .btn-secondary:hover,
.mcp-governance-panel .governance-metrics #mcp-refresh-btn:hover,
.mcp-governance-panel .governance-metrics #mcp-health-check-btn:hover {
    border-color: var(--primary);
    background: #ecfdf5;
    color: var(--primary);
    box-shadow: 0 3px 6px rgba(16, 163, 127, 0.06);
}

.mcp-governance-panel .governance-list span {
    max-width: none;
    background-color: #fffbeb;
    border: 1px solid rgba(245, 158, 11, 0.18);
    color: #b45309;
    font-size: 0.66rem;
    padding: 3px 10px;
    line-height: 1.35;
    border-radius: 6px;
    white-space: normal;
}

.mcp-governance-panel .governance-list span::before {
    content: '•';
    margin-right: 5px;
}

.mcp-governance-empty {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: var(--text-muted);
}

.mcp-governance-empty .btn-secondary {
    height: 24px;
    padding: 0 8px;
    font-size: 0.68rem;
}

.mcp-workbench-state {
    display: none !important;
}

.mcp-workbench-state.is-loading {
    border-color: rgba(59, 130, 246, 0.18);
    background: rgba(59, 130, 246, 0.1);
    color: #1d4ed8;
}

.mcp-workbench-state.is-error {
    border-color: rgba(220, 38, 38, 0.2);
    background: rgba(220, 38, 38, 0.1);
    color: #b91c1c;
}

.mcp-workbench-state .btn-secondary {
    flex: 0 0 auto;
    height: 26px;
    padding: 0 10px;
    font-size: 0.7rem;
}

.mcp-workspace-modal .workspace-modal-body {
    display: flex;
    flex-direction: column;
    padding: 10px 14px 12px;
    overflow: hidden;
}

.mcp-workspace-modal .mcp-layout {
    display: block;
    flex: 1 1 auto;
    min-height: 0;
    height: auto;
}

.mcp-list-wrap {
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 8px;
    min-height: 0;
    height: 100%;
    overflow: auto;
}

.mcp-tools-modal {
    width: min(1040px, calc(100vw - 32px));
    max-height: calc(100vh - 40px);
    padding: 0;
    overflow: hidden;
    text-align: left;
}

.mcp-tools-list {
    max-height: calc(100vh - 116px);
    padding: 14px 16px 16px;
    overflow: auto;
}

.mcp-tools-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 8px;
}

#mcp-tool-cache {
    display: none;
}

.mcp-tool-cache-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding-top: 2px;
    color: var(--text-main);
    font-size: 0.8rem;
    font-weight: 800;
}

.mcp-tool-cache-head span {
    display: inline-flex;
    align-items: center;
    height: 20px;
    padding: 0 7px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 999px;
    color: var(--text-muted);
    font-size: 0.68rem;
    font-weight: 700;
    white-space: nowrap;
}

.mcp-tool-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 8px;
}

.mcp-tool-card {
    display: grid;
    grid-template-rows: auto minmax(34px, auto) auto;
    gap: 5px;
    min-width: 0;
    min-height: 84px;
    padding: 8px 9px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 8px;
    background: #f8fafc;
}

.mcp-tool-card.is-disabled {
    opacity: 0.72;
    background: #f1f5f9;
}

.mcp-tool-card-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    min-width: 0;
}

.mcp-tool-card-head strong {
    min-width: 0;
    overflow: hidden;
    color: var(--text-main);
    font-size: 0.78rem;
    line-height: 1.3;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-tool-state {
    flex: 0 0 auto;
    padding: 2px 6px;
    border: 1px solid rgba(16, 163, 127, 0.22);
    border-radius: 6px;
    color: var(--primary);
    background: #ffffff;
    font-size: 0.64rem;
    font-weight: 800;
}

.mcp-tool-state.is-muted {
    border-color: rgba(148, 163, 184, 0.3);
    color: var(--text-muted);
}

.mcp-tool-card p {
    display: -webkit-box;
    margin: 0;
    overflow: hidden;
    color: var(--text-muted);
    font-size: 0.7rem;
    line-height: 1.45;
    -webkit-box-orient: vertical;
    line-clamp: 2;
    -webkit-line-clamp: 2;
}

.mcp-tool-meta {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 5px;
    min-width: 0;
}

.mcp-tool-meta span {
    display: inline-flex;
    align-items: center;
    min-width: 0;
    max-width: 100%;
    min-height: 20px;
    padding: 2px 7px;
    border: 1px solid rgba(16, 163, 127, 0.18);
    border-radius: 6px;
    background: rgba(255, 255, 255, 0.7);
    color: var(--primary);
    font-size: 0.66rem;
    font-family: Consolas, 'SFMono-Regular', monospace;
    font-weight: 800;
    line-height: 1.3;
    overflow-wrap: anywhere;
    white-space: normal;
    word-break: break-word;
}

.mcp-tool-meta .mcp-tool-owner {
    border-color: rgba(100, 116, 139, 0.18);
    color: #475569;
    background: #ffffff;
    font-family: inherit;
}

.mcp-tool-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 6px;
    margin-top: 4px;
}

.mcp-tool-test-btn {
    height: 22px;
    padding: 0 8px;
    font-size: 0.7rem;
    font-weight: 700;
}

.mcp-tool-test-modal {
    width: min(680px, calc(100vw - 32px));
    max-height: calc(100vh - 40px);
    display: flex;
    flex-direction: column;
    padding: 0;
    overflow: hidden;
    text-align: left;
}

.mcp-tool-test-body {
    flex: 1 1 auto;
    padding: 14px 18px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.mcp-tool-test-section {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.mcp-tool-test-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    font-size: 0.8rem;
}

.mcp-tool-test-actions {
    display: flex;
    align-items: center;
    gap: 6px;
}

.mcp-tool-test-actions button {
    height: 24px;
    padding: 0 8px;
    font-size: 0.72rem;
}

#mcp-tool-test-input,
.mcp-code-editor {
    font-family: var(--font-mono, Consolas, 'SFMono-Regular', 'Roboto Mono', Menlo, Monaco, monospace) !important;
    font-size: 0.78rem !important;
    line-height: 1.45 !important;
    padding: 8px 10px !important;
    border-radius: 6px !important;
    tab-size: 2;
    -moz-tab-size: 2;
    resize: vertical;
}

.mcp-tool-test-schema-hint {
    color: var(--text-muted);
    font-size: 0.72rem;
    line-height: 1.4;
}

.mcp-tool-test-status {
    font-size: 0.72rem;
    font-weight: 700;
}

.mcp-tool-test-status.success {
    color: #059669;
}

.mcp-tool-test-status.error {
    color: #dc2626;
}

.mcp-tool-test-result-box {
    margin: 0;
    padding: 10px 12px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 6px;
    background: #0f172a;
    color: #f8fafc;
    font-family: Consolas, 'SFMono-Regular', monospace;
    font-size: 0.76rem;
    line-height: 1.45;
    max-height: 220px;
    overflow: auto;
    white-space: pre-wrap;
    word-break: break-all;
}

.mcp-tool-test-footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    padding: 12px 18px;
    border-top: 1px solid rgba(148, 163, 184, 0.2);
    background: #f8fafc;
}


/* === styles/workspaces/mcp/mcp-local-auth.css === */
/* 工具库本机授权中心。 */
.mcp-local-auth-overlay {
    z-index: 1920;
}

.mcp-local-auth-modal {
    width: min(760px, calc(100vw - 32px));
    max-height: calc(100vh - 40px);
    padding: 0;
    overflow: hidden;
    text-align: left;
}

.mcp-local-auth-modal .mcp-edit-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
}

.mcp-local-auth-modal .mcp-edit-header p {
    margin: 4px 0 0;
    color: var(--text-muted);
    font-size: 0.76rem;
    line-height: 1.35;
}

.mcp-local-auth-body {
    display: grid;
    gap: 10px;
    max-height: calc(100vh - 128px);
    padding: 14px 16px 16px;
    overflow: auto;
}

.mcp-local-auth-summary {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
    padding: 9px 10px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--surface);
}

.mcp-local-auth-summary.is-ready {
    border-color: rgba(16, 163, 127, 0.2);
    background: #f8fffc;
}

.mcp-local-auth-summary.is-waiting {
    border-color: rgba(245, 158, 11, 0.24);
    background: #fffbeb;
}

.mcp-local-auth-summary div {
    display: grid;
    gap: 2px;
    min-width: 0;
}

.mcp-local-auth-summary strong {
    overflow: hidden;
    color: var(--text-main);
    font-size: 0.82rem;
    font-weight: 800;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.mcp-local-auth-summary span {
    color: var(--text-muted);
    font-size: 0.68rem;
    line-height: 1.35;
}

.mcp-local-auth-summary em {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 22px;
    padding: 0 8px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    border-radius: 999px;
    background: #ffffff;
    color: var(--text-main);
    font-size: 0.62rem;
    font-style: normal;
    font-weight: 800;
    white-space: nowrap;
}

.mcp-local-auth-tabs {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.mcp-local-auth-tabs .btn-secondary {
    min-height: 28px;
    padding: 0 10px;
    font-size: 0.68rem;
}

.mcp-local-auth-tabs .btn-secondary.active {
    border-color: rgba(16, 163, 127, 0.3);
    background: #ecfdf5;
    color: var(--primary);
}

.mcp-local-auth-list {
    display: grid;
    gap: 8px;
}

.mcp-local-auth-item {
    display: grid;
    gap: 8px;
    padding: 10px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: #ffffff;
}

.mcp-local-auth-item.is-authorized {
    border-color: rgba(16, 163, 127, 0.22);
}

.mcp-local-auth-item.is-unavailable {
    background: #f8fafc;
}

.mcp-local-auth-item header {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: start;
    gap: 10px;
}

.mcp-local-auth-item header div {
    display: grid;
    gap: 3px;
    min-width: 0;
}

.mcp-local-auth-item header strong {
    color: var(--text-main);
    font-size: 0.84rem;
    font-weight: 800;
}

.mcp-local-auth-item header p {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.68rem;
    line-height: 1.35;
}

.mcp-local-auth-item header em {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 22px;
    padding: 0 8px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    border-radius: 999px;
    background: #f8fafc;
    color: var(--text-main);
    font-size: 0.62rem;
    font-style: normal;
    font-weight: 800;
    white-space: nowrap;
}

.mcp-local-auth-item.is-authorized header em {
    border-color: rgba(16, 163, 127, 0.22);
    background: #ecfdf5;
    color: var(--primary);
}

.mcp-local-auth-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
}

.mcp-local-auth-tags span {
    display: inline-flex;
    align-items: center;
    min-height: 20px;
    padding: 0 6px;
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 6px;
    background: #f8fafc;
    color: var(--text-main);
