    }
    .session-search-scope {
        width: 100%;
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
    }
    .global-search-type {
        flex: 1;
        min-width: 0;
    }
    .global-search-result {
        grid-template-columns: minmax(0, 1fr);
        gap: 6px;
    }
    .session-batch-slot,
    .session-batch-toggle {
        width: auto;
    }
}

/* 图片全屏查看器样式 */
#image-viewer-modal {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(0, 0, 0, 0.85); backdrop-filter: blur(5px);
    z-index: 10000; display: flex; justify-content: center; align-items: center; cursor: zoom-out;
}
#image-viewer-modal.hidden { display: none; }
#image-viewer-modal img {
    max-width: 90%; max-height: 90%; object-fit: contain; border-radius: var(--radius-md);
    box-shadow: 0 10px 30px rgba(0,0,0,0.5); animation: zoomIn 0.2s ease-out;
}
.close-viewer {
    position: absolute; top: 20px; right: 30px; color: white;
    font-size: 40px; font-weight: bold; cursor: pointer; transition: color 0.2s;
}
.close-viewer:hover { color: #ccc; }


/* === styles/layout-refresh.css === */
/*
 * Pivot UI refresh
 *
 * This file intentionally only changes presentation. Existing ids, data
 * attributes and workspace containers remain untouched so the current
 * interaction and loading code keeps working as-is.
 */

:root {
    --ui-page: #f4f7f8;
    --ui-sidebar: #f8faf9;
    --ui-surface: #ffffff;
    --ui-ink: #14213d;
    --ui-muted: #64748b;
    --ui-line: #e2e8f0;
    --ui-primary: #059669;
    --ui-primary-soft: #e9f8f1;
    --ui-focus: rgba(5, 150, 105, 0.2);
}

#app {
    background: var(--ui-page);
}

/* The sidebar is a compact navigation surface, not a second content pane. */
.sidebar {
    --sidebar-width: 288px;
    background: var(--ui-sidebar);
    border-right: 1px solid var(--ui-line);
    box-shadow: 4px 0 20px rgba(15, 23, 42, 0.025);
}

.sidebar-header {
    position: relative;
    padding: 12px 14px 10px;
    border-bottom: 1px solid var(--ui-line);
    background: var(--ui-sidebar);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

.sidebar-header-mobile-bar {
    display: none;
}

@media (max-width: 720px) {
    .sidebar-header-mobile-bar {
        display: flex;
        justify-content: flex-end;
        margin-bottom: 6px;
    }
}

.sidebar-tools {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 0;
}

.sidebar-new-chat-btn {
    color: var(--ui-primary, #059669);
    background: var(--ui-primary-soft, #e9f8f1);
    font-weight: 600;
}

.sidebar-new-chat-btn:hover {
    color: var(--ui-primary-hover, #047857);
    background: rgba(5, 150, 105, 0.14);
}

.sidebar-new-chat-btn svg {
    color: var(--ui-primary, #059669);
}

.sidebar-tools-collapsed {
    display: none !important;
}

.sidebar-tool-btn {
    min-height: 36px;
    padding: 0 10px;
    border-radius: 8px;
    color: #334155;
    font-size: 0.82rem;
    font-weight: 500;
    transition: all 0.15s ease;
}

.sidebar-tool-btn:hover,
.sidebar-tool-btn.active {
    color: var(--ui-primary);
    background: var(--ui-primary-soft);
}

.sidebar-tool-btn.active {
    font-weight: 700;
    box-shadow: inset 3px 0 0 var(--ui-primary);
}

.sidebar-tool-btn svg {
    width: 16px;
    height: 16px;
}

.sidebar-search-trigger {
    display: flex;
    align-items: center;
    width: 100%;
}

.sidebar-search-trigger span {
    flex: 1;
    text-align: left;
}

.sidebar-session-section-label {
    padding: 16px 16px 7px;
    color: #94a3b8;
    font-size: 0.66rem;
    letter-spacing: 0.04em;
}

.session-list {
    gap: 2px;
    padding: 4px 10px 16px;
    flex: 1;
    min-height: 0;
}

.session-date-group {
    padding: 12px 8px 4px;
}

.session-item {
    min-height: 38px;
    padding: 7px 9px;
    border-radius: 8px;
}

.session-item.active {
    background: #e9f8f1;
}

.session-item.active::before {
    width: 3px;
    top: 24%;
    bottom: 24%;
}

.sidebar-footer {
    display: none !important;
}

.footer-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 6px;
    align-items: stretch;
}

.footer-mini-btn {
    height: 30px;
    border-color: #dbe3ea;
    border-radius: 7px;
    background: var(--ui-surface);
    font-size: 0.7rem;
    box-shadow: none;
}

.footer-mini-btn:hover {
    background: var(--ui-primary-soft);
    border-color: rgba(5, 150, 105, 0.3);
}

.footer-user {
    width: 100%;
    height: auto;
    min-height: 30px;
    padding-inline: 2px;
}

.user-name-text {
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
    overflow-wrap: anywhere;
    line-height: 1.25;
}

.footer-btns {
    justify-content: flex-start;
    gap: 5px;
}

/* Main content gets a quiet page background and a clear, stable header. */
.chat-container {
    background: var(--ui-page);
}

.chat-container[data-active-workspace="agent"],
.chat-container[data-active-workspace="agent-dag"],
.chat-container[data-active-workspace="apps"],
.chat-container[data-active-workspace="knowledge"],
.chat-container[data-active-workspace="mcp"],
.chat-container[data-active-workspace="manual"],
.chat-container[data-active-workspace="print"],
.chat-container[data-active-workspace="settings"] {
    background: var(--ui-page);
}

.chat-header {
    flex: 0 0 58px;
    min-height: 58px;
    padding: 0 24px;
    background: rgba(255, 255, 255, 0.86);
    border-bottom-color: var(--ui-line);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
}

.chat-header .header-left {
    gap: 10px !important;
}

.icon-btn {
    width: 32px;
    height: 32px;
    padding: 0;
    border-radius: 8px;
}

.icon-btn:hover {
    background: var(--ui-primary-soft);
}

#current-title {
    color: var(--ui-ink);
    font-size: 0.96rem;
    letter-spacing: 0;
}

.message-container {
    gap: 12px;
    padding: 20px 24px 218px;
    background: var(--ui-page);
}

.message-container > .message {
    width: 100%;
    margin-inline: 0;
}

.message-content {
    max-width: min(92%, 960px);
    border-radius: 14px;
    box-shadow: 0 1px 1px rgba(15, 23, 42, 0.025);
}

/* The composer is the primary action, so it has one consistent visual frame. */
.input-area {
    padding: 16px clamp(16px, 5vw, 72px) 22px;
    background: linear-gradient(transparent, rgba(244, 247, 248, 0.94) 34%, var(--ui-page) 100%);
}

.input-wrapper {
    max-width: min(960px, calc(100% - 16px));
    border-color: #d8e1e8;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.98);
    box-shadow: 0 12px 28px rgba(15, 23, 42, 0.08), 0 1px 2px rgba(15, 23, 42, 0.04);
}

.input-wrapper:focus-within {
    border-color: rgba(5, 150, 105, 0.5);
    box-shadow: 0 14px 30px rgba(15, 23, 42, 0.1), 0 0 0 4px var(--ui-focus);
}

.input-wrapper textarea {
    min-height: 54px;
    height: 54px;
    padding: 14px 16px 7px;
    font-size: 0.86rem;
}

.input-actions {
    padding: 4px 12px 10px;
}

.input-wrapper .btn-primary,
.input-wrapper #stop-btn {
    width: 34px;
    height: 34px;
    flex-basis: 34px;
}

/* All full-page workspaces share the exact same rhythm and header dimensions to prevent layout jump. */
.workspace-modal-header,
.agent-modal-header,
.agent-dag-modal-header {
    height: 64px;
    min-height: 64px;
    max-height: 64px;
    padding: 12px 20px;
    background: #ffffff;
    border-bottom: 1px solid var(--border);
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
}

.workspace-modal-header > div,
.agent-modal-header > div,
.agent-dag-modal-header > div {
    min-width: 0;
}

.workspace-modal-header h3,
.agent-modal-header h3,
.agent-dag-modal-header h3 {
    margin: 0 0 3px;
    font-size: 1.05rem;
    font-weight: 800;
    line-height: 1.25;
    color: var(--text-main);
}

.workspace-modal-header p,
.agent-modal-header p,
.agent-dag-modal-header p {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.76rem;
    line-height: 1.35;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.workspace-modal-body,
.agent-modal > .agent-workbench {
    padding: 16px 20px 20px;
    background: var(--ui-page);
}

.workspace-panel,
.mcp-form,
.mcp-list-wrap,
.agent-history-panel {
    border-color: var(--ui-line);
    border-radius: 10px;
    box-shadow: 0 5px 16px rgba(15, 23, 42, 0.035);
}

.agent-modal-header-actions,
.agent-dag-header-actions {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    flex: 0 0 auto;
}

.workspace-toolbar .btn-primary,
.workspace-toolbar .btn-secondary,
.agent-modal-header-actions > button,
.agent-dag-header-actions > button,
.workspace-modal-close,
.agent-modal-close {
    height: 34px;
    min-height: 34px;
    padding: 0 14px;
    border-radius: 7px;
    font-size: 0.8rem;
    font-weight: 600;
    box-sizing: border-box;
}

.automation-primary-tabs {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 24px;
    height: 43px;
    min-height: 43px;
    max-height: 43px;
    padding: 0 20px;
    overflow-x: auto;
    border-bottom: 1px solid var(--border);
    background: #fff;
    box-sizing: border-box;
    scrollbar-width: none;
}

/* Task workbench: master list and immersive detail view */
#agent-tasks-view {
    display: flex;
    flex-direction: column;
    flex: 1 1 auto;
    height: calc(100vh - 107px);
    min-height: 0;
    overflow: hidden;
    padding: 14px 18px 18px;
    background: #f8fafc;
    box-sizing: border-box;
}

#agent-tasks-view .agent-history-panel {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    min-height: 0;
    padding: 14px;
    border-color: var(--ui-line);
    border-radius: 10px;
    background: var(--ui-surface);
    box-shadow: 0 5px 16px rgba(15, 23, 42, 0.035);
}

#agent-tasks-view .agent-history-head {
    align-items: center;
    padding: 0 0 12px;
    border-bottom-color: var(--ui-line);
}

#agent-tasks-view .agent-history-head h3 {
    color: var(--ui-ink);
    font-size: 0.96rem;
}

#agent-tasks-view .agent-history-head p {
    color: var(--ui-muted);
}

#agent-tasks-view .agent-history-tools {
    flex-wrap: wrap;
    justify-content: flex-end;
}

#agent-tasks-view .agent-history-tools .btn-secondary {
    border-color: #dbe3ea;
    background: #fbfdfd;
}

#agent-tasks-view .agent-history-toolbar {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    margin: 0 0 12px;
    padding: 10px;
    border: 1px solid #e6edf1;
    border-radius: 8px;
    background: #f8fafb;
}

#agent-tasks-view .agent-metrics {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 8px;
    min-height: 0;
    margin: 0;
}

#agent-tasks-view .agent-metrics span {
    min-width: 0;
    height: 34px;
    justify-content: center;
    padding: 0 8px;
    overflow: hidden;
    border-color: #dce8e2;
    border-radius: 7px;
    background: var(--ui-surface);
    color: #3f5d51;
    font-size: 0.72rem;
    text-overflow: ellipsis;
    white-space: nowrap;
}

#agent-tasks-view .agent-history-filters {
    width: 100%;
    grid-template-columns: 132px 132px minmax(0, 1fr);
}

#agent-tasks-view .agent-history-filters .form-input {
    border-color: #dbe3ea;
    background: var(--ui-surface);
}

#agent-tasks-view .agent-runs-list {
    border-color: var(--ui-line);
    border-radius: 8px;
    background: #fff;
}

#agent-tasks-view .agent-runs-table th {
    background: #f8fafb;
    color: #526274;
}

#agent-tasks-view .agent-runs-table tbody tr.active,
#agent-tasks-view .agent-runs-table tbody tr:hover {
    background: var(--ui-primary-soft);
}

/* Opening a run keeps the activity list in context and turns the old modal into a drawer. */
#agent-run-detail-modal {
    align-items: stretch;
    justify-content: flex-end;
    padding: 16px;
    background: rgba(15, 23, 42, 0.18);
    backdrop-filter: blur(3px);
    -webkit-backdrop-filter: blur(3px);
}

#agent-run-detail-modal .agent-run-detail-modal {
    width: min(560px, 100%);
    height: 100%;
    max-height: none;
    border-radius: 12px;
    box-shadow: -18px 0 44px rgba(15, 23, 42, 0.15), 0 18px 48px rgba(15, 23, 42, 0.16);
    animation: agent-workbench-drawer-in 0.22s ease-out;
}

#agent-run-detail-modal .agent-run-detail {
    padding: 16px 18px 24px;
}

@keyframes agent-workbench-drawer-in {
    from { opacity: 0; transform: translateX(24px); }
    to { opacity: 1; transform: translateX(0); }
}

@media (max-width: 720px) {
    .sidebar {
        --sidebar-width: min(304px, calc(100vw - 32px));
    }

    .chat-header {
        padding: 0 14px;
    }

    .message-container {
        padding: 20px 14px 188px;
    }

    .message-container > .message {
        width: 100%;
    }

    .message-content {
        max-width: calc(100% - 44px);
    }

    .input-area {
        padding: 10px 10px calc(12px + env(safe-area-inset-bottom));
    }

    .input-wrapper {
        max-width: 100%;
        border-radius: 13px;
    }

    .workspace-modal-header,
    .agent-modal-header {
        min-height: 58px;
        padding: 12px 14px 10px;
    }

    .workspace-modal-header p,
    .agent-modal-header p {
        display: none;
    }

    .workspace-modal-body,
    .agent-modal > .agent-workbench {
        padding: 12px 10px 14px;
    }

    #agent-tasks-view {
        gap: 10px;
    }

    #agent-tasks-view .agent-history-panel {
        padding: 10px;
    }

    #agent-tasks-view .agent-history-head {
        align-items: stretch;
    }

    #agent-tasks-view .agent-history-tools {
        justify-content: flex-start;
    }

    #agent-tasks-view .agent-metrics {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    #agent-tasks-view .agent-history-filters {
        grid-template-columns: 1fr;
    }

    #agent-run-detail-modal {
        padding: 0;
    }

    #agent-run-detail-modal .agent-run-detail-modal {
        width: 100%;
        height: 100%;
        border-radius: 0;
    }
}

@media (prefers-reduced-motion: reduce) {
    .sidebar,
    .session-item,
    .sidebar-tool-btn,
    .new-chat-circle-btn,
    .input-wrapper {
        transition: none;
    }
}
